const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, HeadingLevel,
  VerticalAlign, PageBreak, ImageRun, UnderlineType
} = require('docx');
const fs = require('fs');
const { createCanvas } = require('canvas');

// Colors
const HEADER_BLUE = "2E5FA3";
const HEADER_LIGHT = "D6E4F0";
const SUB_HEADER = "BDD7EE";
const WHITE = "FFFFFF";
const BORDER_COLOR = "4472C4";

const border = { style: BorderStyle.SINGLE, size: 4, color: BORDER_COLOR };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function boldCell(text, fill = HEADER_LIGHT, colSpan = 1, width = 4680) {
  return new TableCell({
    borders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 150, right: 120 },
    columnSpan: colSpan,
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({ text, bold: true, size: 20, color: "000000" })]
    })]
  });
}

function plainCell(text, width = 6840, fill = WHITE) {
  return new TableCell({
    borders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 150, right: 120 },
    children: [new Paragraph({
      children: [new TextRun({ text, size: 20 })]
    })]
  });
}

function headerRow(title) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: HEADER_BLUE, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 150, right: 120 },
        columnSpan: 2,
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: title, bold: true, size: 22, color: WHITE })]
        })]
      })
    ]
  });
}

function twoColRow(label, value, labelW = 2520, valueW = 6840, labelFill = HEADER_LIGHT) {
  return new TableRow({
    children: [boldCell(label, labelFill, 1, labelW), plainCell(value, valueW)]
  });
}

function sectionRow(title) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: SUB_HEADER, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 150, right: 120 },
        columnSpan: 2,
        children: [new Paragraph({
          children: [new TextRun({ text: title, bold: true, size: 20 })]
        })]
      })
    ]
  });
}

function fullRow(text) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 150, right: 120 },
        columnSpan: 2,
        children: [new Paragraph({ children: [new TextRun({ text, size: 20 })] })]
      })
    ]
  });
}

function colHeaderRow(col1, col2) {
  return new TableRow({
    children: [boldCell(col1, SUB_HEADER, 1, 4680), boldCell(col2, SUB_HEADER, 1, 4680)]
  });
}

function twoEqualRow(left, right) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 150, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: left, size: 20 })] })]
      }),
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 150, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: right, size: 20 })] })]
      })
    ]
  });
}

function kondisiRow(label, text) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 9360, type: WidthType.DXA },
        columnSpan: 2,
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 150, right: 120 },
        children: [new Paragraph({
          children: [
            new TextRun({ text: label + " ", bold: true, size: 20 }),
            new TextRun({ text, size: 20 })
          ]
        })]
      })
    ]
  });
}

function buildScenarioTable(uc) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: [
      headerRow("Identifikasi"),
      twoColRow("Nomor", uc.nomor),
      twoColRow("Nama", uc.nama),
      twoColRow("Tujuan", uc.tujuan),
      twoColRow("Deskripsi", uc.deskripsi),
      twoColRow("Aktor", uc.aktor),
      sectionRow("Skenario Utama"),
      kondisiRow("Kondisi awal", uc.kondisiAwal),
      colHeaderRow("Aksi Aktor", "Reaksi Sistem"),
      ...uc.utama.map(([a, r]) => twoEqualRow(a, r)),
      sectionRow("Skenario Alternatif"),
      colHeaderRow("Aksi Aktor", "Reaksi Sistem"),
      ...uc.alternatif.map(([a, r]) => twoEqualRow(a, r)),
      kondisiRow("Kondisi akhir", uc.kondisiAkhir),
    ]
  });
}

