// ─── Build sequence diagram as SVG PNG buffer ─────────────────────────────────

const { createCanvas: cc } = require('canvas');

function buildSequenceDiagram(interaksi) {
  const actors = interaksi.actors;
  const steps = interaksi.steps;
  const numActors = actors.length;
  const W = 680;
  const colW = W / numActors;
  const headerH = 70;
  const stepH = 48;
  const H = headerH + steps.length * stepH + 40;

  const canvas = cc(W, H);
  const ctx = canvas.getContext('2d');

  // Background
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  // Actor x positions (center of each column)
  const ax = actors.map((_, i) => colW * i + colW / 2);

  // Draw actor boxes
  actors.forEach((name, i) => {
    const x = ax[i];
    ctx.fillStyle = '#2E5FA3';
    ctx.beginPath();
    ctx.roundRect(x - 60, 10, 120, 36, 6);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 13px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(name, x, 28);
  });

  // Draw lifelines
  actors.forEach((_, i) => {
    const x = ax[i];
    ctx.setLineDash([5, 4]);
    ctx.strokeStyle = '#4472C4';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, 46);
    ctx.lineTo(x, H - 10);
    ctx.stroke();
    ctx.setLineDash([]);
  });

  // Draw steps
  steps.forEach((step, idx) => {
    const y = headerH + idx * stepH + stepH / 2;
    const x1 = ax[step.from];
    const x2 = ax[step.to];
    const isSelf = step.from === step.to;

    ctx.strokeStyle = '#1a3a7a';
    ctx.lineWidth = 1.5;

    if (isSelf) {
      // Self-loop
      const lx = x1 + 20;
      ctx.beginPath();
      ctx.moveTo(x1, y - 10);
      ctx.lineTo(lx + 25, y - 10);
      ctx.lineTo(lx + 25, y + 10);
      ctx.lineTo(x1, y + 10);
      ctx.stroke();
      // Arrow
      ctx.beginPath();
      ctx.moveTo(x1 + 8, y + 10 - 5);
      ctx.lineTo(x1, y + 10);
      ctx.lineTo(x1 + 8, y + 10 + 5);
      ctx.stroke();
      ctx.fillStyle = '#1a3a7a';
      ctx.font = '10px Arial';
      ctx.textAlign = 'left';
      ctx.fillText(step.label, lx + 27, y);
    } else {
      // Arrow line
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.stroke();
      // Arrowhead
      const dir = x2 > x1 ? 1 : -1;
      ctx.fillStyle = '#1a3a7a';
      ctx.beginPath();
      ctx.moveTo(x2, y);
      ctx.lineTo(x2 - dir * 9, y - 5);
      ctx.lineTo(x2 - dir * 9, y + 5);
      ctx.closePath();
      ctx.fill();
      // Label
      const midX = (x1 + x2) / 2;
      ctx.fillStyle = '#1a3a7a';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(step.label, midX, y - 6);
    }

    // Step number circle
    ctx.fillStyle = '#D6E4F0';
    ctx.beginPath();
    ctx.arc(x1, y, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#2E5FA3';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = '#1a3a7a';
    ctx.font = 'bold 8px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText((idx + 1).toString(), x1, y);
  });

  return canvas.toBuffer('image/png');
}

// ─── Build document ────────────────────────────────────────────────────────────

const sectionTitle = (text) => new Paragraph({
  spacing: { before: 300, after: 160 },
  children: [new TextRun({ text, bold: true, size: 28, color: HEADER_BLUE })]
});

const subTitle = (text) => new Paragraph({
  spacing: { before: 240, after: 120 },
  children: [new TextRun({ text, bold: true, size: 24, underline: { type: UnderlineType.SINGLE } })]
});

const spacer = () => new Paragraph({ spacing: { before: 120, after: 120 }, children: [new TextRun("")] });

// Build all content
const allChildren = [
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 400 },
    children: [new TextRun({ text: "SKENARIO DAN INTERAKSI OBJEK", bold: true, size: 36, color: HEADER_BLUE })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 600 },
    children: [new TextRun({ text: "Sistem Rekrutmen PT Eco Green Oleochemicals", size: 24, color: "444444" })]
  }),
];

useCases.forEach((uc, idx) => {
  allChildren.push(sectionTitle(`3.${idx + 1} Fitur ${uc.nomor.replace('UC-', '')}: ${uc.nama}`));
  allChildren.push(subTitle(`3.${idx + 1}.1 Skenario`));
  allChildren.push(buildScenarioTable(uc));
  allChildren.push(spacer());
  allChildren.push(subTitle(`3.${idx + 1}.2 Interaksi Objek`));

  const imgBuf = buildSequenceDiagram(uc.interaksi);
  const stepsCount = uc.interaksi.steps.length;
  const imgH = Math.round((70 + stepsCount * 48 + 40) * (5760 / 680));

  allChildren.push(new Paragraph({
    spacing: { before: 80, after: 200 },
    children: [
      new ImageRun({
        data: imgBuf,
        transformation: { width: 560, height: Math.round(560 * (70 + stepsCount * 48 + 40) / 680) },
        type: "png"
      })
    ]
  }));

  if (idx < useCases.length - 1) {
    allChildren.push(new Paragraph({ children: [new PageBreak()] }));
  }
});

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22 } }
    }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1080, bottom: 1440, left: 1440 }
      }
    },
    children: allChildren
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/skenario_rekrutmen.docx', buf);
  console.log('Done!');
});
