  const num = `3.${idx + 1}`;

  // Section heading
  allChildren.push(new Paragraph({
    spacing: { before: 200, after: 140 },
    children: [new TextRun({ text: `${num} Fitur ${uc.nomor.replace('UC-', '')}: ${uc.nama}`, bold: true, size: 28, color: HEADER_BLUE })]
  }));

  // Skenario subsection
  allChildren.push(new Paragraph({
    spacing: { before: 160, after: 120 },
    children: [new TextRun({ text: `${num}.1 Skenario`, bold: true, size: 24, underline: { type: UnderlineType.SINGLE } })]
  }));

  allChildren.push(buildScenarioTable(uc));
  allChildren.push(spacer());

  // Interaksi Objek subsection
  allChildren.push(new Paragraph({
    spacing: { before: 160, after: 120 },
    children: [new TextRun({ text: `${num}.2 Interaksi Objek`, bold: true, size: 24, underline: { type: UnderlineType.SINGLE } })]
  }));

  const imgData = fs.readFileSync(`/home/claude/${uc.img}`);
  const scaledH = Math.round(520 * uc.imgH / 720);

  allChildren.push(new Paragraph({
    spacing: { before: 80, after: 200 },
    children: [new ImageRun({
      data: imgData,
      transformation: { width: 520, height: scaledH },
      type: "png"
    })]
  }));

