const days = [
  {
    day: "Rabu",
    date: "8 Apr",
    isClass: true,
    meals: [
      { time: "Pagi", menu: "Roti tawar (2 lbr) + Telur ceplok + Teh manis", note: "Masak sendiri", price: 10000 },
      { time: "Siang", menu: "Nasi warteg — nasi + ayam/ikan + sayur", note: "Di luar (kuliah)", price: 20000 },
      { time: "Malam", menu: "Nasi + Sarden kaleng + Tempe goreng", note: "Masak sendiri", price: 15000 },
    ],
  },
  {
