    date: "9 Apr",
    isClass: false,
    meals: [
      { time: "Pagi", menu: "Oatmeal sachet + Telur rebus + Teh", note: "Masak sendiri", price: 10000 },
      { time: "Siang", menu: "Nasi + Telur dadar + Tumis kangkung + Tahu", note: "Masak sendiri", price: 15000 },
      { time: "Malam", menu: "Nasi + Ikan asin + Tempe goreng + Sayur bening", note: "Masak sendiri", price: 15000 },
    ],
  },
  {
    day: "Jumat",
    date: "10 Apr",
    isClass: false,
    meals: [
      { time: "Pagi", menu: "Roti tawar + Telur ceplok + Susu sachet", note: "Masak sendiri", price: 10000 },
      { time: "Siang", menu: "Nasi + Kornet kaleng + Telur + Wortel tumis", note: "Masak sendiri", price: 15000 },
      { time: "Malam", menu: "Mie instan + Telur + Sayur kangkung", note: "Masak sendiri", price: 10000 },
    ],
  },
  {
    day: "Sabtu",
    date: "11 Apr",
    isClass: false,
    meals: [
      { time: "Pagi", menu: "Nasi + Telur ceplok + Kecap + Teh", note: "Masak sendiri", price: 8000 },
      { time: "Siang", menu: "Nasi + Sarden kaleng + Tahu goreng + Sayur", note: "Masak sendiri", price: 15000 },
      { time: "Malam", menu: "Nasi + Ayam goreng (beli mentah, masak langsung)", note: "Beli & masak sore", price: 20000 },
    ],
  },
  {
    day: "Minggu",
    date: "12 Apr",
    isClass: false,
    meals: [
      { time: "Pagi", menu: "Oatmeal + Telur rebus + Teh manis", note: "Masak sendiri", price: 10000 },
      { time: "Siang", menu: "Nasi + Tempe orek + Telur + Wortel tumis", note: "Masak sendiri", price: 15000 },
      { time: "Malam", menu: "Nasi + Sarden + Tahu goreng + Sayur bayam", note: "Masak sendiri", price: 15000 },
    ],
  },
  {
    day: "Senin",
    date: "13 Apr",
    isClass: true,
    meals: [
      { time: "Pagi", menu: "Roti tawar + Telur ceplok + Teh", note: "Masak sendiri", price: 10000 },
      { time: "Siang", menu: "Nasi warteg — nasi + lauk + sayur", note: "Di luar (kuliah)", price: 20000 },
      { time: "Malam", menu: "Nasi + Ikan asin + Tempe + Tahu goreng", note: "Masak sendiri", price: 15000 },
    ],
  },
  {
    day: "Selasa",
    date: "14 Apr",
    isClass: true,
