      { time: "Pagi", menu: "Roti tawar + Telur + Susu sachet", note: "Masak sendiri", price: 10000 },
      { time: "Siang", menu: "Nasi warteg — nasi + lauk + sayur", note: "Di luar (kuliah)", price: 20000 },
      { time: "Malam", menu: "Nasi + Kornet kaleng + Sayur tumis", note: "Masak sendiri", price: 15000 },
    ],
  },
];

const mealColors = {
  Pagi: { bg: "#FFF8E7", accent: "#F59E0B", emoji: "🌅" },
  Siang: { bg: "#FFF1F0", accent: "#EF4444", emoji: "☀️" },
  Malam: { bg: "#EEF2FF", accent: "#6366F1", emoji: "🌙" },
};

function formatRupiah(n) {
  return "Rp " + n.toLocaleString("id-ID");
}

export default function MealPlan() {
  const [activeDay, setActiveDay] = useState(0);
  const totalAll = days.reduce((sum, d) => sum + d.meals.reduce((s, m) => s + m.price, 0), 0);
  const dayTotal = days[activeDay].meals.reduce((s, m) => s + m.price, 0);

  return (
    <div style={{
      fontFamily: "'Nunito', sans-serif",
      background: "linear-gradient(135deg, #f0fdf4 0%, #ecfdf5 50%, #f0f9ff 100%)",
      minHeight: "100vh",
      padding: "24px 16px",
    }}>
      <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&display=swap" rel="stylesheet" />

      {/* Header */}
      <div style={{ textAlign: "center", marginBottom: 28 }}>
        <div style={{ fontSize: 13, fontWeight: 700, letterSpacing: 3, color: "#059669", textTransform: "uppercase", marginBottom: 6 }}>
          🏠 Menu Anak Kos Batam • Tanpa Kulkas
        </div>
        <h1 style={{ fontSize: 26, fontWeight: 900, color: "#064e3b", margin: "0 0 6px" }}>
          Rencana Makan Seminggu
        </h1>
        <p style={{ fontSize: 13, color: "#6b7280", margin: 0 }}>
          8 – 14 April 2026 &nbsp;·&nbsp; Total Budget&nbsp;
          <span style={{ fontWeight: 800, color: "#059669" }}>{formatRupiah(totalAll)}</span>
        </p>
      </div>

      {/* Day Tabs */}
      <div style={{
        display: "flex", gap: 8, overflowX: "auto", paddingBottom: 4,
        marginBottom: 20, scrollbarWidth: "none",
      }}>
        {days.map((d, i) => (
          <button
            key={i}
            onClick={() => setActiveDay(i)}
            style={{
              flexShrink: 0,
              padding: "8px 14px",
              borderRadius: 12,
              border: "none",
              cursor: "pointer",
              fontFamily: "inherit",
              fontWeight: 700,
              fontSize: 13,
              transition: "all 0.18s",
              background: activeDay === i ? "#059669" : "white",
              color: activeDay === i ? "white" : "#374151",
              boxShadow: activeDay === i
                ? "0 4px 14px rgba(5,150,105,0.35)"
                : "0 1px 4px rgba(0,0,0,0.08)",
              transform: activeDay === i ? "translateY(-2px)" : "none",
            }}
          >
            <div>{d.day}</div>
            <div style={{ fontSize: 11, opacity: 0.8, fontWeight: 600 }}>{d.date}</div>
            {d.isClass && (
              <div style={{
                fontSize: 9, marginTop: 2,
                background: activeDay === i ? "rgba(255,255,255,0.25)" : "#dcfce7",
                color: activeDay === i ? "white" : "#15803d",
                borderRadius: 4, padding: "1px 4px", fontWeight: 800, letterSpacing: 0.5
              }}>KULIAH</div>
            )}
          </button>
        ))}
      </div>

      {/* Day Card */}
      {(() => {
        const d = days[activeDay];
        return (
          <div>
            {/* Day header */}
            <div style={{
              background: "white",
              borderRadius: 16,
              padding: "16px 20px",
              marginBottom: 12,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
            }}>
              <div>
                <div style={{ fontWeight: 900, fontSize: 20, color: "#064e3b" }}>
                  {d.day}, {d.date}
                </div>
                <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>
                  {d.isClass ? "📚 Hari kuliah — makan siang di luar" : "🏠 Hari bebas — masak sendiri"}
                </div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: 11, color: "#9ca3af", fontWeight: 600 }}>Total hari ini</div>
                <div style={{ fontWeight: 900, fontSize: 18, color: "#059669" }}>{formatRupiah(dayTotal)}</div>
              </div>
            </div>

            {/* Meals */}
            {d.meals.map((m, mi) => {
              const c = mealColors[m.time];
              return (
                <div key={mi} style={{
                  background: "white",
                  borderRadius: 14,
                  marginBottom: 10,
                  overflow: "hidden",
                  boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
                  display: "flex",
                }}>
                  {/* Left accent */}
                  <div style={{
                    width: 64, background: c.bg,
                    display: "flex", flexDirection: "column",
                    alignItems: "center", justifyContent: "center",
                    padding: "14px 8px", flexShrink: 0,
                  }}>
                    <div style={{ fontSize: 22 }}>{c.emoji}</div>
                    <div style={{ fontSize: 11, fontWeight: 800, color: c.accent, marginTop: 4 }}>{m.time}</div>
                  </div>

                  {/* Content */}
                  <div style={{ padding: "14px 16px", flex: 1 }}>
                    <div style={{ fontWeight: 700, fontSize: 14, color: "#1f2937", lineHeight: 1.4 }}>
                      {m.menu}
                    </div>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 8 }}>
                      <span style={{
                        fontSize: 11, fontWeight: 700,
                        background: m.note.includes("luar") ? "#fef3c7" : "#dcfce7",
                        color: m.note.includes("luar") ? "#92400e" : "#166534",
                        padding: "2px 8px", borderRadius: 6,
                      }}>
                        {m.note.includes("luar") ? "🍽️" : "🍳"} {m.note}
                      </span>
                      <span style={{ fontWeight: 800, fontSize: 14, color: "#374151" }}>
                        {formatRupiah(m.price)}
                      </span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        );
      })()}

      {/* Weekly Summary */}
      <div style={{
        background: "linear-gradient(135deg, #064e3b, #065f46)",
        borderRadius: 16, padding: "20px",
        marginTop: 20, color: "white",
        boxShadow: "0 8px 24px rgba(6,78,59,0.3)",
      }}>
        <div style={{ fontWeight: 900, fontSize: 16, marginBottom: 14, letterSpacing: 0.5 }}>
          📊 Ringkasan Budget Mingguan
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 14 }}>
          {days.map((d, i) => (
            <div key={i} style={{
              background: "rgba(255,255,255,0.1)",
              borderRadius: 10, padding: "10px 12px",
              display: "flex", justifyContent: "space-between", alignItems: "center",
              cursor: "pointer",
              border: activeDay === i ? "2px solid rgba(255,255,255,0.5)" : "2px solid transparent",
            }} onClick={() => setActiveDay(i)}>
              <div>
                <div style={{ fontWeight: 800, fontSize: 13 }}>{d.day}</div>
                <div style={{ fontSize: 10, opacity: 0.7 }}>{d.isClass ? "Kuliah" : "Libur"}</div>
              </div>
              <div style={{ fontWeight: 800, fontSize: 13, color: "#6ee7b7" }}>
                {formatRupiah(d.meals.reduce((s, m) => s + m.price, 0))}
              </div>
            </div>
          ))}
        </div>
        <div style={{
          borderTop: "1px solid rgba(255,255,255,0.2)",
          paddingTop: 14,
          display: "flex", justifyContent: "space-between", alignItems: "center"
        }}>
          <div>
            <div style={{ fontWeight: 700, fontSize: 13, opacity: 0.8 }}>TOTAL 7 HARI</div>
            <div style={{ fontSize: 11, opacity: 0.6, marginTop: 2 }}>≈ {formatRupiah(Math.round(totalAll/7))}/hari rata-rata</div>
          </div>
          <div style={{ fontWeight: 900, fontSize: 24, color: "#6ee7b7" }}>
            {formatRupiah(totalAll)}
          </div>
        </div>
      </div>

      {/* Tips */}
      <div style={{
        background: "white", borderRadius: 14, padding: 16,
        marginTop: 12, boxShadow: "0 2px 8px rgba(0,0,0,0.06)"
      }}>
        <div style={{ fontWeight: 800, fontSize: 14, color: "#064e3b", marginBottom: 10 }}>💡 Tips Hemat</div>
        {[
          ["🛒", "Belanja bahan sekali 2-3 hari, jangan harian supaya hemat ongkos"],
          ["🍳", "Goreng tempe/tahu dalam jumlah banyak sekaligus, hemat minyak & gas"],
          ["🐟", "Sarden & kornet kaleng = stok wajib, tahan lama, praktis"],
          ["🥚", "Telur adalah penyelamat — murah, bergizi, bisa diolah banyak cara"],
          ["🕐", "Hari kuliah: masak pagi cepat, siang beli warteg, malam masak lagi"],
        ].map(([icon, tip], i) => (
          <div key={i} style={{ display: "flex", gap: 8, marginBottom: 8, fontSize: 13, color: "#374151", lineHeight: 1.4 }}>
            <span style={{ flexShrink: 0 }}>{icon}</span>
            <span>{tip}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

