                ["Tambah porsi nasi", "Beras 2 kg lebih dari cukup. Kalau lapar, tambah nasi — gratis dari stok."],
                ["Air putih perbanyak", "Minum air banyak bikin perut terasa lebih penuh. Gratis dari kos."],
                ["Sarapan jangan dilewat", "Terutama hari kuliah — kalau lapar di kelas konsentrasi buyar."],
                ["Goreng tempe kering", "Tempe goreng kering tahan lama + mengenyangkan, cocok jadi stok cemilan."],
                ["Tidur cukup", "Kurang tidur bikin hormon lapar meningkat. Tidur yang cukup hemat pengeluaran makan!"],
              ].map(([judul, tip], i) => (
                <div key={i} style={{ display: "flex", gap: 8, marginBottom: 10 }}>
                  <div style={{ width: 24, height: 24, background: "#dcfce7", borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 12, fontWeight: 900, color: "#15803d" }}>{i + 1}</div>
                  <div>
                    <div style={{ fontWeight: 800, fontSize: 13, color: "#111827" }}>{judul}</div>
                    <div style={{ fontSize: 12, color: "#6b7280" }}>{tip}</div>
                  </div>
                </div>
              ))}
            </div>

            {/* Budget final */}
            <div style={{ background: "linear-gradient(135deg, #1e3a5f, #0f5132)", borderRadius: 14, padding: "18px 20px", color: "white" }}>
              <div style={{ fontWeight: 900, fontSize: 16, marginBottom: 12 }}>📊 Ringkasan Budget</div>
              {[
                ["Total belanja seminggu", Rp(totalBelanja), "#6ee7b7"],
                ["Dana cadangan / sayur segar", Rp(sisa), "#fcd34d"],
                ["Rata-rata per hari", Rp(Math.round(totalBelanja / 7)), "#93c5fd"],
                ["Rata-rata per makan", Rp(Math.round(totalBelanja / 21)), "#c4b5fd"],
              ].map(([l, v, c]) => (
                <div key={l} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
                  <span style={{ fontSize: 13, opacity: 0.85 }}>{l}</span>
                  <span style={{ fontWeight: 800, color: c }}>{v}</span>
                </div>
              ))}
              <div style={{ marginTop: 12, background: "rgba(255,255,255,0.1)", borderRadius: 10, padding: "10px 14px", fontSize: 12, opacity: 0.9 }}>
                ✅ Dengan budget <b>Rp 150.000</b>, kamu bisa makan <b>3x sehari selama 7 hari</b> dengan gizi yang cukup — asal disiplin masak sendiri dan bawa bekal.
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

