              ].map((g, i) => (
                <div key={i} style={{ display: "flex", gap: 10, marginBottom: 10, padding: "10px 12px", background: g.ok ? "#f0fdf4" : "#fffbeb", borderRadius: 10, border: `1px solid ${g.ok ? "#bbf7d0" : "#fde68a"}` }}>
