                  <div>
                    <div style={{ fontWeight: 800, fontSize: 13, color: "#111827" }}>{g.label}</div>
                    <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>{g.value}</div>
                  </div>
                </div>
              ))}
            </div>

            {/* Tips anti lapar */}
            <div style={{ background: "white", borderRadius: 14, padding: "16px", marginBottom: 12, boxShadow: "0 1px 6px rgba(0,0,0,0.06)" }}>
              <div style={{ fontWeight: 800, fontSize: 15, color: "#1e3a5f", marginBottom: 12 }}>🍽️ Tips Biar Gak Kelaparan</div>
