        </p>

        {/* Timeline summary bar */}
        <div style={{ marginTop: 16, background: "#1e293b", borderRadius: 12, padding: "12px 14px" }}>
          <div style={{ fontSize: 11, color: "#64748b", fontWeight: 700, marginBottom: 8 }}>TIMELINE SINGKAT</div>
          <div style={{ display: "flex", alignItems: "center", gap: 0, overflowX: "auto", scrollbarWidth: "none" }}>
            {[
              ["06:30", "Bangun"],
              ["06:35", "Masak"],
              ["06:50", "Sarapan"],
              ["07:05", "Bekal"],
              ["07:10", "Mandi"],
              ["07:15", "Siap"],
              ["07:33", "Jalan"],
              ["07:48", "Kelas"],
            ].map(([t, l], i, arr) => (
              <div key={i} style={{ display: "flex", alignItems: "center", flexShrink: 0 }}>
                <div style={{ textAlign: "center" }}>
                  <div style={{ fontSize: 10, fontWeight: 800, color: i === arr.length - 1 ? "#4ade80" : "#e2e8f0" }}>{t}</div>
                  <div style={{ fontSize: 9, color: "#64748b" }}>{l}</div>
                </div>
                {i < arr.length - 1 && (
                  <div style={{ width: 16, height: 2, background: "#334155", margin: "0 4px", flexShrink: 0 }} />
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: "flex", background: "#1e293b", borderBottom: "1px solid #334155" }}>
        {[["pagi", "🌅 Pagi Hari"], ["malam", "🌙 Malam Sebelum"], ["checklist", "✅ Checklist"]].map(([id, label]) => (
          <button key={id} onClick={() => setView(id)} style={{
            flex: 1, padding: "12px 4px", border: "none", background: "none",
            fontFamily: "inherit", fontWeight: 700, fontSize: 12, cursor: "pointer",
            color: view === id ? "#4ade80" : "#64748b",
            borderBottom: view === id ? "2px solid #4ade80" : "2px solid transparent",
            transition: "all 0.15s",
          }}>{label}</button>
        ))}
      </div>

      <div style={{ padding: "16px" }}>

        {/* PAGI */}
        {view === "pagi" && (
          <div>
            <div style={{ background: "#1e293b", borderRadius: 12, padding: "12px 14px", marginBottom: 16, fontSize: 13, color: "#94a3b8" }}>
              💡 Semua bisa terlaksana asal <b style={{ color: "#fbbf24" }}>nasi dan lauk bekal sudah disiapkan malam sebelumnya.</b> Kalau belum, tambah 20 menit dan bangun jam 06:10.
            </div>

            {/* Timeline */}
            <div style={{ position: "relative" }}>
              {/* Vertical line */}
              <div style={{ position: "absolute", left: 43, top: 12, bottom: 12, width: 2, background: "#1e293b", zIndex: 0 }} />

              {morning.map((item, i) => (
                <div key={i} style={{ display: "flex", gap: 12, marginBottom: 12, position: "relative", zIndex: 1 }}>
                  {/* Time */}
                  <div style={{ width: 42, flexShrink: 0, textAlign: "right" }}>
                    <div style={{ fontSize: 12, fontWeight: 900, color: "#e2e8f0", lineHeight: 1 }}>{item.time}</div>
                    {item.duration !== "—" && (
                      <div style={{ fontSize: 9, color: "#475569", marginTop: 2 }}>{item.duration}</div>
                    )}
                  </div>

                  {/* Dot */}
                  <div style={{
                    width: 32, height: 32, borderRadius: "50%", flexShrink: 0,
                    background: item.color + "22",
                    border: `2px solid ${item.color}`,
                    display: "flex", alignItems: "center", justifyContent: "center",
                    fontSize: 15, marginTop: 0,
                  }}>
                    {item.icon}
                  </div>

                  {/* Card */}
                  <div style={{
                    flex: 1, background: "#1e293b",
                    borderRadius: 12, padding: "10px 14px",
                    border: item.urgent ? "1px solid #ef444466" : "1px solid #334155",
                  }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                      <div style={{ fontWeight: 800, fontSize: 14, color: "white" }}>{item.activity}</div>
                      {item.urgent && (
                        <span style={{ fontSize: 9, fontWeight: 800, background: "#ef444422", color: "#f87171", borderRadius: 4, padding: "2px 6px", flexShrink: 0, marginLeft: 8 }}>PENTING</span>
                      )}
                    </div>
                    <div style={{ fontSize: 12, color: "#94a3b8", marginTop: 6, lineHeight: 1.5 }}>{item.detail}</div>
                  </div>
                </div>
              ))}
            </div>

            {/* Final note */}
            <div style={{ background: "#14532d", border: "1px solid #166534", borderRadius: 12, padding: "14px 16px", marginTop: 8 }}>
              <div style={{ fontWeight: 800, fontSize: 14, color: "#4ade80", marginBottom: 6 }}>🎯 Kunci Sukses Pagi Hari</div>
              <div style={{ fontSize: 13, color: "#86efac", lineHeight: 1.6 }}>
                Satu-satunya hal yang bisa bikin semua ini gagal adalah <b>nasi belum dimasak</b>. Kalau nasi sudah ada dari malam, pagi cuma tinggal goreng telur + kemas bekal. Semua selesai dalam 40 menit.
              </div>
            </div>
          </div>
        )}

        {/* MALAM SEBELUM */}
        {view === "malam" && (
          <div>
            <div style={{ background: "#1e293b", borderRadius: 12, padding: "12px 14px", marginBottom: 16, fontSize: 13, color: "#94a3b8" }}>
              🌙 Lakukan ini setelah makan malam, sebelum tidur. Total waktu cuma <b style={{ color: "#a78bfa" }}>±40 menit</b> tapi menyelamatkan seluruh pagi kamu.
            </div>

            {nightBefore.map((item, i) => (
              <div key={i} style={{ display: "flex", gap: 12, marginBottom: 12 }}>
                <div style={{ width: 42, flexShrink: 0, textAlign: "right" }}>
                  <div style={{ fontSize: 12, fontWeight: 900, color: "#e2e8f0" }}>{item.time}</div>
                  {item.duration !== "—" && (
                    <div style={{ fontSize: 9, color: "#475569", marginTop: 2 }}>{item.duration}</div>
                  )}
                </div>
                <div style={{
                  width: 32, height: 32, borderRadius: "50%", flexShrink: 0,
                  background: "#7c3aed22", border: "2px solid #7c3aed",
                  display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15,
                }}>
                  {item.icon}
                </div>
                <div style={{ flex: 1, background: "#1e293b", borderRadius: 12, padding: "10px 14px", border: "1px solid #334155" }}>
                  <div style={{ fontWeight: 800, fontSize: 14, color: "white" }}>{item.activity}</div>
                  <div style={{ fontSize: 12, color: "#94a3b8", marginTop: 5, lineHeight: 1.5 }}>{item.detail}</div>
                  {item.tips && (
                    <div style={{ fontSize: 11, color: "#a78bfa", marginTop: 8, background: "#7c3aed15", borderRadius: 8, padding: "7px 10px", lineHeight: 1.4 }}>
                      💜 {item.tips}
                    </div>
                  )}
                </div>
              </div>
            ))}

            <div style={{ background: "#1e1b4b", border: "1px solid #3730a3", borderRadius: 12, padding: "14px 16px", marginTop: 8 }}>
              <div style={{ fontWeight: 800, fontSize: 14, color: "#a5b4fc", marginBottom: 8 }}>📋 Jadwal Malam Ideal</div>
              {[
                ["~20:00", "Makan malam"],
                ["~21:00", "Masak nasi + goreng lauk bekal"],
                ["~21:35", "Beres-beres dapur kecil"],
                ["~21:45", "Mandi malam, belajar, atau santai"],
                ["~22:30", "Tidur → bangun 06:30 = 8 jam tidur ✓"],
              ].map(([t, a]) => (
                <div key={t} style={{ display: "flex", gap: 10, marginBottom: 7, fontSize: 13 }}>
                  <span style={{ color: "#818cf8", fontWeight: 800, width: 50, flexShrink: 0 }}>{t}</span>
                  <span style={{ color: "#c7d2fe" }}>{a}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* CHECKLIST */}
        {view === "checklist" && (
          <div>
            <div style={{ background: "#1e293b", borderRadius: 12, padding: "14px 16px", marginBottom: 16 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <div style={{ fontWeight: 800, fontSize: 15, color: "white" }}>Sebelum Keluar Kos</div>
                  <div style={{ fontSize: 12, color: "#94a3b8", marginTop: 2 }}>Cek ini di jam 07:30</div>
                </div>
                <div style={{ textAlign: "center" }}>
                  <div style={{ fontWeight: 900, fontSize: 24, color: doneCount === checklist.length ? "#4ade80" : "#fbbf24" }}>
                    {doneCount}/{checklist.length}
                  </div>
                  <div style={{ fontSize: 10, color: "#64748b" }}>selesai</div>
                </div>
              </div>
              {/* Progress bar */}
              <div style={{ height: 6, background: "#334155", borderRadius: 3, marginTop: 12, overflow: "hidden" }}>
                <div style={{
                  height: "100%", borderRadius: 3, transition: "width 0.3s",
                  width: (doneCount / checklist.length * 100) + "%",
                  background: doneCount === checklist.length ? "#4ade80" : "#fbbf24"
                }} />
              </div>
            </div>

            {checklist.map((item, i) => (
              <div key={i} onClick={() => toggle(i)} style={{
                display: "flex", alignItems: "center", gap: 14,
                background: checks[i] ? "#14532d" : "#1e293b",
                border: `1px solid ${checks[i] ? "#166534" : "#334155"}`,
                borderRadius: 12, padding: "14px 16px", marginBottom: 8,
                cursor: "pointer", transition: "all 0.15s",
              }}>
                <div style={{
                  width: 26, height: 26, borderRadius: 8, flexShrink: 0,
                  background: checks[i] ? "#16a34a" : "transparent",
                  border: `2px solid ${checks[i] ? "#16a34a" : "#475569"}`,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  transition: "all 0.15s",
                }}>
                  {checks[i] && <span style={{ color: "white", fontSize: 14, fontWeight: 900 }}>✓</span>}
                </div>
                <span style={{
                  fontSize: 14, fontWeight: 700,
                  color: checks[i] ? "#86efac" : "#e2e8f0",
                  textDecoration: checks[i] ? "line-through" : "none",
                  opacity: checks[i] ? 0.7 : 1,
                  transition: "all 0.15s",
                }}>{item}</span>
              </div>
            ))}

            {doneCount === checklist.length && (
              <div style={{ background: "#14532d", border: "1px solid #16a34a", borderRadius: 12, padding: "16px", textAlign: "center", marginTop: 8 }}>
                <div style={{ fontSize: 28, marginBottom: 6 }}>🎉</div>
                <div style={{ fontWeight: 900, fontSize: 16, color: "#4ade80" }}>Semua beres!</div>
                <div style={{ fontSize: 13, color: "#86efac", marginTop: 4 }}>Berangkat sekarang, kamu tidak akan terlambat.</div>
              </div>
            )}

            <div style={{ background: "#1e293b", borderRadius: 12, padding: "14px 16px", marginTop: 12 }}>
              <div style={{ fontWeight: 800, fontSize: 13, color: "#fbbf24", marginBottom: 8 }}>⚠️ Yang Paling Sering Terlupakan</div>
              {["Kompor lupa dimatikan → bahaya kebakaran", "Bekal ketinggalan → lapar sampai sore", "HP gak di-charge → mati di jalan"].map((t, i) => (
                <div key={i} style={{ fontSize: 12, color: "#94a3b8", marginBottom: 5, display: "flex", gap: 6 }}>
                  <span style={{ color: "#f87171" }}>✗</span> {t}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

