// ============================================================
// TUGAS a - Modifikasi Praktikum 1
// 1. Menghitung Luas Lingkaran
// 2. Menghitung Laju Kecepatan Kendaraan
// ============================================================

// ----- CLASS 1: Lingkaran -----
class Lingkaran {
  public float $jariJari;

  // method getLuas: rumus = π × r²
  public function getLuas(): float {
    return M_PI * $this->jariJari * $this->jariJari;
  }
}

// ----- CLASS 2: Kecepatan -----
class Kecepatan {
  public float $jarak;  // satuan: km
  public float $waktu;  // satuan: jam

  // method getKecepatan: rumus v = s / t
  public function getKecepatan(): float {
    if ($this->waktu == 0) {
      return 0; // hindari pembagian dengan nol
    }
    return $this->jarak / $this->waktu;
  }
}

// ============================================================
// MAIN - Penggunaan Class Lingkaran
// ============================================================
echo "===== Hitung Luas Lingkaran =====" . PHP_EOL;

$lingkaran1 = new Lingkaran();

echo "Masukkan jari-jari lingkaran (cm): ";
$lingkaran1->jariJari = (float) trim(fgets(STDIN));

$luas = $lingkaran1->getLuas();
echo "Luas Lingkaran: " . round($luas, 2) . " cm²" . PHP_EOL;

echo PHP_EOL;

// ============================================================
