class Bus {
  // 1. Private property jumlah penumpang dan kapasitas
  private int $jumlahPenumpang;
  private int $kapasitas;

  // Constructor: inisialisasi awal
  public function __construct(int $kapasitas) {
    $this->kapasitas      = $kapasitas;
    $this->jumlahPenumpang = 0;
  }

  // 2. Setter untuk mengeset nilai kapasitas bus
  public function setKapasitas(int $kapasitas): void {
    if ($kapasitas < 1) {
      echo "Kapasitas tidak valid! Minimal 1." . PHP_EOL;
    } else {
      $this->kapasitas = $kapasitas;
      echo "Kapasitas bus berhasil diset: " . $this->kapasitas . " orang." . PHP_EOL;
    }
  }

  // 3. Getter untuk jumlah penumpang saat ini
  public function getJumlahPenumpang(): int {
    return $this->jumlahPenumpang;
  }

  // 3. Getter untuk kapasitas bus
  public function getKapasitas(): int {
    return $this->kapasitas;
  }

  // 4. Setter untuk MENAMBAH penumpang (dengan validasi)
  public function tambahPenumpang(int $jumlah): void {
    if ($jumlah <= 0) {
      echo "Jumlah penumpang yang ditambah harus lebih dari 0!" . PHP_EOL;
    } elseif (($this->jumlahPenumpang + $jumlah) > $this->kapasitas) {
      $sisa = $this->kapasitas - $this->jumlahPenumpang;
      echo "Gagal! Bus penuh. Sisa tempat yang tersedia: " . $sisa . " orang." . PHP_EOL;
    } else {
      $this->jumlahPenumpang += $jumlah;
      echo "Berhasil menambah " . $jumlah . " penumpang." . PHP_EOL;
    }
  }

  // 4. Setter untuk MENGURANGI penumpang (dengan validasi)
  public function kurangiPenumpang(int $jumlah): void {
    if ($jumlah <= 0) {
      echo "Jumlah penumpang yang dikurangi harus lebih dari 0!" . PHP_EOL;
    } elseif (($this->jumlahPenumpang - $jumlah) < 0) {
      echo "Gagal! Tidak bisa kurangi penumpang. Jumlah saat ini: " . $this->jumlahPenumpang . " orang." . PHP_EOL;
    } else {
      $this->jumlahPenumpang -= $jumlah;
      echo "Berhasil mengurangi " . $jumlah . " penumpang." . PHP_EOL;
    }
  }

  // Method untuk menampilkan info bus
  public function infobus(): void {
    echo "-------------------------------" . PHP_EOL;
    echo "Kapasitas Bus   : " . $this->kapasitas . " orang" . PHP_EOL;
    echo "Jumlah Penumpang: " . $this->jumlahPenumpang . " orang" . PHP_EOL;
    echo "Sisa Tempat     : " . ($this->kapasitas - $this->jumlahPenumpang) . " orang" . PHP_EOL;
    echo "-------------------------------" . PHP_EOL;
  }
}

