        "    private int   $jamKerja;",
        "",
        "    public function __construct(",
        "        string $nama, int $golongan,",
        "        float $tarifPerJam, int $jamKerja",
        "    ) {",
        "        parent::__construct($nama, $golongan);",
        "        $this->tarifPerJam = $tarifPerJam;",
        "        $this->jamKerja    = $jamKerja;",
        "    }",
        "",
        "    public function hitungGaji(): float {",
        "        // Gaji Kontrak = Tarif Per Jam x Jam Kerja",
        "        return $this->tarifPerJam * $this->jamKerja;",
        "    }",
        "}",
        "",
        "// ── Pengujian ───────────────────────────────────────────",
        "$pegawai = [",
        "    new PegawaiTetap(\"Budi Santoso\",  3, 5_000_000, 1_500_000),",
        "    new PegawaiKontrak(\"Sari Dewi\",   2, 75_000,    160),",
        "];",
        "",
        "foreach ($pegawai as $p) {",
        "    echo $p->infoGaji() . PHP_EOL;",
        "}",
        "",
        "/* Output:",
        "   Nama: Budi Santoso  | Golongan: 3 | Gaji: Rp 6.500.000",
        "   Nama: Sari Dewi     | Golongan: 2 | Gaji: Rp 12.000.000",
        "*/",
        "?>",
      ]),
      spacer(8),

      heading2("B. Penjelasan Implementasi"),
      body("Kelas abstrak Pegawai mendefinisikan atribut umum (nama dan golongan) serta method hitungGaji() sebagai method abstrak. Dengan demikian, setiap kelas turunan WAJIB menyediakan implementasi perhitungan gaji yang sesuai dengan jenisnya."),
      spacer(4),
      bulletItem("PegawaiTetap: Menghitung gaji dengan rumus Gaji Pokok + Tunjangan. Cocok untuk pegawai yang menerima kompensasi tetap setiap bulan."),
      bulletItem("PegawaiKontrak: Menghitung gaji dengan rumus Tarif Per Jam x Jam Kerja. Cocok untuk pegawai yang dibayar berdasarkan waktu kerja aktual."),
      spacer(4),
      body("Method infoGaji() didefinisikan di kelas induk sebagai method konkret, sehingga tidak perlu diulang di kelas turunan. Ini mendemonstrasikan keunggulan code reuse pada abstract class."),
      spacer(12),

      // ══════════════════════════════════════════════════════════
      // TUGAS 3
      // ══════════════════════════════════════════════════════════
      heading1("Tugas 3: Analisis Keuntungan Abstract Class dalam Sistem Informasi Berbasis Web"),
      spacer(8),

      heading2("A. Konteks Permasalahan"),
      body("Sistem informasi berbasis web modern umumnya terdiri dari banyak modul yang memiliki pola perilaku serupa, misalnya modul Pegawai, Mahasiswa, Pelanggan, dan Supplier — semuanya memerlukan operasi CRUD (Create, Read, Update, Delete), validasi data, dan pembangkitan laporan. Tanpa abstract class, setiap modul harus menulis ulang logika-logika tersebut secara mandiri, yang berakibat pada duplikasi kode, inkonsistensi, dan kesulitan perawatan."),
      spacer(8),

      heading2("B. Keuntungan Penerapan Abstract Class"),

      body("1. Konsistensi Antarmuka (Enforced Contract)", { bold: true }),
      body("Abstract class memaksa seluruh kelas turunan mengimplementasikan method-method kritis yang sama, seperti validate(), save(), dan generateReport(). Hal ini memastikan bahwa setiap modul berperilaku secara konsisten, sehingga tim pengembang dapat bekerja pada modul berbeda tanpa khawatir terjadi perbedaan perilaku yang tidak terduga."),
      spacer(4),

      body("2. Code Reuse dan Pengurangan Duplikasi", { bold: true }),
      body("Logika bisnis yang umum — seperti koneksi database, penanganan error, logging aktivitas, dan format response API — cukup ditulis sekali di kelas induk. Kelas-kelas turunan hanya perlu mengimplementasikan bagian yang spesifik untuk masing-masing modul."),
      spacer(4),

      body("3. Kemudahan Pemeliharaan (Maintainability)", { bold: true }),
      body("Perubahan pada logika umum cukup dilakukan di satu tempat (kelas induk), dan perubahan tersebut secara otomatis berlaku untuk semua kelas turunan. Misalnya, jika format log perlu diperbarui, cukup ubah di abstract class BaseModel tanpa menyentuh setiap modul."),
      spacer(4),

      body("4. Fleksibilitas melalui Polimorfisme", { bold: true }),
      body("Dengan abstract class, sistem dapat memproses objek dari berbagai kelas turunan secara seragam melalui referensi kelas induk. Contohnya, controller dapat memanggil $model->save() tanpa perlu mengetahui apakah objek tersebut instance dari ModulPegawai, ModulPelanggan, atau modul lainnya."),
      spacer(4),

      body("5. Keamanan dan Enkapsulasi", { bold: true }),
      body("Abstract class memungkinkan penerapan logika keamanan (seperti sanitasi input, validasi token, dan pengecekan hak akses) di tingkat kelas induk, sehingga seluruh modul secara otomatis terlindungi tanpa harus menerapkan mekanisme keamanan secara terpisah."),
      spacer(8),

      heading2("C. Contoh Implementasi dalam Sistem Informasi"),
      codeBlock([
        "<?php",
        "",
        "abstract class BaseModel {",
        "    protected PDO    $db;",
        "    protected string $table;",
        "",
        "    public function __construct(PDO $db) {",
        "        $this->db = $db;",
        "    }",
        "",
        "    // Method konkret: logika umum yang dipakai semua modul",
        "    protected function log(string $action): void {",
        "        // Catat aktivitas ke tabel audit",
        "        $stmt = $this->db->prepare(",
        "            \"INSERT INTO audit_log (tabel, aksi, waktu) VALUES (?, ?, NOW())\"",
        "        );",
        "        $stmt->execute([$this->table, $action]);",
        "    }",
        "",
        "    public function findById(int $id): ?array {",
        "        $stmt = $this->db->prepare(",
        "            \"SELECT * FROM {$this->table} WHERE id = ?\"",
        "        );",
        "        $stmt->execute([$id]);",
        "        return $stmt->fetch(PDO::FETCH_ASSOC) ?: null;",
        "    }",
        "",
        "    // Method abstrak: implementasi spesifik tiap modul",
        "    abstract public function validate(array $data): bool;",
        "    abstract public function save(array $data): int;",
        "    abstract public function generateReport(): array;",
        "}",
        "",
        "// Modul Pegawai",
        "class ModulPegawai extends BaseModel {",
        "    protected string $table = 'pegawai';",
        "",
        "    public function validate(array $data): bool {",
        "        return !empty($data['nama']) && !empty($data['nip']);",
        "    }",
        "",
        "    public function save(array $data): int {",
        "        if (!$this->validate($data)) throw new Exception('Data tidak valid');",
        "        $stmt = $this->db->prepare(",
        "            \"INSERT INTO pegawai (nama, nip) VALUES (?, ?)\"",
        "        );",
        "        $stmt->execute([$data['nama'], $data['nip']]);",
        "        $this->log('INSERT');",
        "        return (int)$this->db->lastInsertId();",
        "    }",
        "",
        "    public function generateReport(): array {",
        "        return $this->db->query(",
        "            \"SELECT golongan, COUNT(*) as total FROM pegawai GROUP BY golongan\"",
        "        )->fetchAll(PDO::FETCH_ASSOC);",
        "    }",
        "}",
        "",
        "// Modul Pelanggan — pola yang sama, implementasi berbeda",
        "class ModulPelanggan extends BaseModel {",
        "    protected string $table = 'pelanggan';",
        "",
        "    public function validate(array $data): bool {",
        "        return !empty($data['nama']) && filter_var($data['email'], FILTER_VALIDATE_EMAIL);",
        "    }",
        "",
        "    public function save(array $data): int {",
        "        if (!$this->validate($data)) throw new Exception('Data tidak valid');",
        "        $stmt = $this->db->prepare(",
        "            \"INSERT INTO pelanggan (nama, email) VALUES (?, ?)\"",
        "        );",
        "        $stmt->execute([$data['nama'], $data['email']]);",
        "        $this->log('INSERT');",
        "        return (int)$this->db->lastInsertId();",
        "    }",
        "",
        "    public function generateReport(): array {",
        "        return $this->db->query(",
        "            \"SELECT DATE(created_at) as tgl, COUNT(*) as total",
        "             FROM pelanggan GROUP BY tgl ORDER BY tgl DESC LIMIT 30\"",
        "        )->fetchAll(PDO::FETCH_ASSOC);",
        "    }",
        "}",
        "?>",
      ]),
      spacer(8),

      heading2("D. Kesimpulan"),
      body("Penerapan abstract class dalam pengembangan sistem informasi berbasis web yang memiliki banyak modul serupa memberikan manfaat yang signifikan dari segi arsitektur perangkat lunak. Kelas induk abstrak bertindak sebagai cetak biru (blueprint) yang menjamin konsistensi, mengurangi duplikasi kode, dan mempermudah pemeliharaan jangka panjang. Setiap perubahan pada logika umum hanya perlu dilakukan di satu tempat, sementara fleksibilitas tetap terjaga melalui polimorfisme. Dengan demikian, tim pengembang dapat menambahkan modul baru dengan lebih cepat dan aman tanpa risiko merusak modul yang sudah ada."),
      spacer(4),
      body("Abstract class sangat ideal digunakan ketika terdapat hubungan 'IS-A' yang kuat antar kelas (misalnya PegawaiTetap IS-A Pegawai), ada logika bersama yang ingin diwarisi, dan setiap turunan memiliki implementasi spesifik yang wajib tersedia. Sementara interface lebih tepat digunakan ketika yang dibutuhkan hanyalah kontrak perilaku tanpa logika bersama."),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Tugas_Teori_M4_PBO_Faizal_Kahfi_Lubis.docx", buffer);
  console.log("Done!");
});

