const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, LevelFormat, BorderStyle, WidthType,
  ShadingType, VerticalAlign, PageNumber, Header, Footer
} = require('docx');
const fs = require('fs');

const NAVY  = "0D2B6B";
const TEAL  = "1A7A5E";
const LIGHT = "EAF2FB";
const CODEBG = "1E1E2E";
const GREY  = "5A6A7E";
const WHITE = "FFFFFF";

const cellBorder = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function spacer(pt = 6) {
  return new Paragraph({ children: [new TextRun("")], spacing: { after: pt * 20 } });
}

function heading1(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, color: WHITE, size: 28, font: "Arial" })],
    shading: { fill: NAVY, type: ShadingType.CLEAR },
    spacing: { before: 280, after: 200 },
    indent: { left: 200, right: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: TEAL } }
  });
}

function heading2(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, color: NAVY, size: 24, font: "Arial" })],
    spacing: { before: 240, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: "AABBD0", space: 1 } }

