              space(),
              new Paragraph({ children: [new TextRun({ text: "1. Sebesta, R. W. (2021). Concepts of Programming Languages (13th ed.). Pearson.", font: "Arial", size: 20, color: DARK })] }),
              new Paragraph({ children: [new TextRun({ text: "2. Welling, L., & Thomson, L. (2017). PHP and MySQL Web Development (5th ed.). Addison-Wesley.", font: "Arial", size: 20, color: DARK })] }),
              new Paragraph({ children: [new TextRun({ text: "3. Ullman, L. (2018). PHP for the Web: Visual QuickStart Guide (5th ed.). Peachpit Press.", font: "Arial", size: 20, color: DARK })] }),
              new Paragraph({ children: [new TextRun({ text: "4. Zend Technologies. (2024). PHP Manual: Object Interfaces. php.net", font: "Arial", size: 20, color: DARK })] }),
              new Paragraph({ children: [new TextRun({ text: "5. Booch, G., Rumbaugh, J., & Jacobson, I. (2007). Object-Oriented Analysis and Design (3rd ed.). Addison-Wesley.", font: "Arial", size: 20, color: DARK })] }),
            ]
