      // ══ SOAL 1 ════════════════════════════════════════════════════
      h1("1. Perbedaan Interface dan Class Abstrak dalam PHP"),
      space(),

      para(
        "Interface dan class abstrak adalah dua mekanisme dalam OOP PHP yang digunakan untuk " +
        "mendefinisikan kontrak atau cetak biru bagi kelas-kelas lain. Meskipun keduanya " +
        "memiliki tujuan yang serupa, terdapat perbedaan mendasar dalam cara kerja dan penggunaannya."
      ),
