const titleColor = "1F3864";
const accentColor = "2E75B6";
const bodyFont = "Arial";

const heading1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [new TextRun({ text, bold: true, size: 28, color: titleColor, font: bodyFont })],
  spacing: { before: 300, after: 120 },
});

const heading2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [new TextRun({ text, bold: true, size: 24, color: accentColor, font: bodyFont })],
  spacing: { before: 200, after: 100 },
});

const body = (text, options = {}) => new Paragraph({
  children: [new TextRun({ text, size: 22, font: bodyFont, ...options })],
  spacing: { before: 60, after: 60 },
  alignment: AlignmentType.JUSTIFIED,
});

const code = (text) => new Paragraph({
  children: [new TextRun({ text, size: 18, font: "Courier New", color: "1a1a1a" })],
  spacing: { before: 20, after: 20 },
  indent: { left: 720 },
  border: { left: { style: BorderStyle.SINGLE, size: 6, color: "2E75B6", space: 10 } },
});

const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  children: [new TextRun({ text, size: 22, font: bodyFont })],
  spacing: { before: 40, after: 40 },
});

const spacer = () => new Paragraph({ children: [new TextRun("")], spacing: { before: 80, after: 80 } });

const divider = () => new Paragraph({
  children: [new TextRun("")],
