            ],
            alignment: AlignmentType.RIGHT,
            border: { top: { style: BorderStyle.SINGLE, size: 4, color: "2E75B6", space: 4 } },
          })
        ]
      })
    },
    children: [
      // ===== JUDUL =====
      new Paragraph({
        children: [new TextRun({ text: "LAPORAN TUGAS", bold: true, size: 40, font: bodyFont, color: titleColor })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 240, after: 80 },
      }),
      new Paragraph({
        children: [new TextRun({ text: "Abstraction dalam Pemrograman Berorientasi Objek (OOP) – PHP", size: 24, font: bodyFont, color: accentColor, italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 480 },
      }),

      divider(),

      // ===== TUGAS 1 =====
      heading1("Tugas 1: Perbedaan Abstract Class dan Interface dalam PHP"),

      body("Abstract class dan interface adalah dua mekanisme utama untuk menerapkan abstraksi dalam PHP, namun keduanya memiliki karakteristik dan tujuan penggunaan yang berbeda."),
      spacer(),

      heading2("Abstract Class"),
      body("Abstract class adalah kelas yang tidak dapat diinstansiasi secara langsung dan harus diwariskan oleh kelas turunan. Kelas ini dapat memiliki method biasa (dengan implementasi) maupun method abstract (tanpa implementasi). Kelas turunan wajib mengimplementasikan seluruh method abstract yang ada."),
      spacer(),

      body("Contoh penggunaan abstract class:", { bold: true }),
      code("<?php"),
      code("abstract class Hewan {"),
      code("    public function bernafas() {"),
      code("        echo 'Menghirup oksigen';"),
      code("    }"),
      code("    abstract public function bersuara();"),
      code("}"),
      code(""),
      code("class Kucing extends Hewan {"),
      code("    public function bersuara() {"),
      code("        echo 'Meong';"),
      code("    }"),
      code("}"),
      code("?>"),
      spacer(),

      heading2("Interface"),
      body("Interface adalah kontrak yang hanya berisi deklarasi method tanpa implementasi. Sebuah kelas dapat mengimplementasikan lebih dari satu interface sekaligus, sehingga interface mendukung multiple inheritance secara tidak langsung. Semua method dalam interface bersifat public dan abstract secara default."),
      spacer(),

      body("Contoh penggunaan interface:", { bold: true }),
      code("<?php"),
      code("interface Berenang {"),
      code("    public function renang();"),
      code("}"),
      code(""),
      code("interface Terbang {"),
      code("    public function terbang();"),
      code("}"),
      code(""),
      code("class Bebek implements Berenang, Terbang {"),
      code("    public function renang() { echo 'Bebek berenang'; }"),
      code("    public function terbang() { echo 'Bebek terbang'; }"),
      code("}"),
      code("?>"),
      spacer(),

      heading2("Ringkasan Perbedaan"),
      bullet("Abstract class: dapat memiliki method biasa dan abstract, mendukung single inheritance, boleh memiliki properti dan constructor."),
      bullet("Interface: hanya berisi deklarasi method tanpa implementasi, mendukung multiple inheritance, tidak dapat memiliki properti biasa."),
      bullet("Abstract class digunakan ketika ada logika bersama antar kelas turunan. Interface digunakan ketika ingin mendefinisikan kontrak perilaku lintas hierarki kelas."),

      divider(),

      // ===== TUGAS 2 =====
      heading1("Tugas 2: Implementasi Abstract Class Pegawai"),

      body("Berikut adalah contoh implementasi abstract class Pegawai dengan method abstract hitungGaji(), beserta dua kelas turunan PegawaiTetap dan PegawaiKontrak yang masing-masing memiliki cara penghitungan gaji berbeda."),
      spacer(),

      code("<?php"),
      code("abstract class Pegawai {"),
      code("    protected string $nama;"),
      code("    protected int $golongan;"),
      code(""),
      code("    public function __construct(string $nama, int $golongan) {"),
      code("        $this->nama     = $nama;"),
      code("        $this->golongan = $golongan;"),
      code("    }"),
      code(""),
      code("    abstract public function hitungGaji(): float;"),
      code(""),
      code("    public function tampilInfo(): void {"),
      code("        echo \"Nama    : {$this->nama}\\n\";"),
      code("        echo \"Gaji    : Rp \" . number_format($this->hitungGaji(), 0, ',', '.') . \"\\n\";"),
      code("    }"),
