const {
  Document, Packer, Paragraph, TextRun, ImageRun,
  AlignmentType, HeadingLevel, PageBreak, BorderStyle
} = require('docx');
const fs = require('fs');

const bodyFont = "Times New Roman";

// Helper: image paragraph centered
function imgPara(imgPath, widthCm, heightCm) {
  const toDxa = cm => Math.round(cm * 567); // 1cm = 567 EMU? No, use inches
  // EMU: 1 inch = 914400 EMU, 1 cm = 360000 EMU
  const toEmu = cm => Math.round(cm * 360000);
  const data = fs.readFileSync(imgPath);
  return new Paragraph({
    children: [
      new ImageRun({
        data,
        transformation: {
          width: Math.round(widthCm * 28.35),  // points? No - docx ImageRun uses pixels
          height: Math.round(heightCm * 28.35),
        },
        type: "png",
      })
    ],
    alignment: AlignmentType.CENTER,
    spacing: { before: 120, after: 120 },
  });
}

// Use pixel-based sizing (96 dpi assumed)
// docx ImageRun width/height are in points (1pt = 1/72 inch)
// Let's size screenshots to fit page width ~16cm = ~453pt
// Page content width with 2.54cm margins on A4 = 21 - 2*2.54 = 15.92cm
// Let's use 15cm wide for screenshots, height proportional

function makeImagePara(imgPath, origW, origH, targetWidthPt) {
  const ratio = origH / origW;
  const targetH = Math.round(targetWidthPt * ratio);
  const data = fs.readFileSync(imgPath);
  return new Paragraph({
    children: [
      new ImageRun({
        data,
        transformation: { width: targetWidthPt, height: targetH },
        type: "png",
      })
    ],
