const {
  Document, Packer, Paragraph, TextRun, ImageRun,
  AlignmentType, HeadingLevel, PageBreak, BorderStyle, LevelFormat
} = require('docx');
const fs = require('fs');

const F = "Times New Roman";
const BLUE = "1F3864";
const ACCENT = "2E75B6";
const PW = 420; // content width in points

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, bold: true, size: 28, font: F, color: BLUE })],
    spacing: { before: 320, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: ACCENT, space: 4 } },
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, bold: true, size: 24, font: F, color: ACCENT })],
    spacing: { before: 200, after: 100 },
  });
}

function h3(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 22, font: F })],
    spacing: { before: 160, after: 80 },
  });
}

function p(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, font: F })],
    spacing: { before: 60, after: 60 },
    alignment: AlignmentType.JUSTIFIED,
  });
}

function code(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 18, font: "Courier New", color: "1a1a1a" })],
    spacing: { before: 10, after: 10 },
    indent: { left: 560 },
    border: { left: { style: BorderStyle.SINGLE, size: 8, color: ACCENT, space: 8 } },
  });
}

function sp() {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } });
}

function pb() {
  return new Paragraph({ children: [new PageBreak()] });
}

const logoData = fs.readFileSync("/home/claude/unpacked_orig/word/media/image1.png");
const logoW = 120, logoH = Math.round(120 * 214 / 235);

const children = [];

// ===== COVER =====
children.push(new Paragraph({
  children: [new ImageRun({ data: logoData, transformation: { width: logoW, height: logoH }, type: "png" })],
  alignment: AlignmentType.CENTER,
  spacing: { before: 1440, after: 360 },
}));

const info = [
  ["NAMA", "Kemas Muhammad Alif Bisyafa Basunjaya"],
  ["NIM", "4342501068"],
  ["KELAS", "TRPL PAGI 2C"],
  ["KOORDINATOR MATA KULIAH", "Ahmadi Irmansyah Lubis"],
  ["PENGAMPU PRAKTIKUM", "Ahmadi Irmansyah Lubis / Muhamad Sahrul Nizan"],
];
for (const [l, v] of info) {
  children.push(new Paragraph({
    children: [new TextRun({ text: `${l} : ${v}`, size: 24, font: F })],
    spacing: { before: 60, after: 60 },
  }));
}
children.push(sp());
children.push(sp());
children.push(sp());
for (const line of [
  "PROGRAM STUDI TEKNOLOGI REKAYASA PERANGKAT LUNAK",
  "JURUSAN TEKNIK INFORMATIKA",
  "POLITEKNIK NEGERI BATAM",
  "2026",
]) {
  children.push(new Paragraph({
    children: [new TextRun({ text: line, bold: true, size: 24, font: F })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 60, after: 60 },
  }));
}

// ===== A. AGGREGATES =====
children.push(pb());
children.push(h1("A. AGGREGATES"));
children.push(p("Bagian ini menggunakan dua tabel yaitu tb_penjualan_brg dan tb_matkul. Fungsi agregat digunakan untuk meringkas sekumpulan data menjadi satu nilai seperti minimum, jumlah, atau total. Dikombinasikan dengan GROUP BY untuk pengelompokan dan HAVING untuk menyaring hasil kelompok."));
children.push(sp());

// Setup
children.push(h2("Persiapan Database dan Tabel"));
children.push(p("Langkah pertama adalah membuat database dan mengisi kedua tabel dengan data yang telah ditentukan."));
for (const q of [
  "CREATE DATABASE db_p4_penugasan;",
  "USE db_p4_penugasan;",
  "",
  "CREATE TABLE tb_penjualan_brg (",
  "  kode_buku  VARCHAR(10),",
  "  jenis_buku VARCHAR(20),",
  "  nama_buku  VARCHAR(50),",
  "  harga      INT,",
  "  stok       INT",
  ");",
  "",
  "INSERT INTO tb_penjualan_brg VALUES",
  "('NVL447','Novel','Bumi Manusia',53500,10),",
  "('NVL777','Novel','Laskar Pelangi',62200,15),",
  "('TKS342','Teks','Matematika Diskrit',80500,9),",
  "('KMK123','Komik','Naruto vol. 60',25500,1),",
  "('KMK333','Komik','HxH vol. 12',24250,5),",
  "('TKS778','Teks','Java Mobile',150000,1),",
  "('KMS333','Kamus','Kamus Bhs Inggris',35000,18);",
  "",
  "CREATE TABLE tb_matkul (",
  "  kode_mk  VARCHAR(10),",
  "  nama_mk  VARCHAR(50),",
  "  sks      INT,",
  "  semester INT",
  ");",
  "",
  "INSERT INTO tb_matkul VALUES",
  "('PTI447','Praktikum Basis Data',1,3),",
  "('TIK342','Praktikum Basis Data',1,3),",
  "('PTI333','Basis Data Terdistribusi',3,5),",
  "('TIK123','Jaringan Komputer',2,5),",
  "('TIK333','Sistem Operasi',3,5),",
  "('PTI123','Grafika Komputer',3,5),",
  "('PTI777','Sistem Informasi',2,3);",
]) { if (q === "") { children.push(sp()); } else { children.push(code(q)); } }

// A1
children.push(sp());
children.push(h2("Soal 1 – Harga Termurah per Jenis Buku"));
children.push(p("Query berikut mengelompokkan buku berdasarkan jenis lalu mencari harga terkecil di masing-masing kelompok menggunakan fungsi MIN."));
for (const q of [
  "SELECT jenis_buku, MIN(harga) AS harga_termurah",
  "FROM tb_penjualan_brg",
  "GROUP BY jenis_buku;",
]) children.push(code(q));
children.push(p("Hasil yang diharapkan: setiap jenis buku (Novel, Teks, Komik, Kamus) menampilkan satu baris dengan harga buku termurahnya."));

// A2
