children.push(p("Subquery mencari kode_dos dari mata kuliah yang semesternya lebih dari 3. Main query menampilkan data dosen yang kode_dos-nya ada dalam daftar tersebut. DISTINCT digunakan agar dosen yang mengajar lebih dari satu mata kuliah tidak muncul dua kali."));
for (const q of [
  "SELECT DISTINCT d.kode_dos, d.nama_dos",
  "FROM dosen d",
  "WHERE d.kode_dos IN (",
  "  SELECT kode_dos FROM matakuliah",
  "  WHERE semester > 3",
  ");",
]) children.push(code(q));
children.push(p("Hasil yang diharapkan: dosen yang mengajar mata kuliah semester 5 yaitu Suharto (10), Rahmawati (12), dan Bambang (13)."));

// B4
children.push(sp());
children.push(h2("Soal 4 – Matkul Dosen yang Bukan Ketua Jurusan Teknik Elektro"));
children.push(p("Kebalikan dari soal 1. Operator <> (tidak sama dengan) digunakan agar yang ditampilkan adalah mata kuliah yang dosennya bukan kode_dos 10."));
for (const q of [
  "SELECT kd_mk, nama_mk",
  "FROM matakuliah",
  "WHERE kode_dos <> (",
  "  SELECT kode_dos FROM jurusan",
  "  WHERE nama_jur = 'Teknik Elektro'",
  ");",
]) children.push(code(q));
children.push(p("Hasil yang diharapkan: semua mata kuliah kecuali yang diajar oleh dosen berkode 10."));

// B5
children.push(sp());
children.push(h2("Soal 5 – Dosen Pengajar Matkul yang Tidak Diambil Mahasiswa"));
children.push(p("Subquery bertingkat dua. Subquery paling dalam mencari kd_mk yang ada di ambil_mk, subquery tengah mencari mata kuliah yang tidak ada dalam daftar tersebut dan mengambil kode_dos-nya, lalu main query menampilkan data dosen berdasarkan kode_dos tersebut."));
for (const q of [
  "SELECT DISTINCT d.kode_dos, d.nama_dos",
  "FROM dosen d",
  "WHERE d.kode_dos IN (",
  "  SELECT kode_dos FROM matakuliah",
  "  WHERE kd_mk NOT IN (",
  "    SELECT kd_mk FROM ambil_mk",
  "  )",
  ");",
]) children.push(code(q));
children.push(p("Hasil yang diharapkan: dosen yang mata kuliahnya belum diambil mahasiswa manapun, yaitu dosen pengajar TIK123 dan TIK342."));

// ===== C. CONSTRAINT =====
children.push(pb());
children.push(h1("C. CONSTRAINT"));
children.push(p("Bagian ini membangun skema database untuk Sistem Manajemen Perpustakaan Digital. Constraint dipasang di tabel untuk memastikan data yang masuk selalu valid dan konsisten sesuai aturan bisnis yang telah ditentukan."));

// Buat tabel
children.push(sp());
children.push(h2("Pembuatan Tabel dengan Constraint"));
children.push(p("Dua tabel dibuat yaitu buku sebagai tabel induk dan peminjaman sebagai tabel anak yang mereferensi ke buku."));
for (const q of [
  "CREATE DATABASE db_perpustakaan;",
  "USE db_perpustakaan;",
  "",
  "CREATE TABLE buku (",
  "  id_buku      INT AUTO_INCREMENT,",
  "  isbn         VARCHAR(20) NOT NULL,",
  "  judul        VARCHAR(100) NOT NULL,",
  "  stok         INT DEFAULT 0,",
  "  tahun_terbit YEAR DEFAULT (YEAR(CURDATE())),",
  "  CONSTRAINT buku_id_pk    PRIMARY KEY (id_buku),",
  "  CONSTRAINT buku_isbn_uk  UNIQUE (isbn),",
  "  CONSTRAINT buku_stok_chk CHECK (stok >= 0)",
  ");",
  "",
  "CREATE TABLE peminjaman (",
  "  id_pinjam  INT,",
  "  id_buku    INT NOT NULL,",
  "  tgl_pinjam DATE NOT NULL,",
  "  status     VARCHAR(10),",
  "  CONSTRAINT pinjam_id_pk      PRIMARY KEY (id_pinjam),",
  "  CONSTRAINT pinjam_buku_fk    FOREIGN KEY (id_buku)",
  "             REFERENCES buku (id_buku),",
  "  CONSTRAINT pinjam_status_chk CHECK (status IN ('Dipinjam','Kembali'))",
  ");",
]) { if (q === "") children.push(sp()); else children.push(code(q)); }

// Eksperimen 1
children.push(sp());
children.push(h2("Eksperimen 1 – Unique Violation (ISBN Duplikat)"));
children.push(p("Percobaan memasukkan dua buku dengan ISBN yang sama. Baris pertama berhasil, baris kedua ditolak karena melanggar constraint UNIQUE pada kolom isbn."));
for (const q of [
  "-- Berhasil dimasukkan",
  "INSERT INTO buku (isbn, judul, stok)",
  "VALUES ('978-123', 'Buku Pertama', 5);",
  "",
  "-- Ditolak, ISBN sudah ada",
  "INSERT INTO buku (isbn, judul, stok)",
  "VALUES ('978-123', 'Buku Lain', 3);",
]) { if (q.startsWith("--")) children.push(p(q)); else children.push(code(q)); }
children.push(p("Error yang muncul: Duplicate entry '978-123' for key 'buku_isbn_uk'. Constraint UNIQUE memastikan setiap ISBN hanya boleh dimiliki oleh satu buku saja di dalam tabel."));

// Eksperimen 2
children.push(sp());
children.push(h2("Eksperimen 2 – Check Violation (Stok Negatif)"));
children.push(p("Percobaan memasukkan buku dengan nilai stok -5. MySQL menolak karena melanggar constraint CHECK yang mensyaratkan stok harus bernilai lebih dari atau sama dengan 0."));
for (const q of [
  "INSERT INTO buku (isbn, judul, stok)",
  "VALUES ('978-456', 'Buku Kedua', -5);",
]) children.push(code(q));
children.push(p("Error yang muncul: CHECK constraint 'buku_stok_chk' is violated. Nilai -5 tidak memenuhi syarat stok >= 0 sehingga data ditolak sepenuhnya oleh MySQL."));

// Eksperimen 3
children.push(sp());
children.push(h2("Eksperimen 3 – FK Restriction (Hapus Buku yang Sedang Dipinjam)"));
children.push(p("Percobaan menghapus data buku yang masih direferensi oleh tabel peminjaman. MySQL menolak karena constraint FOREIGN KEY menjaga integritas referensial antar tabel."));
for (const q of [
  "-- Masukkan data buku yang valid",
  "INSERT INTO buku (isbn, judul, stok)",
  "VALUES ('978-789', 'Buku Ketiga', 3);",
  "",
  "-- Masukkan data peminjaman yang mereferensi buku tersebut",
  "INSERT INTO peminjaman VALUES",
  "(1, 1, '2026-04-06', 'Dipinjam');",
  "",
  "-- Coba hapus buku, ini akan ditolak",
  "DELETE FROM buku WHERE id_buku = 1;",
]) { if (q.startsWith("--")) children.push(p(q)); else children.push(code(q)); }
children.push(p("Error yang muncul: Cannot delete or update a parent row: a foreign key constraint fails. Selama data di tabel peminjaman masih mereferensi buku tersebut, penghapusan tidak bisa dilakukan demi menjaga konsistensi data antar tabel."));

// ===== KESIMPULAN =====
children.push(pb());
children.push(h1("Kesimpulan"));
children.push(p("Dari keseluruhan praktikum pertemuan 4 ini, terdapat tiga materi utama yang saling melengkapi dalam pengelolaan database."));
children.push(sp());
children.push(p("Pertama, fungsi Aggregates seperti MIN, SUM, COUNT, dan AVG memungkinkan pengolahan data secara ringkas tanpa harus mengambil semua baris satu per satu. Dikombinasikan dengan GROUP BY dan HAVING, query menjadi lebih fleksibel dalam menghasilkan informasi per kelompok data."));
children.push(sp());
children.push(p("Kedua, Sub Query menyederhanakan pengambilan data yang kompleks menjadi satu perintah SQL. Subquery bekerja dari dalam ke luar, menghasilkan nilai yang kemudian digunakan oleh query utama untuk menyaring data yang diinginkan."));
children.push(sp());
children.push(p("Ketiga, Constraint adalah lapisan perlindungan yang memastikan setiap data yang masuk ke database selalu valid, konsisten, dan tidak melanggar aturan yang telah ditetapkan. Tanpa constraint, database rentan terhadap kesalahan input yang bisa merusak integritas seluruh sistem."));

