function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 300, after: 150 },
    children: [new TextRun({ text, bold: true, size: 36, color: BLUE_DARK, font: "Arial" })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 240, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BLUE_MID, space: 1 } },
    children: [new TextRun({ text, bold: true, size: 28, color: BLUE_MID, font: "Arial" })]
  });
}

function h3(text, color = GRAY_DARK) {
  return new Paragraph({
    spacing: { before: 180, after: 80 },
    children: [new TextRun({ text, bold: true, size: 24, color, font: "Arial" })]
  });
}

function normal(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: "333333" })]
  });
}

function normalBold(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: "333333" })]
  });
}

function code(text) {
  return new Paragraph({
    spacing: { before: 40, after: 40 },
    indent: { left: 360 },
    children: [new TextRun({ text, size: 20, font: "Courier New", color: "1F4E79" })]
  });
}

function codeBlock(lines) {
  const paragraphs = [];
  paragraphs.push(new Paragraph({
    spacing: { before: 100, after: 0 },
    border: { top: borderThin, left: { style: BorderStyle.SINGLE, size: 6, color: BLUE_MID } },
    shading: { fill: "F0F7FF", type: ShadingType.CLEAR },
    indent: { left: 360, right: 360 },
    children: [new TextRun({ text: "" })]
  }));
  for (const line of lines) {
    paragraphs.push(new Paragraph({
      spacing: { before: 0, after: 0 },
      shading: { fill: "F0F7FF", type: ShadingType.CLEAR },
      indent: { left: 360, right: 360 },
      children: [new TextRun({ text: line, size: 19, font: "Courier New", color: "1F4E79" })]
    }));
  }
  paragraphs.push(new Paragraph({
    spacing: { before: 0, after: 100 },
    border: { bottom: borderThin },
    shading: { fill: "F0F7FF", type: ShadingType.CLEAR },
    indent: { left: 360, right: 360 },
    children: [new TextRun({ text: "" })]
  }));
  return paragraphs;
}

function infoBox(label, text, bgColor, textColor, borderColor) {
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [9026],
    rows: [
      new TableRow({
        children: [new TableCell({
          borders: { top: { style: BorderStyle.SINGLE, size: 4, color: borderColor }, bottom: { style: BorderStyle.SINGLE, size: 4, color: borderColor }, left: { style: BorderStyle.SINGLE, size: 12, color: borderColor }, right: { style: BorderStyle.SINGLE, size: 4, color: borderColor } },
          shading: { fill: bgColor, type: ShadingType.CLEAR },
          margins: { top: 100, bottom: 100, left: 150, right: 150 },
          children: [
            new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: label, bold: true, size: 18, font: "Arial", color: borderColor })] }),
            new Paragraph({ spacing: { before: 0, after: 0 }, children: [new TextRun({ text, size: 20, font: "Arial", color: textColor })] })
          ]
        })]
      })
    ]
  });
}

