const GRAY_LIGHT = "F2F2F2";

function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 150 }, children: [new TextRun({ text, bold: true, size: 36, color: BLUE_DARK, font: "Arial" })] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 120 }, border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BLUE_MID, space: 1 } }, children: [new TextRun({ text, bold: true, size: 28, color: BLUE_MID, font: "Arial" })] });
}
function normal(text) {
  return new Paragraph({ spacing: { before: 60, after: 60 }, children: [new TextRun({ text, size: 22, font: "Arial", color: "333333" })] });
}
function spacer() {
  return new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun("")] });
}
function codeBlock(lines) {
  const paragraphs = [];
  paragraphs.push(new Paragraph({ spacing: { before: 100, after: 0 }, border: { top: borderThin, left: { style: BorderStyle.SINGLE, size: 6, color: BLUE_MID } }, shading: { fill: "F0F7FF", type: ShadingType.CLEAR }, indent: { left: 360, right: 360 }, children: [new TextRun({ text: "" })] }));
  for (const line of lines) {
    paragraphs.push(new Paragraph({ spacing: { before: 0, after: 0 }, shading: { fill: "F0F7FF", type: ShadingType.CLEAR }, indent: { left: 360, right: 360 }, children: [new TextRun({ text: line, size: 19, font: "Courier New", color: "1F4E79" })] }));
  }
  paragraphs.push(new Paragraph({ spacing: { before: 0, after: 100 }, border: { bottom: borderThin }, shading: { fill: "F0F7FF", type: ShadingType.CLEAR }, indent: { left: 360, right: 360 }, children: [new TextRun({ text: "" })] }));
  return paragraphs;
}
function infoBox(label, text, bgColor, textColor, borderColor) {
  return new Table({
