const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType, PageBreak
} = require('docx');
const fs = require('fs');

const borderThin = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: borderThin, bottom: borderThin, left: borderThin, right: borderThin };
const BLUE_DARK = "1F4E79";
const BLUE_MID = "2E75B6";
const BLUE_LIGHT = "D6E4F0";
const BLUE_HEADER = "1F4E79";
const GREEN_LIGHT = "E2EFDA";
const GREEN_DARK = "375623";
const AMBER_LIGHT = "FFF2CC";
const AMBER_DARK = "7F6000";
const RED_LIGHT = "FCE4D6";
const RED_DARK = "843C0C";
const PURPLE_LIGHT = "EAD1DC";
const PURPLE_DARK = "4A235A";
const GRAY_LIGHT = "F2F2F2";
const GRAY_MID = "D9D9D9";

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 180 },
    children: [new TextRun({ text, bold: true, size: 40, color: BLUE_DARK, font: "Arial" })]
  });
}
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 140 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: BLUE_MID, space: 1 } },
    children: [new TextRun({ text, bold: true, size: 30, color: BLUE_MID, font: "Arial" })]
  });
}
function h3(text, color = BLUE_DARK) {
  return new Paragraph({
    spacing: { before: 200, after: 100 },
    children: [new TextRun({ text, bold: true, size: 26, color, font: "Arial" })]
  });
}
function h4(text) {
  return new Paragraph({
    spacing: { before: 160, after: 80 },
    children: [new TextRun({ text, bold: true, size: 22, color: "555555", font: "Arial" })]
  });
}
function normal(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: "333333" })]
  });
}
function bullet(text) {
  return new Paragraph({
    spacing: { before: 40, after: 40 },
    indent: { left: 360 },
    children: [new TextRun({ text: "•  " + text, size: 22, font: "Arial", color: "333333" })]
  });
}
function spacer(n = 1) {
  return new Paragraph({ spacing: { before: 80 * n, after: 80 * n }, children: [new TextRun("")] });
}
function divider() {
  return new Paragraph({
    spacing: { before: 160, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GRAY_MID, space: 1 } },
    children: [new TextRun("")]
  });
}
function infoBox(label, text, bgColor, textColor, borderColor) {
  return new Table({
    width: { size: 9026, type: WidthType.DXA }, columnWidths: [9026],
    rows: [new TableRow({ children: [new TableCell({
      borders: {
        top: { style: BorderStyle.SINGLE, size: 4, color: borderColor },
        bottom: { style: BorderStyle.SINGLE, size: 4, color: borderColor },
        left: { style: BorderStyle.SINGLE, size: 16, color: borderColor },
        right: { style: BorderStyle.SINGLE, size: 4, color: borderColor }
      },
      shading: { fill: bgColor, type: ShadingType.CLEAR },
      margins: { top: 120, bottom: 120, left: 180, right: 180 },
      children: [
        new Paragraph({ spacing: { before: 0, after: 50 }, children: [new TextRun({ text: label, bold: true, size: 19, font: "Arial", color: borderColor })] }),
        new Paragraph({ spacing: { before: 0, after: 0 }, children: [new TextRun({ text, size: 21, font: "Arial", color: textColor })] })
      ]
    })] })]
  });
}
function tabelKolom(rows) {
  const header = new TableRow({
    tableHeader: true,
    children: [
      cell("Nama Kolom", 2100, BLUE_HEADER, "FFFFFF", true),
      cell("Tipe Data", 1400, BLUE_HEADER, "FFFFFF", true),
      cell("Constraint", 1400, BLUE_HEADER, "FFFFFF", true),
      cell("Keterangan", 4126, BLUE_HEADER, "FFFFFF", true),
    ]
  });
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [2100, 1400, 1400, 4126],
    rows: [header, ...rows.map((r, i) => new TableRow({
      children: [
        cellData(r[0], 2100, i, "Courier New", "1F4E79"),
        cellData(r[1], 1400, i, "Courier New", "843C0C"),
        cellData(r[2], 1400, i, "Arial", "843C0C", true),
        cellData(r[3], 4126, i, "Arial", "333333"),
      ]
    }))]
  });
}
function cell(text, width, bg, color, bold = false) {
  return new TableCell({
    borders, shading: { fill: bg, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    width: { size: width, type: WidthType.DXA },
    children: [new Paragraph({ children: [new TextRun({ text, bold, size: 20, font: "Arial", color })] })]
  });
}
function cellData(text, width, i, font, color, bold = false) {
  return new TableCell({
    borders, shading: { fill: i % 2 === 0 ? "FFFFFF" : GRAY_LIGHT, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    width: { size: width, type: WidthType.DXA },
    children: [new Paragraph({ children: [new TextRun({ text, bold, size: 20, font, color })] })]
  });
}
function relasiTable(rows) {
  const header = new TableRow({
    tableHeader: true,
    children: [
      cell("Tabel Asal", 2000, BLUE_HEADER, "FFFFFF", true),
      cell("Relasi", 1200, BLUE_HEADER, "FFFFFF", true),
      cell("Tabel Tujuan", 2000, BLUE_HEADER, "FFFFFF", true),
      cell("Penjelasan", 3826, BLUE_HEADER, "FFFFFF", true),
    ]
  });
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [2000, 1200, 2000, 3826],
    rows: [header, ...rows.map((r, i) => new TableRow({
      children: [
        cellData(r[0], 2000, i, "Courier New", "1F4E79"),
        new TableCell({
          borders, shading: { fill: i % 2 === 0 ? "FFFFFF" : GRAY_LIGHT, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          width: { size: 1200, type: WidthType.DXA },
          children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: r[1], bold: true, size: 20, font: "Arial", color: BLUE_MID })] })]
        }),
        cellData(r[2], 2000, i, "Courier New", "1F4E79"),
        cellData(r[3], 3826, i, "Arial", "333333"),
      ]
    }))]
  });
}

// ===================== TABLE SECTION BUILDER =====================
function tableSection(no, name, fase, group, purpose, why, cols, notes = []) {
  const items = [
    new Paragraph({
      spacing: { before: 280, after: 120 },
      border: { left: { style: BorderStyle.SINGLE, size: 16, color: BLUE_MID }, bottom: { style: BorderStyle.SINGLE, size: 4, color: BLUE_LIGHT } },
      shading: { fill: "F0F7FF", type: ShadingType.CLEAR },
      indent: { left: 200 },
      children: [
        new TextRun({ text: `${no}. `, bold: true, size: 32, color: BLUE_MID, font: "Arial" }),
        new TextRun({ text: name, bold: true, size: 32, color: BLUE_DARK, font: "Courier New" }),
        new TextRun({ text: `   —   ${group}`, size: 22, color: "888888", font: "Arial" }),
      ]
    }),
    new Table({
      width: { size: 9026, type: WidthType.DXA }, columnWidths: [2000, 3513, 3513],
      rows: [new TableRow({ children: [
        new TableCell({ borders, shading: { fill: BLUE_LIGHT, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, width: { size: 2000, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun({ text: "Fase Pembuatan", bold: true, size: 20, font: "Arial", color: BLUE_DARK })] })] }),
        new TableCell({ borders, shading: { fill: BLUE_LIGHT, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, width: { size: 3513, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun({ text: "Tujuan Utama", bold: true, size: 20, font: "Arial", color: BLUE_DARK })] })] }),
        new TableCell({ borders, shading: { fill: BLUE_LIGHT, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, width: { size: 3513, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun({ text: "Mengapa Perlu Ada?", bold: true, size: 20, font: "Arial", color: BLUE_DARK })] })] }),
      ]}),
      new TableRow({ children: [
        new TableCell({ borders, shading: { fill: "FFFFFF", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, width: { size: 2000, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun({ text: fase, size: 20, font: "Arial", color: "333333" })] })] }),
        new TableCell({ borders, shading: { fill: "FFFFFF", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, width: { size: 3513, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun({ text: purpose, size: 20, font: "Arial", color: "333333" })] })] }),
        new TableCell({ borders, shading: { fill: "FFFFFF", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, width: { size: 3513, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun({ text: why, size: 20, font: "Arial", color: "333333" })] })] }),
      ]})
      ]
    }),
    spacer(),
    h4("Struktur Kolom:"),
    tabelKolom(cols),
  ];
  if (notes.length > 0) {
    items.push(spacer());
    for (const n of notes) {
      items.push(infoBox(n[0], n[1], n[2], n[3], n[4]));
      items.push(spacer());
    }
  }
  items.push(divider());
  return items;
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 40, bold: true, font: "Arial", color: BLUE_DARK }, paragraph: { spacing: { before: 360, after: 180 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 30, bold: true, font: "Arial", color: BLUE_MID }, paragraph: { spacing: { before: 280, after: 140 }, outlineLevel: 1 } },
    ]
  },
  sections: [{
    properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1440, right: 1260, bottom: 1440, left: 1260 } } },
    children: [

