<?php

namespace Database\Seeders;

use App\Models\User;
use App\Models\ApplicantCv;
use App\Models\CvTemplate;
use App\Models\WorkExperience;
use App\Models\Education;
use App\Models\ApplicantSkill;
use Illuminate\Database\Seeder;

class ApplicantProfileSeeder extends Seeder
{
    public function run(): void
    {
        $template = CvTemplate::where('is_active', true)->first();
        $applicants = User::where('role', 'applicant')->get();

        foreach ($applicants as $user) {

            // ===== CV =====
            ApplicantCv::create([
                'user_id'     => $user->id,
                'template_id' => $template->id,
                'title'       => 'CV Utama ' . $user->name,
                'cv_data'     => [
                    'objective' => 'Mencari posisi yang sesuai dengan kemampuan saya.',
                    'sections'  => ['experience', 'education', 'skills'],
                ],
                'is_primary'  => true,
            ]);

            // ===== PENGALAMAN KERJA =====
            WorkExperience::create([
                'user_id'      => $user->id,
                'company_name' => fake()->company(),
                'position'     => fake()->jobTitle(),
                'start_date'   => '2022-01-01',
                'end_date'     => '2023-12-31',
                'is_current'   => false,
                'description'  => 'Bertanggung jawab dalam pengelolaan sistem dan pelaporan rutin.',
            ]);

            WorkExperience::create([
                'user_id'      => $user->id,
                'company_name' => fake()->company(),
                'position'     => fake()->jobTitle(),
                'start_date'   => '2024-01-01',
                'end_date'     => null,
                'is_current'   => true,
                'description'  => 'Mengelola proses operasional dan koordinasi tim.',
            ]);

            // ===== PENDIDIKAN =====
            Education::create([
                'user_id'     => $user->id,
                'institution' => fake()->randomElement([
                    'Universitas Indonesia',
                    'Politeknik Negeri Batam',
                    'Universitas Riau',
                    'Universitas Putera Batam',
                ]),
                'degree'      => fake()->randomElement(['D3', 'S1']),
                'major'       => fake()->randomElement([
                    'Teknik Informatika',
                    'Sistem Informasi',
                    'Akuntansi',
                    'Manajemen',
                    'Teknik Industri',
                ]),
                'gpa'         => fake()->randomFloat(2, 3.00, 4.00),
                'start_year'  => 2019,
                'end_year'    => 2023,
            ]);

            // ===== SKILL =====
            $skillSets = [
                ['skill_name' => 'Microsoft Office',  'category' => 'technical',  'level' => 'expert'],
                ['skill_name' => 'Komunikasi',         'category' => 'soft',       'level' => 'expert'],
                ['skill_name' => 'Bahasa Inggris',     'category' => 'language',   'level' => 'intermediate'],
            ];

            foreach ($skillSets as $skill) {
                ApplicantSkill::create(array_merge(
                    $skill, ['user_id' => $user->id]
                ));
            }
        }

        // ===== SKILL TAMBAHAN UNTUK BUDI (IT Skills) =====
        $budi = User::where('email', 'budi@gmail.com')->first();
        if ($budi) {
            $itSkills = [
                ['skill_name' => 'Laravel',  'category' => 'technical', 'level' => 'expert'],
                ['skill_name' => 'MySQL',     'category' => 'technical', 'level' => 'intermediate'],
                ['skill_name' => 'JavaScript','category' => 'technical', 'level' => 'intermediate'],
            ];
            foreach ($itSkills as $skill) {
                ApplicantSkill::create(array_merge(
                    $skill, ['user_id' => $budi->id]
                ));
            }
        }
    }
}
