<?php

namespace Database\Seeders;

use App\Models\User;
use App\Models\JobPosting;
use App\Models\Application;
use App\Models\ApplicationStatusLog;
use App\Models\ApplicantCv;
use Illuminate\Database\Seeder;

class ApplicationSeeder extends Seeder
{
    public function run(): void
    {
        $hr1  = User::where('email', 'hr@ecogreen.com')->first();
        $budi = User::where('email', 'budi@gmail.com')->first();
        $sari = User::where('email', 'sari@gmail.com')->first();
        $rizki= User::where('email', 'rizki@gmail.com')->first();

        $jobBackend  = JobPosting::where('slug', 'backend-developer-laravel')->first();
        $jobFrontend = JobPosting::where('slug', 'frontend-developer')->first();
        $jobFinance  = JobPosting::where('slug', 'staff-keuangan-akuntansi')->first();
        $jobOps      = JobPosting::where('slug', 'operator-produksi')->first();

        $budiCv  = ApplicantCv::where('user_id', $budi->id)->first();
        $sariCv  = ApplicantCv::where('user_id', $sari->id)->first();
        $rizkiCv = ApplicantCv::where('user_id', $rizki->id)->first();

        // ===== LAMARAN 1: Budi → Backend Developer (shortlisted) =====
        $app1 = Application::create([
            'user_id'      => $budi->id,
            'job_id'       => $jobBackend->id,
            'cv_id'        => $budiCv->id,
            'cover_letter' => 'Saya sangat tertarik dengan posisi Backend Developer di PT Eco Green. Dengan pengalaman 2 tahun menggunakan Laravel dan MySQL, saya yakin dapat berkontribusi maksimal.',
            'status'       => 'shortlisted',
        ]);
        $jobBackend->increment('applicant_count');
        ApplicationStatusLog::create([
            'application_id' => $app1->id,
            'changed_by'     => $hr1->id,
            'old_status'     => 'applied',
            'new_status'     => 'reviewed',
            'reason'         => 'CV dan pengalaman sesuai dengan kebutuhan posisi.',
        ]);
        ApplicationStatusLog::create([
            'application_id' => $app1->id,
            'changed_by'     => $hr1->id,
            'old_status'     => 'reviewed',
            'new_status'     => 'shortlisted',
            'reason'         => 'Kandidat masuk dalam daftar shortlist untuk wawancara.',
        ]);

        // ===== LAMARAN 2: Budi → Frontend Developer (applied) =====
        $app2 = Application::create([
            'user_id'      => $budi->id,
            'job_id'       => $jobFrontend->id,
            'cv_id'        => $budiCv->id,
            'cover_letter' => 'Saya juga memiliki kemampuan frontend dan ingin mengembangkan keahlian di bidang ini.',
