<script>
const relations = [
  // users → semua
  { from: 't-users', to: 't-user_profiles', type: '1-1' },
  { from: 't-users', to: 't-password_reset_tokens', type: '1-n' },
  { from: 't-users', to: 't-applicant_cvs', type: '1-n' },
  { from: 't-users', to: 't-work_experiences', type: '1-n' },
  { from: 't-users', to: 't-educations', type: '1-n' },
  { from: 't-users', to: 't-applicant_skills', type: '1-n' },
  { from: 't-users', to: 't-applications', type: '1-n' },
  { from: 't-users', to: 't-job_postings', type: '1-n' },
  { from: 't-users', to: 't-saved_jobs', type: '1-n' },
  { from: 't-users', to: 't-notifications', type: '1-n' },
  { from: 't-users', to: 't-job_search_logs', type: '1-n' },
  { from: 't-users', to: 't-interviews', type: '1-n' },
  { from: 't-users', to: 't-application_status_logs', type: '1-n' },
  { from: 't-users', to: 't-interview_results', type: '1-n' },
  // cv_templates → applicant_cvs
  { from: 't-cv_templates', to: 't-applicant_cvs', type: '1-n' },
  // job_categories → job_postings
  { from: 't-job_categories', to: 't-job_postings', type: '1-n' },
  // job_postings → applications, saved_jobs
  { from: 't-job_postings', to: 't-applications', type: '1-n' },
  { from: 't-job_postings', to: 't-saved_jobs', type: '1-n' },
  // applicant_cvs → applications
  { from: 't-applicant_cvs', to: 't-applications', type: '1-n' },
  // applications → status_logs, interviews
  { from: 't-applications', to: 't-application_status_logs', type: '1-n' },
  { from: 't-applications', to: 't-interviews', type: '1-n' },
  // interviews → interview_results
  { from: 't-interviews', to: 't-interview_results', type: '1-1' },
];

function getCenter(el) {
  const rect = el.getBoundingClientRect();
  const container = document.getElementById('erd').getBoundingClientRect();
  return {
    x: rect.left - container.left + rect.width / 2,
    y: rect.top - container.top + rect.height / 2,
    top: rect.top - container.top,
    bottom: rect.bottom - container.top,
    left: rect.left - container.left,
    right: rect.right - container.left,
  };
}

window.addEventListener('load', () => {
  const svg = document.getElementById('svg-lines');
  const W = 2400, H = 1800;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);

  const colors = { '1-1': '#1D6A4E', '1-n': '#2E75B6' };

  relations.forEach(rel => {
    const fromEl = document.getElementById(rel.from);
    const toEl = document.getElementById(rel.to);
    if (!fromEl || !toEl) return;

    const f = getCenter(fromEl);
    const t = getCenter(toEl);

    // Determine best connection points
    let x1, y1, x2, y2;
    if (Math.abs(f.x - t.x) > Math.abs(f.y - t.y)) {
      // Horizontal connection
      if (f.x < t.x) { x1 = f.right; y1 = f.y; x2 = t.left; y2 = t.y; }
      else { x1 = f.left; y1 = f.y; x2 = t.right; y2 = t.y; }
    } else {
      // Vertical connection
      if (f.y < t.y) { x1 = f.x; y1 = f.bottom; x2 = t.x; y2 = t.top; }
      else { x1 = f.x; y1 = f.top; x2 = t.x; y2 = t.bottom; }
    }

    const cx1 = x1 + (x2 - x1) * 0.5;
    const cy1 = y1;
    const cx2 = x1 + (x2 - x1) * 0.5;
    const cy2 = y2;

    const color = colors[rel.type];
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', `M${x1},${y1} C${cx1},${cy1} ${cx2},${cy2} ${x2},${y2}`);
    path.setAttribute('stroke', color);
    path.setAttribute('stroke-width', '1.5');
    path.setAttribute('fill', 'none');
    path.setAttribute('opacity', '0.6');
    svg.appendChild(path);

    // Endpoint dots
    [{ x: x1, y: y1 }, { x: x2, y: y2 }].forEach(pt => {
      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', pt.x);
      circle.setAttribute('cy', pt.y);
      circle.setAttribute('r', '3');
      circle.setAttribute('fill', color);
      circle.setAttribute('opacity', '0.8');
      svg.appendChild(circle);
    });
  });
});
</script>

</body>
</html>
