<script>
function getPos(id) {
  const el = document.getElementById(id);
  const canvas = document.getElementById('canvas');
  const er = el.getBoundingClientRect();
  const cr = canvas.getBoundingClientRect();
  return {
    top: er.top - cr.top, bottom: er.bottom - cr.top,
    left: er.left - cr.left, right: er.right - cr.left,
    cx: er.left - cr.left + er.width / 2,
    cy: er.top - cr.top + er.height / 2,
  };
}

function drawLine(svg, x1, y1, x2, y2, color, dash = false) {
  const dx = (x2 - x1) * 0.5;
  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  path.setAttribute('d', `M${x1},${y1} C${x1+dx},${y1} ${x2-dx},${y2} ${x2},${y2}`);
  path.setAttribute('stroke', color);
  path.setAttribute('stroke-width', '1.8');
  path.setAttribute('fill', 'none');
  path.setAttribute('opacity', '0.7');
  if (dash) path.setAttribute('stroke-dasharray', '5,3');
  svg.appendChild(path);

  // dots at endpoints
  [{ x: x1, y: y1 }, { x: x2, y: y2 }].forEach(p => {
    const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    c.setAttribute('cx', p.x); c.setAttribute('cy', p.y);
    c.setAttribute('r', '3.5'); c.setAttribute('fill', color); c.setAttribute('opacity', '0.9');
    svg.appendChild(c);
  });
}

function connect(svg, fromId, toId, color, dash = false) {
  const f = getPos(fromId);
  const t = getPos(toId);
  let x1, y1, x2, y2;
  const hDist = Math.abs(f.cx - t.cx);
  const vDist = Math.abs(f.cy - t.cy);
  if (hDist >= vDist) {
    if (f.cx < t.cx) { x1 = f.right; y1 = f.cy; x2 = t.left; y2 = t.cy; }
    else { x1 = f.left; y1 = f.cy; x2 = t.right; y2 = t.cy; }
  } else {
    if (f.cy < t.cy) { x1 = f.cx; y1 = f.bottom; x2 = t.cx; y2 = t.top; }
    else { x1 = f.cx; y1 = f.top; x2 = t.cx; y2 = t.bottom; }
  }
  drawLine(svg, x1, y1, x2, y2, color, dash);
}

window.addEventListener('load', () => {
  const svg = document.getElementById('svg');
  const canvas = document.getElementById('canvas');
  svg.setAttribute('viewBox', `0 0 ${canvas.offsetWidth} ${canvas.offsetHeight}`);

  const BLUE = '#2E75B6';
  const GREEN = '#1D6A4E';
  const PURPLE = '#5B2D8E';

  // Grup A relations
  connect(svg, 'users', 'user_profiles', GREEN, true);      // 1-1 dashed
  connect(svg, 'users', 'password_reset_tokens', BLUE);     // 1-n
  // Grup B relations
  connect(svg, 'users', 'applicant_cvs', BLUE);
  connect(svg, 'cv_templates', 'applicant_cvs', BLUE);
  // Grup C relations
  connect(svg, 'users', 'work_experiences', PURPLE);
  connect(svg, 'users', 'educations', PURPLE);
  connect(svg, 'users', 'applicant_skills', PURPLE);
});
</script>
