const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

const BLUE = "1F4E79";
const BLUE_LIGHT = "D6E4F0";
const BLUE_MID = "2E75B6";
const GREEN = "1D6A4E";
const GREEN_LIGHT = "D6EAE0";
const ORANGE = "B45309";
const ORANGE_LIGHT = "FDEBD0";
const RED = "B91C1C";
const RED_LIGHT = "FADBD8";
const PURPLE = "5B2D8E";
const PURPLE_LIGHT = "EAE0F5";
const GRAY_LIGHT = "F2F2F2";
const BORDER_COLOR = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 4, color: BORDER_COLOR };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 200 },
    children: [new TextRun({ text, bold: true, size: 32, font: "Arial", color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 160 },
    children: [new TextRun({ text, bold: true, size: 28, font: "Arial", color: BLUE_MID })]
  });
}

function h3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 200, after: 120 },
    children: [new TextRun({ text, bold: true, size: 24, font: "Arial", color: "444444" })]
  });
}

function para(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    alignment: opts.center ? AlignmentType.CENTER : AlignmentType.JUSTIFIED,
    children: [new TextRun({ text, size: 22, font: "Arial", color: "333333", ...opts })]
  });
}

function bold(text) {
  return new TextRun({ text, bold: true, size: 22, font: "Arial", color: "333333" });
}

function note(text, color = ORANGE_LIGHT, borderColor = ORANGE) {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: borderColor } },
    indent: { left: 360 },
    children: [new TextRun({ text, size: 20, font: "Arial", color: "555555", italics: true })]
  });
}

function spacer(lines = 1) {
  return new Paragraph({ spacing: { before: 0, after: lines * 80 }, children: [new TextRun("")] });
}

function pageBreak() {
  return new Paragraph({ children: [new PageBreak()] });
}

function sectionBanner(text, bgColor) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: noBorders,
        shading: { fill: bgColor, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 200, right: 200 },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text, bold: true, size: 26, font: "Arial", color: "FFFFFF" })]
        })]
      })]
    })]
  });
}

function tableHeader(cols, widths, bgColor = BLUE) {
  return new TableRow({
    tableHeader: true,
    children: cols.map((col, i) => new TableCell({
      borders,
      shading: { fill: bgColor, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      width: { size: widths[i], type: WidthType.DXA },
      verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: col, bold: true, size: 20, font: "Arial", color: "FFFFFF" })]
      })]
    }))
  });
}

function tableRow(cells, widths, bg = "FFFFFF", bold_first = false) {
  return new TableRow({
    children: cells.map((cell, i) => new TableCell({
      borders,
      shading: { fill: bg, type: ShadingType.CLEAR },
      margins: { top: 60, bottom: 60, left: 120, right: 120 },
      width: { size: widths[i], type: WidthType.DXA },
      verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({
        children: [new TextRun({
          text: cell,
          size: 20,
          font: "Arial",
          bold: (i === 0 && bold_first),
          color: "333333"
        })]
      })]
    }))
  });
}

// ===================== CONTENT =====================

const children = [];

// COVER
children.push(
  spacer(3),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 200 },
    children: [new TextRun({ text: "LAPORAN PROGRESS PART-1", bold: true, size: 40, font: "Arial", color: BLUE })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 160 },
    children: [new TextRun({ text: "Skema Normalisasi Database", bold: true, size: 32, font: "Arial", color: BLUE_MID })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 120 },
    children: [new TextRun({ text: "Sistem E-Recruitment PT Eco Green Oleochemicals", size: 26, font: "Arial", color: "555555" })]
  }),
  new Paragraph({
