const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

const BLUE = "1F4E79"; const BLUE_LIGHT = "D6E4F0"; const BLUE_MID = "2E75B6";
const GREEN = "1D6A4E"; const GREEN_LIGHT = "D6EAE0";
const ORANGE = "B45309"; const ORANGE_LIGHT = "FDEBD0";
const RED = "B91C1C"; const RED_LIGHT = "FADBD8";
const PURPLE = "5B2D8E"; const PURPLE_LIGHT = "EAE0F5";
const TEAL = "0F766E"; const TEAL_LIGHT = "D0EBE8";
const GRAY = "F2F2F2"; const BORDER = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 4, color: BORDER };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

const h1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 360, after: 200 }, children: [new TextRun({ text: t, bold: true, size: 32, font: "Arial", color: BLUE })] });
const h2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 140 }, children: [new TextRun({ text: t, bold: true, size: 26, font: "Arial", color: BLUE_MID })] });
const h3 = t => new Paragraph({ heading: HeadingLevel.HEADING_3, spacing: { before: 180, after: 100 }, children: [new TextRun({ text: t, bold: true, size: 24, font: "Arial", color: "444444" })] });
const para = (runs) => {
  if (typeof runs === 'string') runs = [new TextRun({ text: runs, size: 22, font: "Arial", color: "333333" })];
  return new Paragraph({ spacing: { before: 80, after: 80 }, alignment: AlignmentType.JUSTIFIED, children: runs });
};
const bold = (t, c = "333333") => new TextRun({ text: t, bold: true, size: 22, font: "Arial", color: c });
const normal = t => new TextRun({ text: t, size: 22, font: "Arial", color: "333333" });
const note = (t, bg = ORANGE_LIGHT, left = ORANGE) => new Paragraph({
  spacing: { before: 120, after: 120 }, border: { left: { style: BorderStyle.SINGLE, size: 14, color: left } }, indent: { left: 400 },
  children: [new TextRun({ text: t, size: 20, font: "Arial", color: "555555", italics: true })]
});
const spacer = (n = 1) => new Paragraph({ spacing: { before: 0, after: n * 80 }, children: [new TextRun("")] });
const pb = () => new Paragraph({ children: [new PageBreak()] });
const bullet = t => new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 60, after: 60 }, children: [new TextRun({ text: t, size: 22, font: "Arial" })] });
const numbered = t => new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 60, after: 60 }, children: [new TextRun({ text: t, size: 22, font: "Arial" })] });
const tHeader = (cols, widths, bg = BLUE) => new TableRow({ tableHeader: true, children: cols.map((c, i) => new TableCell({ borders, width: { size: widths[i], type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: c, bold: true, size: 20, font: "Arial", color: "FFFFFF" })] })] })) });
const tRow = (cells, widths, bg = "FFFFFF", bf = false) => new TableRow({ children: cells.map((c, i) => new TableCell({ borders, width: { size: widths[i], type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER, children: [new Paragraph({ children: [new TextRun({ text: c, size: 20, font: "Arial", bold: i === 0 && bf, color: "333333" })] })] })) });
const highlight = (t, bg = BLUE_LIGHT, tc = BLUE) => new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360], rows: [new TableRow({ children: [new TableCell({ borders, width: { size: 9360, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 200, right: 200 }, children: [new Paragraph({ children: [new TextRun({ text: t, size: 22, font: "Arial", color: tc, bold: true })] })] })] })] });
const codeBlock = lines => new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360], rows: [new TableRow({ children: [new TableCell({ borders: noBorders, width: { size: 9360, type: WidthType.DXA }, shading: { fill: "1E2A3A", type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 200, right: 200 }, children: lines.map(l => new Paragraph({ spacing: { before: 0, after: 0 }, children: [new TextRun({ text: l, size: 18, font: "Courier New", color: "A8D8EA" })] })) })] })] });

const children = [];

// COVER
children.push(
  spacer(2),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 120 }, children: [new TextRun({ text: "MATERI BELAJAR", size: 24, font: "Arial", color: "888888", bold: true })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 160 }, border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BLUE_MID } }, children: [new TextRun({ text: "ERD — Entity Relationship Diagram", bold: true, size: 40, font: "Arial", color: BLUE })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 160, after: 120 }, children: [new TextRun({ text: "Cara Membaca, Memahami, dan Membuat ERD dari Database Kita", size: 24, font: "Arial", color: BLUE_MID })] }),
  spacer(),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Sistem E-Recruitment PT Eco Green Oleochemicals", size: 22, font: "Arial", color: "666666" })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "PBL TRPL-212 — Politeknik Batam", size: 22, font: "Arial", color: "888888" })] }),
  spacer(3),
  new Table({ width: { size: 5040, type: WidthType.DXA }, columnWidths: [5040], rows: [new TableRow({ children: [new TableCell({ borders, shading: { fill: BLUE, type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 200, right: 200 }, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Belajar 05", bold: true, size: 28, font: "Arial", color: "FFFFFF" })] })] })] })] }),
  pb()
);

// BAB 1
children.push(
  h1("Apa Itu ERD?"),
  para([bold("ERD (Entity Relationship Diagram)"), normal(" adalah diagram yang menggambarkan struktur database secara visual — menunjukkan tabel apa saja yang ada, kolom apa yang dimiliki setiap tabel, dan bagaimana tabel-tabel tersebut saling berhubungan.")]),
  spacer(),
  para("Analoginya: kalau database adalah kota, ERD adalah peta kotanya. Dengan melihat ERD, siapapun bisa langsung paham bagaimana data diorganisir tanpa harus baca kode SQL satu per satu."),
  spacer(),
  h2("Kegunaan ERD"),
  bullet("Komunikasi antar anggota tim — semua orang bisa diskusi berdasarkan gambar yang sama"),
  bullet("Dokumentasi database — bukti bahwa database dirancang dengan terstruktur"),
  bullet("Landasan sebelum coding — pastikan struktur sudah benar sebelum buat migration"),
  bullet("Membantu debug — saat ada error relasi, lihat ERD untuk cek hubungan antar tabel"),
  spacer(),
  h2("ERD vs EERD"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [1500, 3930, 3930],
    rows: [
      tHeader(["", "ERD", "EERD"], [1500, 3930, 3930]),
      tRow(["Kepanjangan", "Entity Relationship Diagram", "Enhanced Entity Relationship Diagram"], [1500, 3930, 3930]),
      tRow(["Perbedaan", "Diagram standar: entitas, atribut, relasi", "ERD + konsep tambahan: generalisasi, spesialisasi, inheritance"], [1500, 3930, 3930], GRAY),
      tRow(["Kapan dipakai", "Mayoritas project — cukup untuk menggambarkan database", "Saat ada hierarki entitas (contoh: pegawai → manajer, kasir)"], [1500, 3930, 3930]),
      tRow(["Di project kita", "Digunakan — 18 tabel tanpa hierarki kompleks", "Tidak diperlukan — tidak ada inheritance antar tabel"], [1500, 3930, 3930], GRAY),
    ]
  }),
  spacer(),
  note("Untuk tugas kita, ERD sudah cukup. EERD hanya perlu jika dosen secara khusus memintanya."),
  pb()
);

// BAB 2 — Komponen ERD
children.push(
  h1("Komponen-komponen ERD"),
  h2("1. Entitas (Entity)"),
  para([bold("Entitas"), normal(" adalah objek atau konsep yang datanya kita simpan di database. Dalam ERD, entitas digambarkan sebagai kotak (tabel).")]),
  spacer(),
  para("Di project kita, contoh entitas:"),
  bullet("users — menyimpan data semua pengguna"),
  bullet("job_postings — menyimpan data lowongan pekerjaan"),
  bullet("applications — menyimpan data lamaran yang masuk"),
  spacer(),
  h2("2. Atribut (Attribute)"),
  para([bold("Atribut"), normal(" adalah detail atau properti dari sebuah entitas. Dalam tabel database, atribut adalah kolom.")]),
  spacer(),
  para("Contoh atribut pada entitas users:"),
  bullet("id — nomor unik setiap pengguna"),
  bullet("name — nama lengkap pengguna"),
  bullet("email — alamat email untuk login"),
  bullet("role — jenis akun (hr atau applicant)"),
  spacer(),
  h3("Jenis-jenis Atribut Khusus"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [1800, 2500, 5060],
    rows: [
      tHeader(["Jenis", "Simbol/Label", "Penjelasan"], [1800, 2500, 5060]),
      tRow(["Primary Key (PK)", "PK / bergaris bawah", "Kolom yang nilainya unik — jadi identitas utama setiap baris. Contoh: users.id"], [1800, 2500, 5060]),
      tRow(["Foreign Key (FK)", "FK", "Kolom yang merujuk ke PK tabel lain. Contoh: applications.user_id merujuk ke users.id"], [1800, 2500, 5060], GRAY),
      tRow(["Unique Key (UK)", "UK / UNIQUE", "Kolom yang tidak boleh duplikat tapi bukan PK. Contoh: users.email harus unik per akun"], [1800, 2500, 5060]),
      tRow(["NOT NULL", "NN", "Kolom yang wajib diisi — tidak boleh kosong"], [1800, 2500, 5060], GRAY),
    ]
  }),
  spacer(),
  h2("3. Relasi (Relationship)"),
  para([bold("Relasi"), normal(" adalah hubungan antara dua tabel. Dalam ERD, relasi digambarkan sebagai garis yang menghubungkan dua kotak tabel.")]),
  spacer(),
  para("Setiap garis relasi memiliki notasi di kedua ujungnya yang menunjukkan kardinalitas."),
  spacer(),
  h2("4. Kardinalitas (Cardinality)"),
  para([bold("Kardinalitas"), normal(" menjelaskan berapa banyak baris dari satu tabel yang bisa berhubungan dengan baris di tabel lain.")]),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [1800, 2200, 5360],
    rows: [
      tHeader(["Tipe", "Notasi", "Penjelasan"], [1800, 2200, 5360]),
      tRow(["One to One (1:1)", "||——||", "Satu baris A berhubungan dengan tepat satu baris B. Contoh: users ↔ user_profiles"], [1800, 2200, 5360]),
      tRow(["One to Many (1:N)", "||——<", "Satu baris A bisa berhubungan dengan banyak baris B. Contoh: users → applications (satu user bisa punya banyak lamaran)"], [1800, 2200, 5360], GRAY),
      tRow(["Many to One (N:1)", ">——||", "Banyak baris A berhubungan dengan satu baris B. Sama dengan 1:N tapi dilihat dari arah sebaliknya"], [1800, 2200, 5360]),
      tRow(["Many to Many (N:M)", ">——<", "Banyak baris A bisa berhubungan dengan banyak baris B. Di database diselesaikan dengan tabel pivot"], [1800, 2200, 5360], GRAY),
    ]
  }),
  pb()
);

// BAB 3 — Relasi di Project
children.push(
  h1("Relasi di Database E-Recruitment"),
  h2("Cara Membaca Relasi ERD"),
  para("Saat melihat garis relasi di ERD, baca seperti kalimat:"),
  bullet('"Satu users BISA MEMILIKI BANYAK applications" → relasi 1:N dari users ke applications'),
  bullet('"Satu applications DIMILIKI OLEH SATU users" → relasi N:1 dari applications ke users'),
  bullet('"Satu users MEMILIKI TEPAT SATU user_profiles" → relasi 1:1'),
  spacer(),
  h2("Pengelompokan Relasi per Grup"),
  spacer(),
  h3("Grup A — Manajemen Pengguna"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
      tHeader(["Relasi", "Kardinalitas", "Penjelasan"], [2500, 1800, 5060], BLUE),
      tRow(["users → user_profiles", "1 : 1", "Setiap akun punya tepat satu profil personal — dipisah agar login lebih cepat"], [2500, 1800, 5060]),
      tRow(["users → password_reset_tokens", "1 : N", "Satu akun bisa request reset password berkali-kali (masing-masing punya token berbeda)"], [2500, 1800, 5060], BLUE_LIGHT),
    ]
  }),
  spacer(),
  h3("Grup B & C — CV dan Profil Profesional"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
      tHeader(["Relasi", "Kardinalitas", "Penjelasan"], [2500, 1800, 5060], GREEN),
      tRow(["cv_templates → applicant_cvs", "1 : N", "Satu template bisa dipakai oleh banyak pelamar untuk buat CV mereka"], [2500, 1800, 5060]),
      tRow(["users → applicant_cvs", "1 : N", "Satu pelamar bisa buat beberapa CV berbeda (misal: CV untuk IT, CV untuk keuangan)"], [2500, 1800, 5060], GREEN_LIGHT),
      tRow(["users → work_experiences", "1 : N", "Satu pelamar bisa punya banyak riwayat pengalaman kerja"], [2500, 1800, 5060]),
      tRow(["users → educations", "1 : N", "Satu pelamar bisa punya banyak riwayat pendidikan"], [2500, 1800, 5060], GREEN_LIGHT),
      tRow(["users → applicant_skills", "1 : N", "Satu pelamar bisa punya banyak skill dan sertifikasi"], [2500, 1800, 5060]),
    ]
  }),
  spacer(),
  h3("Grup D — Lowongan Pekerjaan"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
      tHeader(["Relasi", "Kardinalitas", "Penjelasan"], [2500, 1800, 5060], ORANGE),
      tRow(["job_categories → job_postings", "1 : N", "Satu kategori (misal: IT) bisa punya banyak lowongan"], [2500, 1800, 5060]),
      tRow(["users → job_postings", "1 : N", "Satu HR bisa buat banyak lowongan"], [2500, 1800, 5060], ORANGE_LIGHT),
      tRow(["users → saved_jobs", "1 : N", "Satu pelamar bisa bookmark banyak lowongan"], [2500, 1800, 5060]),
      tRow(["job_postings → saved_jobs", "1 : N", "Satu lowongan bisa di-bookmark banyak pelamar"], [2500, 1800, 5060], ORANGE_LIGHT),
    ]
  }),
  spacer(),
  h3("Grup E — Lamaran dan Pelacakan"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
      tHeader(["Relasi", "Kardinalitas", "Penjelasan"], [2500, 1800, 5060], RED),
      tRow(["users → applications", "1 : N", "Satu pelamar bisa melamar ke banyak lowongan (beda-beda)"], [2500, 1800, 5060]),
      tRow(["job_postings → applications", "1 : N", "Satu lowongan bisa menerima banyak lamaran dari pelamar berbeda"], [2500, 1800, 5060], RED_LIGHT),
      tRow(["applicant_cvs → applications", "1 : N", "Satu CV bisa digunakan untuk melamar banyak lowongan"], [2500, 1800, 5060]),
      tRow(["applications → application_status_logs", "1 : N", "Satu lamaran punya banyak catatan riwayat perubahan status"], [2500, 1800, 5060], RED_LIGHT),
      tRow(["users → job_search_logs", "1 : N (nullable)", "Pencarian bisa dilakukan oleh user yang login atau tamu (null)"], [2500, 1800, 5060]),
    ]
  }),
  spacer(),
  h3("Grup F — Wawancara dan Sistem"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
      tHeader(["Relasi", "Kardinalitas", "Penjelasan"], [2500, 1800, 5060], TEAL),
      tRow(["applications → interviews", "1 : N", "Satu lamaran bisa punya beberapa sesi wawancara (multi-tahap)"], [2500, 1800, 5060]),
      tRow(["users → interviews", "1 : N", "Satu HR bisa menjadwalkan banyak wawancara"], [2500, 1800, 5060], TEAL_LIGHT),
      tRow(["interviews → interview_results", "1 : 1", "Setiap sesi wawancara punya tepat satu hasil penilaian"], [2500, 1800, 5060]),
      tRow(["users → notifications", "1 : N", "Satu user bisa punya banyak notifikasi"], [2500, 1800, 5060], TEAL_LIGHT),
    ]
  }),
  pb()
);

// BAB 4 — Cara Baca ERD
children.push(
  h1("Cara Membaca ERD Project Kita"),
  h2("Langkah-langkah Membaca ERD"),
  numbered("Perhatikan tabel apa saja yang ada dan apa fungsinya (baca nama tabelnya)"),
  numbered("Lihat kolom mana yang PK — itu identitas unik setiap baris"),
  numbered("Cari kolom yang FK — itu tanda tabel ini bergantung pada tabel lain"),
  numbered("Ikuti garis relasi untuk memahami hubungan antar tabel"),
  numbered("Perhatikan notasi di ujung garis — itu menunjukkan kardinalitas (1:1, 1:N, N:M)"),
  spacer(),
  h2("Contoh: Alur Melamar Pekerjaan"),
  para("Ikuti alur ini di ERD untuk memahami bagaimana data mengalir saat pelamar melamar lowongan:"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [500, 2500, 2500, 3860],
    rows: [
      tHeader(["No", "Tabel", "Kolom Kunci", "Keterangan"], [500, 2500, 2500, 3860]),
      tRow(["1", "users", "id (PK), role='applicant'", "Pelamar login dengan akun ini"], [500, 2500, 2500, 3860]),
      tRow(["2", "applicant_cvs", "id (PK), user_id (FK → users.id)", "Pelamar memiliki CV yang akan dilampirkan"], [500, 2500, 2500, 3860], GRAY),
      tRow(["3", "job_postings", "id (PK), status='open'", "Lowongan yang tersedia untuk dilamar"], [500, 2500, 2500, 3860]),
      tRow(["4", "applications", "id (PK), user_id (FK), job_id (FK), cv_id (FK)", "Lamaran terbuat — menghubungkan user, lowongan, dan CV"], [500, 2500, 2500, 3860], GRAY),
      tRow(["5", "application_status_logs", "id (PK), application_id (FK)", "Setiap perubahan status lamaran dicatat di sini"], [500, 2500, 2500, 3860]),
      tRow(["6", "interviews", "id (PK), application_id (FK)", "HR jadwalkan wawancara untuk lamaran ini"], [500, 2500, 2500, 3860], GRAY),
      tRow(["7", "interview_results", "id (PK), interview_id (FK)", "HR isi hasil penilaian wawancara"], [500, 2500, 2500, 3860]),
      tRow(["8", "notifications", "id (PK), user_id (FK)", "Pelamar terima notifikasi setiap ada perubahan"], [500, 2500, 2500, 3860], GRAY),
    ]
  }),
  spacer(),
  note("Tabel applications adalah jantung dari sistem rekrutmen kita — dia menghubungkan tiga tabel sekaligus: users (siapa yang melamar), job_postings (lowongan apa), dan applicant_cvs (CV yang dilampirkan)."),
  spacer(),
  h2("Kenapa Tabel users Jadi Pusat?"),
  para("Kalau dilihat di ERD, hampir semua garis mengarah ke atau dari tabel users. Ini wajar karena:"),
  bullet("Pelamar (role: applicant) — punya profil, CV, skill, pengalaman kerja, lamaran, dan notifikasi"),
  bullet("HR (role: hr) — membuat lowongan, memproses lamaran, dan menjadwalkan wawancara"),
  bullet("Kedua jenis pengguna ini disimpan dalam satu tabel users yang dibedakan oleh kolom role"),
  spacer(),
  highlight("users adalah tabel induk utama — hampir semua tabel lain memiliki foreign key yang mengarah ke users.id", BLUE_LIGHT, BLUE),
  pb()
);

// BAB 5 — Tools ERD
children.push(
  h1("Tools untuk Membuat ERD"),
  h2("Tools yang Kita Gunakan"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2000, 2500, 4860],
    rows: [
      tHeader(["Tools", "Format Output", "Kegunaan"], [2000, 2500, 4860]),
      tRow(["dbdiagram.io", "PNG, PDF", "Tools ERD online — input kode DBML, ERD otomatis tergambar. Yang kita pakai untuk ERD PNG dikumpulkan ke dosen"], [2000, 2500, 4860]),
      tRow(["draw.io / diagrams.net", ".drawio, PNG, PDF", "Tools diagram umum — bisa impor dari SQL. Kita pakai untuk versi XML yang bisa diedit"], [2000, 2500, 4860], GRAY),
      tRow(["phpMyAdmin", ".sql", "Bisa generate ERD otomatis dari database yang sudah ada — menu Designer"], [2000, 2500, 4860]),
    ]
  }),
  spacer(),
  h2("DBML — Format Kode dbdiagram.io"),
  para("dbdiagram.io menggunakan format DBML (Database Markup Language) yang sederhana untuk mendefinisikan struktur database:"),
  spacer(1),
  codeBlock([
    "// Cara menulis DBML di dbdiagram.io",
    "",
    "Table users {",
    "  id bigint [pk, increment]",
    "  name varchar(100) [not null]",
    "  email varchar(150) [unique, not null]",
    "  role varchar(20) [note: 'ENUM: hr | applicant']",
    "  created_at timestamp",
    "}",
    "",
    "Table applications {",
    "  id bigint [pk, increment]",
    "  user_id bigint [not null]",
    "  job_id bigint [not null]",
    "  status varchar(20)",
    "}",
    "",
    "// Mendefinisikan relasi",
    "Ref: applications.user_id > users.id  // N:1",
    "Ref: applications.job_id > job_postings.id  // N:1",
  ]),
  spacer(),
  h2("Format Berkas ERD yang Dikumpulkan"),
