const fs = require('fs');

const BLUE = "1F4E79"; const BLUE_LIGHT = "D6E4F0"; const BLUE_MID = "2E75B6";
const GREEN = "1D6A4E"; const GREEN_LIGHT = "D6EAE0";
const ORANGE = "B45309"; const ORANGE_LIGHT = "FDEBD0";
const RED = "B91C1C"; const RED_LIGHT = "FADBD8";
const PURPLE = "5B2D8E"; const PURPLE_LIGHT = "EAE0F5";
const TEAL = "0F766E"; const TEAL_LIGHT = "D0EBE8";
const GRAY = "F2F2F2"; const BORDER = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 4, color: BORDER };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

const h1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 360, after: 200 }, children: [new TextRun({ text: t, bold: true, size: 32, font: "Arial", color: BLUE })] });
const h2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 140 }, children: [new TextRun({ text: t, bold: true, size: 26, font: "Arial", color: BLUE_MID })] });
const h3 = t => new Paragraph({ heading: HeadingLevel.HEADING_3, spacing: { before: 180, after: 100 }, children: [new TextRun({ text: t, bold: true, size: 24, font: "Arial", color: "444444" })] });
const para = (runs) => {
  if (typeof runs === 'string') runs = [new TextRun({ text: runs, size: 22, font: "Arial", color: "333333" })];
  return new Paragraph({ spacing: { before: 80, after: 80 }, alignment: AlignmentType.JUSTIFIED, children: runs });
};
const bold = (t, c = "333333") => new TextRun({ text: t, bold: true, size: 22, font: "Arial", color: c });
const normal = t => new TextRun({ text: t, size: 22, font: "Arial", color: "333333" });
const note = (t, bg = ORANGE_LIGHT, left = ORANGE) => new Paragraph({
  spacing: { before: 120, after: 120 }, border: { left: { style: BorderStyle.SINGLE, size: 14, color: left } }, indent: { left: 400 },
  children: [new TextRun({ text: t, size: 20, font: "Arial", color: "555555", italics: true })]
});
const spacer = (n = 1) => new Paragraph({ spacing: { before: 0, after: n * 80 }, children: [new TextRun("")] });
const pb = () => new Paragraph({ children: [new PageBreak()] });
const bullet = t => new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 60, after: 60 }, children: [new TextRun({ text: t, size: 22, font: "Arial" })] });
const numbered = t => new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 60, after: 60 }, children: [new TextRun({ text: t, size: 22, font: "Arial" })] });
const tHeader = (cols, widths, bg = BLUE) => new TableRow({ tableHeader: true, children: cols.map((c, i) => new TableCell({ borders, width: { size: widths[i], type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: c, bold: true, size: 20, font: "Arial", color: "FFFFFF" })] })] })) });
const tRow = (cells, widths, bg = "FFFFFF", bf = false) => new TableRow({ children: cells.map((c, i) => new TableCell({ borders, width: { size: widths[i], type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER, children: [new Paragraph({ children: [new TextRun({ text: c, size: 20, font: "Arial", bold: i === 0 && bf, color: "333333" })] })] })) });
const highlight = (t, bg = BLUE_LIGHT, tc = BLUE) => new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360], rows: [new TableRow({ children: [new TableCell({ borders, width: { size: 9360, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 200, right: 200 }, children: [new Paragraph({ children: [new TextRun({ text: t, size: 22, font: "Arial", color: tc, bold: true })] })] })] })] });
const codeBlock = lines => new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360], rows: [new TableRow({ children: [new TableCell({ borders: noBorders, width: { size: 9360, type: WidthType.DXA }, shading: { fill: "1E2A3A", type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 200, right: 200 }, children: lines.map(l => new Paragraph({ spacing: { before: 0, after: 0 }, children: [new TextRun({ text: l, size: 18, font: "Courier New", color: "A8D8EA" })] })) })] })] });

const children = [];

// COVER
children.push(
  spacer(2),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 120 }, children: [new TextRun({ text: "MATERI BELAJAR", size: 24, font: "Arial", color: "888888", bold: true })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 160 }, border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BLUE_MID } }, children: [new TextRun({ text: "ERD — Entity Relationship Diagram", bold: true, size: 40, font: "Arial", color: BLUE })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 160, after: 120 }, children: [new TextRun({ text: "Cara Membaca, Memahami, dan Membuat ERD dari Database Kita", size: 24, font: "Arial", color: BLUE_MID })] }),
  spacer(),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Sistem E-Recruitment PT Eco Green Oleochemicals", size: 22, font: "Arial", color: "666666" })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "PBL TRPL-212 — Politeknik Batam", size: 22, font: "Arial", color: "888888" })] }),
  spacer(3),
  new Table({ width: { size: 5040, type: WidthType.DXA }, columnWidths: [5040], rows: [new TableRow({ children: [new TableCell({ borders, shading: { fill: BLUE, type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 200, right: 200 }, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Belajar 05", bold: true, size: 28, font: "Arial", color: "FFFFFF" })] })] })] })] }),
  pb()
);

// BAB 1
children.push(
