  para([bold("ERD (Entity Relationship Diagram)"), normal(" adalah diagram yang menggambarkan struktur database secara visual — menunjukkan tabel apa saja yang ada, kolom apa yang dimiliki setiap tabel, dan bagaimana tabel-tabel tersebut saling berhubungan.")]),
  spacer(),
  para("Analoginya: kalau database adalah kota, ERD adalah peta kotanya. Dengan melihat ERD, siapapun bisa langsung paham bagaimana data diorganisir tanpa harus baca kode SQL satu per satu."),
  spacer(),
  h2("Kegunaan ERD"),
  bullet("Komunikasi antar anggota tim — semua orang bisa diskusi berdasarkan gambar yang sama"),
  bullet("Dokumentasi database — bukti bahwa database dirancang dengan terstruktur"),
  bullet("Landasan sebelum coding — pastikan struktur sudah benar sebelum buat migration"),
  bullet("Membantu debug — saat ada error relasi, lihat ERD untuk cek hubungan antar tabel"),
  spacer(),
  h2("ERD vs EERD"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [1500, 3930, 3930],
    rows: [
      tHeader(["", "ERD", "EERD"], [1500, 3930, 3930]),
      tRow(["Kepanjangan", "Entity Relationship Diagram", "Enhanced Entity Relationship Diagram"], [1500, 3930, 3930]),
      tRow(["Perbedaan", "Diagram standar: entitas, atribut, relasi", "ERD + konsep tambahan: generalisasi, spesialisasi, inheritance"], [1500, 3930, 3930], GRAY),
      tRow(["Kapan dipakai", "Mayoritas project — cukup untuk menggambarkan database", "Saat ada hierarki entitas (contoh: pegawai → manajer, kasir)"], [1500, 3930, 3930]),
      tRow(["Di project kita", "Digunakan — 18 tabel tanpa hierarki kompleks", "Tidak diperlukan — tidak ada inheritance antar tabel"], [1500, 3930, 3930], GRAY),
    ]
  }),
  spacer(),
  note("Untuk tugas kita, ERD sudah cukup. EERD hanya perlu jika dosen secara khusus memintanya."),
  pb()
);

// BAB 2 — Komponen ERD
children.push(
  h1("Komponen-komponen ERD"),
  h2("1. Entitas (Entity)"),
  para([bold("Entitas"), normal(" adalah objek atau konsep yang datanya kita simpan di database. Dalam ERD, entitas digambarkan sebagai kotak (tabel).")]),
  spacer(),
  para("Di project kita, contoh entitas:"),
  bullet("users — menyimpan data semua pengguna"),
  bullet("job_postings — menyimpan data lowongan pekerjaan"),
  bullet("applications — menyimpan data lamaran yang masuk"),
  spacer(),
  h2("2. Atribut (Attribute)"),
  para([bold("Atribut"), normal(" adalah detail atau properti dari sebuah entitas. Dalam tabel database, atribut adalah kolom.")]),
  spacer(),
  para("Contoh atribut pada entitas users:"),
  bullet("id — nomor unik setiap pengguna"),
  bullet("name — nama lengkap pengguna"),
  bullet("email — alamat email untuk login"),
  bullet("role — jenis akun (hr atau applicant)"),
  spacer(),
  h3("Jenis-jenis Atribut Khusus"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [1800, 2500, 5060],
    rows: [
      tHeader(["Jenis", "Simbol/Label", "Penjelasan"], [1800, 2500, 5060]),
      tRow(["Primary Key (PK)", "PK / bergaris bawah", "Kolom yang nilainya unik — jadi identitas utama setiap baris. Contoh: users.id"], [1800, 2500, 5060]),
      tRow(["Foreign Key (FK)", "FK", "Kolom yang merujuk ke PK tabel lain. Contoh: applications.user_id merujuk ke users.id"], [1800, 2500, 5060], GRAY),
      tRow(["Unique Key (UK)", "UK / UNIQUE", "Kolom yang tidak boleh duplikat tapi bukan PK. Contoh: users.email harus unik per akun"], [1800, 2500, 5060]),
      tRow(["NOT NULL", "NN", "Kolom yang wajib diisi — tidak boleh kosong"], [1800, 2500, 5060], GRAY),
    ]
  }),
  spacer(),
  h2("3. Relasi (Relationship)"),
  para([bold("Relasi"), normal(" adalah hubungan antara dua tabel. Dalam ERD, relasi digambarkan sebagai garis yang menghubungkan dua kotak tabel.")]),
  spacer(),
  para("Setiap garis relasi memiliki notasi di kedua ujungnya yang menunjukkan kardinalitas."),
  spacer(),
  h2("4. Kardinalitas (Cardinality)"),
  para([bold("Kardinalitas"), normal(" menjelaskan berapa banyak baris dari satu tabel yang bisa berhubungan dengan baris di tabel lain.")]),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [1800, 2200, 5360],
    rows: [
      tHeader(["Tipe", "Notasi", "Penjelasan"], [1800, 2200, 5360]),
      tRow(["One to One (1:1)", "||——||", "Satu baris A berhubungan dengan tepat satu baris B. Contoh: users ↔ user_profiles"], [1800, 2200, 5360]),
      tRow(["One to Many (1:N)", "||——<", "Satu baris A bisa berhubungan dengan banyak baris B. Contoh: users → applications (satu user bisa punya banyak lamaran)"], [1800, 2200, 5360], GRAY),
      tRow(["Many to One (N:1)", ">——||", "Banyak baris A berhubungan dengan satu baris B. Sama dengan 1:N tapi dilihat dari arah sebaliknya"], [1800, 2200, 5360]),
      tRow(["Many to Many (N:M)", ">——<", "Banyak baris A bisa berhubungan dengan banyak baris B. Di database diselesaikan dengan tabel pivot"], [1800, 2200, 5360], GRAY),
    ]
  }),
  pb()
);

// BAB 3 — Relasi di Project
children.push(
  h1("Relasi di Database E-Recruitment"),
  h2("Cara Membaca Relasi ERD"),
