    ]
  }),
  spacer(),
  h3("Grup B & C — CV dan Profil Profesional"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
