      tRow(["cv_templates → applicant_cvs", "1 : N", "Satu template bisa dipakai oleh banyak pelamar untuk buat CV mereka"], [2500, 1800, 5060]),
      tRow(["users → applicant_cvs", "1 : N", "Satu pelamar bisa buat beberapa CV berbeda (misal: CV untuk IT, CV untuk keuangan)"], [2500, 1800, 5060], GREEN_LIGHT),
      tRow(["users → work_experiences", "1 : N", "Satu pelamar bisa punya banyak riwayat pengalaman kerja"], [2500, 1800, 5060]),
      tRow(["users → educations", "1 : N", "Satu pelamar bisa punya banyak riwayat pendidikan"], [2500, 1800, 5060], GREEN_LIGHT),
      tRow(["users → applicant_skills", "1 : N", "Satu pelamar bisa punya banyak skill dan sertifikasi"], [2500, 1800, 5060]),
    ]
  }),
  spacer(),
  h3("Grup D — Lowongan Pekerjaan"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
      tHeader(["Relasi", "Kardinalitas", "Penjelasan"], [2500, 1800, 5060], ORANGE),
      tRow(["job_categories → job_postings", "1 : N", "Satu kategori (misal: IT) bisa punya banyak lowongan"], [2500, 1800, 5060]),
      tRow(["users → job_postings", "1 : N", "Satu HR bisa buat banyak lowongan"], [2500, 1800, 5060], ORANGE_LIGHT),
      tRow(["users → saved_jobs", "1 : N", "Satu pelamar bisa bookmark banyak lowongan"], [2500, 1800, 5060]),
      tRow(["job_postings → saved_jobs", "1 : N", "Satu lowongan bisa di-bookmark banyak pelamar"], [2500, 1800, 5060], ORANGE_LIGHT),
    ]
  }),
  spacer(),
  h3("Grup E — Lamaran dan Pelacakan"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2500, 1800, 5060],
    rows: [
