  h2("EERD Menambahkan Konsep Baru"),
  para("EERD (Enhanced ERD) adalah perluasan dari ERD yang menambahkan tiga konsep utama yang tidak ada di ERD biasa:"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2000, 3000, 4360],
    rows: [
      tHeader(["Konsep EERD", "Definisi", "Contoh"], [2000, 3000, 4360]),
      tRow(["Generalisasi", "Proses menggabungkan beberapa entitas yang serupa menjadi satu entitas umum (dari spesifik ke umum)", "Manager, Kasir, Security → digeneralisasi menjadi Pegawai"], [2000, 3000, 4360]),
      tRow(["Spesialisasi", "Kebalikan generalisasi — memecah satu entitas umum menjadi entitas-entitas yang lebih spesifik", "Pengguna → dipecah menjadi HR dan Pelamar (dengan atribut berbeda)"], [2000, 3000, 4360], GRAY),
      tRow(["Inheritance", "Entitas anak mewarisi semua atribut entitas induk dan bisa punya atribut tambahan sendiri", "HR dan Pelamar sama-sama punya name, email (dari Pengguna), tapi punya atribut unik masing-masing"], [2000, 3000, 4360]),
