{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

const BLUE = "1F4E79"; const BLUE_MID = "2E75B6"; const BLUE_LIGHT = "D6E4F0";
const GREEN = "1D6A4E"; const GREEN_LIGHT = "D6EAE0"; const GREEN_MID = "14A97A";
const ORANGE = "B45309"; const ORANGE_LIGHT = "FDEBD0";
const RED = "B91C1C"; const RED_LIGHT = "FADBD8";
const PURPLE = "5B2D8E"; const PURPLE_LIGHT = "EAE0F5";
const TEAL = "0F766E"; const TEAL_LIGHT = "D0EBE8";
const GRAY = "F5F5F5"; const GRAY2 = "E8E8E8"; const BORDER_C = "CCCCCC";

const bdr = { style: BorderStyle.SINGLE, size: 4, color: BORDER_C };
const bdrs = { top: bdr, bottom: bdr, left: bdr, right: bdr };
const noBdr = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBdrs = { top: noBdr, bottom: noBdr, left: noBdr, right: noBdr };

const h1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 360, after: 160 }, children: [new TextRun({ text: t, bold: true, size: 30, font: "Arial", color: BLUE })] });
const h2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 120 }, children: [new TextRun({ text: t, bold: true, size: 24, font: "Arial", color: BLUE_MID })] });
const para = t => new Paragraph({ spacing: { before: 60, after: 60 }, alignment: AlignmentType.JUSTIFIED, children: [new TextRun({ text: t, size: 22, font: "Arial", color: "333333" })] });
const spacer = (n = 1) => new Paragraph({ spacing: { before: 0, after: n * 80 }, children: [new TextRun("")] });
const pb = () => new Paragraph({ children: [new PageBreak()] });

// Group banner
function groupBanner(label, name, color) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      borders: noBdrs, width: { size: 9360, type: WidthType.DXA },
      shading: { fill: color, type: ShadingType.CLEAR },
      margins: { top: 120, bottom: 120, left: 240, right: 240 },
      children: [new Paragraph({ children: [new TextRun({ text: `${label}  —  ${name}`, bold: true, size: 26, font: "Arial", color: "FFFFFF" })] })]
    })] })]
  });
}

// Table header for schema
function schHeader() {
  const cols = ["Nama Kolom", "Tipe Data", "Constraint", "Default", "Keterangan"];
  const widths = [2000, 1600, 1500, 900, 3360];
  return new TableRow({
    tableHeader: true,
    children: cols.map((c, i) => new TableCell({
      borders: bdrs, width: { size: widths[i], type: WidthType.DXA },
      shading: { fill: "2E75B6", type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: c, bold: true, size: 18, font: "Arial", color: "FFFFFF" })] })]
    }))
  });
}

function schRow(col, type, constraint, defVal, desc, bg = "FFFFFF") {
  const widths = [2000, 1600, 1500, 900, 3360];
  const vals = [col, type, constraint, defVal, desc];
  // highlight PK/FK in constraint
  const isPK = constraint.includes("PK");
  const isFK = constraint.includes("FK");
  const constraintColor = isPK ? "B91C1C" : isFK ? "1D6A4E" : "333333";

  return new TableRow({
    children: vals.map((v, i) => new TableCell({
      borders: bdrs, width: { size: widths[i], type: WidthType.DXA },
      shading: { fill: bg, type: ShadingType.CLEAR },
      margins: { top: 50, bottom: 50, left: 100, right: 100 },
      children: [new Paragraph({ children: [new TextRun({
        text: v, size: 18, font: i <= 1 ? "Courier New" : "Arial",
        color: i === 2 ? constraintColor : "333333",
        bold: i === 0 || (i === 2 && (isPK || isFK))
      })] })]
    }))
  });
}

function tableNote(text, color = BLUE_LIGHT, leftColor = BLUE_MID) {
  return new Paragraph({
    spacing: { before: 80, after: 120 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: leftColor } },
    indent: { left: 360 },
    children: [new TextRun({ text, size: 18, font: "Arial", color: "555555", italics: true })]
  });
}

function relRow(col, ref, card, bg = "FFFFFF") {
  return new TableRow({ children: [
    new TableCell({ borders: bdrs, width: { size: 2200, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: col, size: 18, font: "Courier New", color: "333333" })] })] }),
    new TableCell({ borders: bdrs, width: { size: 2800, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: ref, size: 18, font: "Courier New", color: GREEN })] })] }),
    new TableCell({ borders: bdrs, width: { size: 4360, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: card, size: 18, font: "Arial", color: "333333" })] })] }),
  ]});
}

function relTable(rels) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2200, 2800, 4360],
    rows: [
      new TableRow({ tableHeader: true, children: [
        new TableCell({ borders: bdrs, width: { size: 2200, type: WidthType.DXA }, shading: { fill: GREEN, type: ShadingType.CLEAR }, margins: { top: 60, bottom: 60, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: "Foreign Key", bold: true, size: 18, font: "Arial", color: "FFFFFF" })] })] }),
        new TableCell({ borders: bdrs, width: { size: 2800, type: WidthType.DXA }, shading: { fill: GREEN, type: ShadingType.CLEAR }, margins: { top: 60, bottom: 60, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: "Referensi ke", bold: true, size: 18, font: "Arial", color: "FFFFFF" })] })] }),
        new TableCell({ borders: bdrs, width: { size: 4360, type: WidthType.DXA }, shading: { fill: GREEN, type: ShadingType.CLEAR }, margins: { top: 60, bottom: 60, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: "Kardinalitas & Keterangan", bold: true, size: 18, font: "Arial", color: "FFFFFF" })] })] }),
      ]}),
      ...rels.map((r, i) => relRow(r[0], r[1], r[2], i % 2 === 0 ? "FFFFFF" : GREEN_LIGHT))
    ]
  });
}

function schemaTable(cols) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2000, 1600, 1500, 900, 3360],
    rows: [schHeader(), ...cols.map((c, i) => schRow(c[0], c[1], c[2], c[3], c[4], i % 2 === 0 ? "FFFFFF" : GRAY))]
  });
}

// =========================================================
const children = [];

// COVER
children.push(
  spacer(2),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 100 }, children: [new TextRun({ text: "LAPORAN PERKEMBANGAN PROJECT", size: 24, font: "Arial", color: "888888", bold: true })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 200 }, border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: BLUE_MID } }, children: [new TextRun({ text: "Skema Relasi Database", bold: true, size: 46, font: "Arial", color: BLUE })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 120 }, children: [new TextRun({ text: "Data Dictionary — Struktur Lengkap 18 Tabel", size: 26, font: "Arial", color: BLUE_MID })] }),
  spacer(),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Sistem E-Recruitment PT Eco Green Oleochemicals", size: 22, font: "Arial", color: "555555" })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "PBL TRPL-212 — Politeknik Batam — 2025", size: 22, font: "Arial", color: "888888" })] }),
  spacer(3),
  // Summary box
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [2340, 2340, 2340, 2340],
    rows: [new TableRow({ children: [
      ["18 Tabel", "6 Grup", "22 Relasi", "3NF"].map(t => new TableCell({
        borders: bdrs, shading: { fill: BLUE, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 120, right: 120 },
        children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: t, bold: true, size: 28, font: "Arial", color: "FFFFFF" })] })]
      }))
    ]})]
  }),
  spacer(4),
  new Table({
    width: { size: 6480, type: WidthType.DXA }, columnWidths: [3240, 3240],
    rows: [
      new TableRow({ tableHeader: true, children: [
        new TableCell({ borders: bdrs, shading: { fill: BLUE_MID, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Nama Anggota", bold: true, size: 20, font: "Arial", color: "FFFFFF" })] })] }),
        new TableCell({ borders: bdrs, shading: { fill: BLUE_MID, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "NIM", bold: true, size: 20, font: "Arial", color: "FFFFFF" })] })] }),
      ]}),
      ...[["Khayra Sakilla Ramona","4342501073"],["Faizal Kahfi Lubis","4342501077"],["Faiz Annabil","4342501071"],["Mufti","4342501084"],["Rasya' Defiya Putri Salsabila","4342501062"]].map(([n,nim], i) =>
        new TableRow({ children: [
          new TableCell({ borders: bdrs, shading: { fill: i%2===0?"FFFFFF":BLUE_LIGHT, type: ShadingType.CLEAR }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: n, size: 20, font: "Arial" })] })] }),
          new TableCell({ borders: bdrs, shading: { fill: i%2===0?"FFFFFF":BLUE_LIGHT, type: ShadingType.CLEAR }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: nim, size: 20, font: "Arial" })] })] }),
        ]})
      )
    ]
  }),
  pb()
);

// INDEX
children.push(
  h1("Daftar Tabel Database"),
  para("Database Sistem E-Recruitment terdiri dari 18 tabel yang dikelompokkan dalam 6 grup fungsional:"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [600, 2500, 1600, 4660],
    rows: [
      new TableRow({ tableHeader: true, children: ["No","Nama Tabel","Grup","Fungsi"].map(t => new TableCell({ borders: bdrs, shading: { fill: BLUE, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 100, right: 100 }, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: t, bold: true, size: 18, font: "Arial", color: "FFFFFF" })] })] })) }),
      ...[
        ["1","users","Grup A","Akun semua pengguna (HR dan pelamar)","FFFFFF"],
        ["2","user_profiles","Grup A","Data personal dan profil pelamar","F5F5F5"],
        ["3","password_reset_tokens","Grup A","Token reset password sekali pakai","FFFFFF"],
        ["4","login_attempts","Grup A","Log percobaan login untuk keamanan","F5F5F5"],
        ["5","cv_templates","Grup B","Master template CV yang tersedia","FFFFFF"],
        ["6","applicant_cvs","Grup B","CV yang dibuat pelamar berdasarkan template","F5F5F5"],
        ["7","work_experiences","Grup C","Riwayat pengalaman kerja pelamar","FFFFFF"],
        ["8","educations","Grup C","Riwayat pendidikan pelamar","F5F5F5"],
        ["9","applicant_skills","Grup C","Skill dan sertifikasi pelamar","FFFFFF"],
        ["10","job_categories","Grup D","Kategori pekerjaan (master data)","F5F5F5"],
