function drawAttr(attr, entityX, entityY) {
  const g = el('g');
  const rx = attr.label.length > 12 ? attr.label.length * 4.5 : Math.max(38, attr.label.length * 4.8);
  const ry = 13;

  // Line from attr to entity
  const line = el('line', {
    x1: attr.x, y1: attr.y,
    x2: entityX, y2: entityY,
    stroke: '#94A3B8', 'stroke-width': 1
  });
  g.appendChild(line);

  // Outer oval
  g.appendChild(el('ellipse', {
    cx: attr.x, cy: attr.y, rx, ry,
    fill: 'white',
    stroke: attr.fk ? '#1D6A4E' : '#B91C1C',
    'stroke-width': attr.pk || attr.fk ? 1.5 : 1.2,
    'stroke-dasharray': attr.fk ? '4 2' : 'none'
  }));

  // PK double oval
  if (attr.pk) {
    g.appendChild(el('ellipse', {
      cx: attr.x, cy: attr.y, rx: rx - 4, ry: ry - 3,
      fill: 'none', stroke: '#B91C1C', 'stroke-width': 1
    }));
  }

  const textEl = el('text', {
    x: attr.x, y: attr.y + 4.5,
    'text-anchor': 'middle',
    'font-size': 10,
    fill: attr.pk ? '#B91C1C' : attr.fk ? '#1D6A4E' : '#333',
    'font-weight': attr.pk || attr.fk ? 700 : 400,
    'font-style': attr.fk ? 'italic' : 'normal'
  }, attr.label);
  g.appendChild(textEl);
  svg.appendChild(g);
}

// Draw relation diamond
function drawRelation(rel) {
  const g = el('g');
  const dw = 44, dh = 22;
  const pts = `${rel.x},${rel.y - dh} ${rel.x + dw},${rel.y} ${rel.x},${rel.y + dh} ${rel.x - dw},${rel.y}`;

  // Find entities
  const fromEnt = ENTITIES.find(e => e.id === rel.from);
  const toEnt   = ENTITIES.find(e => e.id === rel.to);

  if (fromEnt) {
    g.appendChild(el('line', {
      x1: rel.x, y1: rel.y,
      x2: fromEnt.x, y2: fromEnt.y,
      stroke: '#94A3B8', 'stroke-width': 1.5
    }));
    // card1
    const mx = (rel.x + fromEnt.x) / 2;
    const my = (rel.y + fromEnt.y) / 2;
    g.appendChild(el('text', { x: mx, y: my - 5, 'text-anchor':'middle', 'font-size':12, 'font-weight':700, fill:'#475569' }, rel.card1));
  }
  if (toEnt) {
    g.appendChild(el('line', {
      x1: rel.x, y1: rel.y,
      x2: toEnt.x, y2: toEnt.y,
      stroke: '#94A3B8', 'stroke-width': 1.5
    }));
    // cardN
    const mx = (rel.x + toEnt.x) / 2;
    const my = (rel.y + toEnt.y) / 2;
    g.appendChild(el('text', { x: mx, y: my - 5, 'text-anchor':'middle', 'font-size':12, 'font-weight':700, fill:'#475569' }, rel.cardN));
  }

  g.appendChild(el('polygon', {
    points: pts,
    fill: '#FEF3E2', stroke: '#B45309', 'stroke-width': 1.5
  }));
  g.appendChild(el('text', {
    x: rel.x, y: rel.y + 4,
    'text-anchor': 'middle',
    'font-size': 10, 'font-weight': 600,
    fill: '#B45309'
  }, rel.label));

  svg.appendChild(g);
}

// Draw all relations first (behind), then attrs, then entities on top
RELATIONS.forEach(drawRelation);
ENTITIES.forEach(ent => {
  ent.attrs.forEach(attr => drawAttr(attr, ent.x, ent.y));
});
ENTITIES.forEach(drawEntity);

</script>
