const ORANGE = "B45309"; const ORANGE_LIGHT = "FDEBD0";
const RED = "B91C1C"; const RED_LIGHT = "FADBD8";
const PURPLE = "5B2D8E"; const PURPLE_LIGHT = "EAE0F5";
const GRAY = "F2F2F2"; const BORDER_C = "CCCCCC";
const DARK_RED = "7B1818"; const YELLOW_LIGHT = "FFFBEA";

const bdr = { style: BorderStyle.SINGLE, size: 4, color: BORDER_C };
const bdrs = { top: bdr, bottom: bdr, left: bdr, right: bdr };
const noBdr = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBdrs = { top: noBdr, bottom: noBdr, left: noBdr, right: noBdr };

const h1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 360, after: 200 }, children: [new TextRun({ text: t, bold: true, size: 32, font: "Arial", color: BLUE })] });
const h2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 140 }, children: [new TextRun({ text: t, bold: true, size: 26, font: "Arial", color: BLUE_MID })] });
const h3 = t => new Paragraph({ heading: HeadingLevel.HEADING_3, spacing: { before: 180, after: 100 }, children: [new TextRun({ text: t, bold: true, size: 24, font: "Arial", color: "444444" })] });
const para = (runs) => {
  if (typeof runs === 'string') runs = [new TextRun({ text: runs, size: 22, font: "Arial", color: "333333" })];
  return new Paragraph({ spacing: { before: 80, after: 80 }, alignment: AlignmentType.JUSTIFIED, children: runs });
};
const bold = (t, c = "333333") => new TextRun({ text: t, bold: true, size: 22, font: "Arial", color: c });
const normal = t => new TextRun({ text: t, size: 22, font: "Arial", color: "333333" });
const note = (t, bg = ORANGE_LIGHT, left = ORANGE) => new Paragraph({
  spacing: { before: 120, after: 120 }, border: { left: { style: BorderStyle.SINGLE, size: 14, color: left } }, indent: { left: 400 },
  children: [new TextRun({ text: t, size: 20, font: "Arial", color: "555555", italics: true })]
});
const spacer = (n = 1) => new Paragraph({ spacing: { before: 0, after: n * 80 }, children: [new TextRun("")] });
const pb = () => new Paragraph({ children: [new PageBreak()] });
const bullet = t => new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 60, after: 60 }, children: [new TextRun({ text: t, size: 22, font: "Arial" })] });
