function tHeader(cols, widths, bg = BLUE) {
  return new TableRow({ tableHeader: true, children: cols.map((c, i) => new TableCell({ borders: bdrs, width: { size: widths[i], type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 100, right: 100 }, verticalAlign: VerticalAlign.CENTER, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: c, bold: true, size: 18, font: "Arial", color: "FFFFFF" })] })] })) });
}
function tRow(cells, widths, bg = "FFFFFF", bf = false) {
  return new TableRow({ children: cells.map((c, i) => new TableCell({ borders: bdrs, width: { size: widths[i], type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 100, right: 100 }, verticalAlign: VerticalAlign.CENTER, children: [new Paragraph({ children: [new TextRun({ text: c, size: 18, font: "Arial", bold: i === 0 && bf, color: "333333" })] })] })) });
}
function highlight(t, bg = BLUE_LIGHT, tc = BLUE) {
  return new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360], rows: [new TableRow({ children: [new TableCell({ borders: bdrs, width: { size: 9360, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 200, right: 200 }, children: [new Paragraph({ children: [new TextRun({ text: t, size: 22, font: "Arial", color: tc, bold: true })] })] })] })] });
}
function codeBlock(lines) {
