  bullet("Tidak ada lagi anomali update — data HR tidak berulang di setiap baris lowongan"),
  bullet("Tidak ada lagi anomali delete — menghapus satu lowongan tidak menghapus data kategori"),
  bullet("Setiap kolom hanya bergantung pada primary key tabelnya sendiri — struktur bersih dan konsisten"),
  spacer(2),
  alertBox("Database Sistem E-Recruitment PT Eco Green Oleochemicals telah memenuhi Third Normal Form (3NF) dengan 18 tabel final, 22 relasi, dan bebas dari redundansi, partial dependency, serta transitive dependency.", C.BLUE_LIGHT, C.BLUE),
);

// ── BUILD ──
const doc = new Document({
  numbering: { config: [
    { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    { reference: "numbers", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
  ]},
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 32, bold: true, font: "Arial", color: C.BLUE }, paragraph: { spacing: { before: 360, after: 200 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 26, bold: true, font: "Arial", color: C.BLUE_MID }, paragraph: { spacing: { before: 260, after: 140 }, outlineLevel: 1 } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 24, bold: true, font: "Arial", color: "444444" }, paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 2 } },
    ]
  },
  sections: [{ properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1440, right: 1440, bottom: 1440, left: 1800 } } }, children }]
});

Packer.toBuffer(doc).then(b => {
  fs.writeFileSync('/home/claude/Skema_Normalisasi_Final.docx', b);
  console.log('Done!');
}).catch(e => { console.error(e); process.exit(1); });

display_content.json_block:
{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

// Colors
const C = {
  BLUE: "1F4E79", BLUE_MID: "2E75B6", BLUE_LIGHT: "D6E4F0",
  GREEN: "1D6A4E", GREEN_LIGHT: "D6EAE0",
  ORANGE: "B45309", ORANGE_LIGHT: "FDEBD0",
  RED: "B91C1C", RED_LIGHT: "FADBD8",
  PURPLE: "5B2D8E", PURPLE_LIGHT: "EAE0F5",
  GRAY: "F5F5F5", GRAY2: "E8E8E8", BORDER: "CCCCCC",
  WHITE: "FFFFFF"
};

const bdr = { style: BorderStyle.SINGLE, size: 4, color: C.BORDER };
const bdrs = { top: bdr, bottom: bdr, left: bdr, right: bdr };
const noBdr = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBdrs = { top: noBdr, bottom: noBdr, left: noBdr, right: noBdr };

// ── helpers ──────────────────────────────────────────────────────────────────
const h1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 360, after: 200 }, children: [new TextRun({ text: t, bold: true, size: 32, font: "Arial", color: C.BLUE })] });
const h2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 260, after: 140 }, children: [new TextRun({ text: t, bold: true, size: 26, font: "Arial", color: C.BLUE_MID })] });
const h3 = t => new Paragraph({ heading: HeadingLevel.HEADING_3, spacing: { before: 200, after: 100 }, children: [new TextRun({ text: t, bold: true, size: 24, font: "Arial", color: "444444" })] });

const para = (runs) => {
  if (typeof runs === 'string') runs = [new TextRun({ text: runs, size: 22, font: "Arial", color: "333333" })];
  return new Paragraph({ spacing: { before: 80, after: 80 }, alignment: AlignmentType.JUSTIFIED, children: runs });
};
const bold = (t, c = "333333") => new TextRun({ text: t, bold: true, size: 22, font: "Arial", color: c });
const normal = t => new TextRun({ text: t, size: 22, font: "Arial", color: "333333" });
const italic = t => new TextRun({ text: t, size: 22, font: "Arial", color: "555555", italics: true });

const note = (t, bg = C.ORANGE_LIGHT, left = C.ORANGE) => new Paragraph({
  spacing: { before: 120, after: 120 },
  border: { left: { style: BorderStyle.SINGLE, size: 14, color: left } },
  indent: { left: 400 },
  children: [new TextRun({ text: t, size: 20, font: "Arial", color: "555555", italics: true })]
});

const alertBox = (t, bg, textColor) => new Table({
  width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
  rows: [new TableRow({ children: [new TableCell({
    borders: noBdrs, shading: { fill: bg, type: ShadingType.CLEAR },
    margins: { top: 140, bottom: 140, left: 240, right: 240 },
    children: [new Paragraph({ children: [new TextRun({ text: t, size: 22, font: "Arial", color: textColor, bold: true })] })]
  })] })]
});

const spacer = (n = 1) => new Paragraph({ spacing: { before: 0, after: n * 80 }, children: [new TextRun("")] });
const pb = () => new Paragraph({ children: [new PageBreak()] });
const bullet = t => new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 60, after: 60 }, children: [new TextRun({ text: t, size: 22, font: "Arial" })] });
const numbered = t => new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 60, after: 60 }, children: [new TextRun({ text: t, size: 22, font: "Arial" })] });

// Table builder helpers
const tHdr = (cols, widths, bg = C.BLUE) => new TableRow({
  tableHeader: true,
  children: cols.map((c, i) => new TableCell({
    borders: bdrs, width: { size: widths[i], type: WidthType.DXA },
    shading: { fill: bg, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: c, bold: true, size: 20, font: "Arial", color: "FFFFFF" })] })]
  }))
});

const tRow = (cells, widths, bg = "FFFFFF", bFirst = false) => new TableRow({
  children: cells.map((c, i) => new TableCell({
    borders: bdrs, width: { size: widths[i], type: WidthType.DXA },
    shading: { fill: bg, type: ShadingType.CLEAR },
    margins: { top: 60, bottom: 60, left: 120, right: 120 },
    children: [new Paragraph({ children: [new TextRun({ text: c, size: 20, font: "Arial", bold: i === 0 && bFirst, color: "333333" })] })]
  }))
});

const spanRow = (text, totalWidth, bg = C.BLUE_MID, cols = 3) => new TableRow({
  children: [new TableCell({
    borders: bdrs,
    columnSpan: cols,
    width: { size: totalWidth, type: WidthType.DXA },
    shading: { fill: bg, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 160, right: 160 },
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 20, font: "Arial", color: "FFFFFF" })] })]
  })]
});

// Problem box — red bordered box describing issues found
function problemBox(title, problems) {
  const rows = [
    new TableRow({ children: [new TableCell({
      borders: noBdrs,
      shading: { fill: C.RED_LIGHT, type: ShadingType.CLEAR },
      margins: { top: 100, bottom: 60, left: 180, right: 180 },
      children: [new Paragraph({ children: [new TextRun({ text: title, bold: true, size: 20, font: "Arial", color: C.RED })] })]
    })] }),
    ...problems.map(p => new TableRow({ children: [new TableCell({
      borders: noBdrs,
      shading: { fill: C.RED_LIGHT, type: ShadingType.CLEAR },
      margins: { top: 30, bottom: 30, left: 220, right: 180 },
      children: [new Paragraph({ children: [new TextRun({ text: "•  " + p, size: 19, font: "Arial", color: "444444" })] })]
    })] })),
    new TableRow({ children: [new TableCell({
      borders: noBdrs,
      shading: { fill: C.RED_LIGHT, type: ShadingType.CLEAR },
      margins: { top: 60, bottom: 60, left: 180, right: 180 },
      children: [new Paragraph({ children: [new TextRun("")] })]
    })] }),
  ];
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
    rows,
    borders: {
      top: { style: BorderStyle.SINGLE, size: 6, color: C.RED },
      left: { style: BorderStyle.SINGLE, size: 6, color: C.RED },
      bottom: { style: BorderStyle.SINGLE, size: 6, color: C.RED },
      right: { style: BorderStyle.SINGLE, size: 6, color: C.RED },
    }
  });
}

// Split reason box — green box explaining why a table was split
function reasonBox(from, to, reason) {
  const toText = Array.isArray(to) ? to.join("  +  ") : to;
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
    rows: [
      new TableRow({ children: [new TableCell({
        borders: noBdrs, shading: { fill: C.GREEN_LIGHT, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 60, left: 180, right: 180 },
        children: [new Paragraph({ children: [
          new TextRun({ text: from + "  →  ", size: 20, font: "Courier New", color: C.RED, bold: true }),
          new TextRun({ text: toText, size: 20, font: "Courier New", color: C.GREEN, bold: true }),
        ] })]
      })] }),
      new TableRow({ children: [new TableCell({
        borders: noBdrs, shading: { fill: C.GREEN_LIGHT, type: ShadingType.CLEAR },
        margins: { top: 30, bottom: 100, left: 220, right: 180 },
        children: [new Paragraph({ children: [new TextRun({ text: "Alasan: " + reason, size: 19, font: "Arial", color: "333333", italics: true })] })]
      })] }),
    ],
    borders: {
      top: { style: BorderStyle.SINGLE, size: 6, color: C.GREEN },
      left: { style: BorderStyle.SINGLE, size: 6, color: C.GREEN },
      bottom: { style: BorderStyle.SINGLE, size: 6, color: C.GREEN },
      right: { style: BorderStyle.SINGLE, size: 6, color: C.GREEN },
    }
  });
}

// Column table for UNF
function colTable(columns) {
  const W1 = 400, W2 = 2600, W3 = 1600, W4 = 4760;
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [W1, W2, W3, W4],
    rows: [
      tHdr(["No", "Nama Kolom", "Tipe Data", "Keterangan Masalah"], [W1, W2, W3, W4]),
      ...columns.map(([no, col, type, desc], i) => {
        const isRepeat = desc.toLowerCase().includes("repeating") || desc.toLowerCase().includes("berulang");
        const isRedun = desc.toLowerCase().includes("redundan") || desc.toLowerCase().includes("transitive");
        const bg = isRedun ? C.RED_LIGHT : isRepeat ? C.ORANGE_LIGHT : i % 2 === 0 ? "FFFFFF" : C.GRAY;
        return new TableRow({ children: [
          new TableCell({ borders: bdrs, width: { size: W1, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 80, right: 80 }, children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: String(no), size: 18, font: "Arial", color: "666666" })] })] }),
          new TableCell({ borders: bdrs, width: { size: W2, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: col, size: 18, font: "Courier New", color: "222222" })] })] }),
          new TableCell({ borders: bdrs, width: { size: W3, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: type, size: 18, font: "Arial", color: C.BLUE_MID })] })] }),
          new TableCell({ borders: bdrs, width: { size: W4, type: WidthType.DXA }, shading: { fill: bg, type: ShadingType.CLEAR }, margins: { top: 50, bottom: 50, left: 100, right: 100 }, children: [new Paragraph({ children: [new TextRun({ text: desc, size: 18, font: "Arial", color: isRedun ? C.RED : isRepeat ? C.ORANGE : "444444" })] })] }),
        ]});
      })
    ]
  });
}

// Progress banner
function progressBanner(stages) {
  // stages = [{label, count, active}]
  const w = Math.floor(9360 / stages.length);
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: stages.map(() => w),
    rows: [new TableRow({ children: stages.map(s => new TableCell({
      borders: bdrs,
      shading: { fill: s.active ? C.BLUE : C.GRAY2, type: ShadingType.CLEAR },
      margins: { top: 120, bottom: 120, left: 100, right: 100 },
      children: [
        new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: s.label, bold: true, size: 22, font: "Arial", color: s.active ? "FFFFFF" : "888888" })] }),
        new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: s.count + " tabel", size: 18, font: "Arial", color: s.active ? "DDDDDD" : "AAAAAA" })] }),
      ]
    })) })]
  });
}

// ── DOCUMENT CONTENT ─────────────────────────────────────────────────────────
const children = [];

// COVER
children.push(
  spacer(2),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 100 },
    children: [new TextRun({ text: "LAPORAN PROGRESS PART-1", size: 24, font: "Arial", color: "888888", bold: true })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: C.BLUE_MID } },
    children: [new TextRun({ text: "Skema Normalisasi Database", bold: true, size: 46, font: "Arial", color: C.BLUE })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 120 },
    children: [new TextRun({ text: "Sistem E-Recruitment PT Eco Green Oleochemicals", size: 26, font: "Arial", color: C.BLUE_MID })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 },
    children: [new TextRun({ text: "Mata Kuliah: Perancangan Basis Data — PBL TRPL-212", size: 22, font: "Arial", color: "666666" })] }),
  spacer(2),
  progressBanner([
    { label: "UNF", count: 5, active: false },
    { label: "1NF", count: 13, active: false },
    { label: "2NF", count: 13, active: false },
    { label: "3NF", count: 18, active: false },
  ]),
  spacer(3),
  new Table({
    width: { size: 5040, type: WidthType.DXA }, columnWidths: [3240, 1800],
    rows: [
      tHdr(["Nama Anggota", "NIM"], [3240, 1800], C.BLUE_MID),
      ...[
        ["Khayra Sakilla Ramona","4342501073"],
        ["Faizal Kahfi Lubis","4342501077"],
        ["Faiz Annabil","4342501071"],
        ["Mufti","4342501084"],
        ["Rasya' Defiya Putri Salsabila","4342501062"],
      ].map((r,i) => tRow(r, [3240, 1800], i%2===0?"FFFFFF":C.BLUE_LIGHT))
    ]
  }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 240, after: 0 },
    children: [new TextRun({ text: "Politeknik Batam — 2025", size: 20, font: "Arial", color: "888888" })] }),
  pb()
);

// ── BAB 1 ──
children.push(
  h1("BAB 1 — PENDAHULUAN"),
  h2("1.1 Latar Belakang"),
  para("Perancangan basis data yang baik merupakan fondasi utama dalam pengembangan sistem informasi. Salah satu teknik yang digunakan untuk menghasilkan struktur basis data yang efisien, bebas dari redundansi, dan meminimalkan anomali adalah Normalisasi Basis Data."),
  para("Dokumen ini memaparkan proses normalisasi yang diterapkan dalam perancangan basis data Sistem E-Recruitment PT Eco Green Oleochemicals. Proses dilakukan bertahap mulai dari bentuk data awal yang belum terstruktur (UNF) hingga mencapai Third Normal Form (3NF), menghasilkan 18 tabel relasional yang saling terhubung."),
  spacer(),
  h2("1.2 Tujuan Normalisasi"),
  bullet("Menghilangkan redundansi data agar tidak ada informasi yang tersimpan berulang"),
  bullet("Mencegah anomali insert, update, dan delete yang dapat merusak integritas data"),
  bullet("Memastikan setiap atribut hanya bergantung pada primary key yang tepat"),
  bullet("Menghasilkan struktur tabel yang efisien, konsisten, dan mudah dipelihara"),
  spacer(),
  h2("1.3 Ringkasan Alur Normalisasi"),
  para("Normalisasi dilakukan dalam empat tahap dengan perkembangan jumlah tabel sebagai berikut:"),
  spacer(1),
  new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [1400, 1200, 4260, 2500],
    rows: [
      tHdr(["Tahap", "Jumlah Tabel", "Yang Dilakukan", "Perubahan"], [1400, 1200, 4260, 2500]),
      tRow(["UNF", "5 tabel", "Data awal dikelompokkan secara kasar — masih banyak masalah", "Titik awal"], [1400, 1200, 4260, 2500]),
      tRow(["1NF", "13 tabel", "Semua repeating group dipecah menjadi tabel tersendiri", "+8 tabel baru"], [1400, 1200, 4260, 2500], C.GRAY),
      tRow(["2NF", "13 tabel", "Verifikasi bahwa semua tabel bebas partial dependency", "Tidak ada perubahan struktur"], [1400, 1200, 4260, 2500]),
      tRow(["3NF", "18 tabel", "Semua transitive dependency dipisahkan ke tabel baru", "+5 tabel baru"], [1400, 1200, 4260, 2500], C.GRAY),
    ]
  }),
  pb()
);

// ── BAB 2 — UNF ──
children.push(
  h1("BAB 2 — UNNORMALIZED FORM (UNF)"),
  progressBanner([
    { label: "UNF", count: 5, active: true },
    { label: "1NF", count: 13, active: false },
    { label: "2NF", count: 13, active: false },
    { label: "3NF", count: 18, active: false },
  ]),
  spacer(),
  h2("2.1 Definisi UNF"),
  para("Unnormalized Form (UNF) adalah kondisi awal data sebelum normalisasi diterapkan. Pada tahap ini data dikelompokkan secara kasar berdasarkan fungsi utamanya — namun di dalam setiap kelompok masih terdapat berbagai pelanggaran seperti repeating groups, atribut yang tidak atomik, dan data yang redundan."),
  para([bold("Penting: "), normal("UNF bukan berarti tidak ada tabel sama sekali. UNF adalah kondisi di mana tabel sudah ada namun belum memenuhi aturan normalisasi apapun — masih kotor, campur, dan berulang.")]),
  spacer(),
  h2("2.2 Lima Tabel UNF Awal"),
  note("Kelompok oranye = Repeating Group (kolom yang berulang). Kelompok merah = Redundansi (data yang tersimpan dobel). Kolom normal = atribut yang sudah benar."),
  spacer(),

  // T1 data_pelamar
  h3("Tabel 1 — data_pelamar"),
  para("Menyimpan semua data yang berkaitan dengan kandidat dalam satu tabel besar. Data profil, pengalaman kerja, pendidikan, skill, dan CV semuanya digabung menjadi satu baris per kandidat."),
  spacer(1),
  colTable([
    [1, "kandidat_id", "BIGINT", "Identitas kandidat"],
    [2, "nama", "VARCHAR", "Data profil kandidat"],
    [3, "email", "VARCHAR", "Data profil kandidat"],
    [4, "password", "VARCHAR", "Data profil kandidat"],
    [5, "telepon", "VARCHAR", "Data profil kandidat"],
    [6, "foto", "VARCHAR", "Data profil kandidat"],
    [7, "bio", "TEXT", "Data profil kandidat"],
    [8, "alamat", "TEXT", "Data profil kandidat"],
    [9, "kota", "VARCHAR", "Data profil kandidat"],
    [10, "provinsi", "VARCHAR", "Data profil kandidat"],
    [11, "tanggal_lahir", "DATE", "Data profil kandidat"],
    [12, "jenis_kelamin", "VARCHAR", "Data profil kandidat"],
    [13, "linkedin_url", "VARCHAR", "Data profil kandidat"],
    [14, "portfolio_url", "VARCHAR", "Data profil kandidat"],
    [15, "pengalaman_1_perusahaan", "VARCHAR", "REPEATING GROUP — berulang menjadi _2, _3, dst."],
    [16, "pengalaman_1_jabatan", "VARCHAR", "REPEATING GROUP"],
    [17, "pengalaman_1_mulai", "DATE", "REPEATING GROUP"],
    [18, "pengalaman_1_selesai", "DATE", "REPEATING GROUP"],
    [19, "pengalaman_1_masih_bekerja", "BOOLEAN", "REPEATING GROUP"],
    [20, "pengalaman_1_deskripsi", "TEXT", "REPEATING GROUP"],
    [21, "pengalaman_2_perusahaan", "VARCHAR", "REPEATING GROUP — NULL jika hanya punya 1 pengalaman"],
    [22, "pengalaman_2_jabatan", "VARCHAR", "REPEATING GROUP — NULL jika tidak ada"],
    [23, "pendidikan_1_institusi", "VARCHAR", "REPEATING GROUP — berulang menjadi _2, dst."],
    [24, "pendidikan_1_jenjang", "VARCHAR", "REPEATING GROUP"],
    [25, "pendidikan_1_jurusan", "VARCHAR", "REPEATING GROUP"],
    [26, "pendidikan_1_ipk", "DECIMAL", "REPEATING GROUP"],
    [27, "skill_1_nama", "VARCHAR", "REPEATING GROUP — berulang menjadi _2, _3, dst."],
    [28, "skill_1_kategori", "VARCHAR", "REPEATING GROUP"],
    [29, "skill_1_tingkat", "VARCHAR", "REPEATING GROUP"],
    [30, "skill_2_nama", "VARCHAR", "REPEATING GROUP — NULL jika skill hanya satu"],
    [31, "cv_1_judul", "VARCHAR", "REPEATING GROUP — berulang menjadi _2, dst."],
    [32, "cv_1_template_id", "BIGINT", "REPEATING GROUP"],
    [33, "cv_1_nama_template", "VARCHAR", "REDUNDAN — bergantung pada template_id, bukan kandidat_id"],
    [34, "cv_1_preview_template", "VARCHAR", "REDUNDAN — bergantung pada template_id, bukan kandidat_id"],
    [35, "cv_1_data_cv", "JSON", "REPEATING GROUP"],
    [36, "cv_1_is_utama", "BOOLEAN", "REPEATING GROUP"],
  ]),
  spacer(),
  problemBox("Masalah yang ditemukan pada data_pelamar:", [
    "Repeating group pengalaman kerja: kolom pengalaman_1_*, pengalaman_2_* akan terus bertambah jika kandidat punya banyak pengalaman. Kandidat dengan 1 pengalaman menyebabkan kolom pengalaman_2_* hingga pengalaman_N_* berisi NULL.",
