const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

const C = {
  BLUE:"1F4E79", BLUE_MID:"2E75B6", BLUE_LIGHT:"D6E4F0",
  GREEN:"1D6A4E", GREEN_LIGHT:"D6EAE0",
  ORANGE:"B45309", ORANGE_LIGHT:"FDEBD0",
  RED:"B91C1C", RED_LIGHT:"FADBD8",
  PURPLE:"5B2D8E", PURPLE_LIGHT:"EAE0F5",
  TEAL:"0F766E", TEAL_LIGHT:"D0EBE8",
  GRAY:"F5F5F5", BORDER:"CCCCCC", WHITE:"FFFFFF"
};

const bdr={style:BorderStyle.SINGLE,size:4,color:C.BORDER};
const bdrs={top:bdr,bottom:bdr,left:bdr,right:bdr};
const noBdr={style:BorderStyle.NONE,size:0,color:"FFFFFF"};
const noBdrs={top:noBdr,bottom:noBdr,left:noBdr,right:noBdr};

const h1=t=>new Paragraph({heading:HeadingLevel.HEADING_1,spacing:{before:360,after:200},children:[new TextRun({text:t,bold:true,size:30,font:"Arial",color:C.BLUE})]});
const h2=t=>new Paragraph({heading:HeadingLevel.HEADING_2,spacing:{before:240,after:140},children:[new TextRun({text:t,bold:true,size:24,font:"Arial",color:C.BLUE_MID})]});
const h3=t=>new Paragraph({heading:HeadingLevel.HEADING_3,spacing:{before:180,after:100},children:[new TextRun({text:t,bold:true,size:22,font:"Arial",color:"444444"})]});
const para=t=>new Paragraph({spacing:{before:80,after:80},alignment:AlignmentType.JUSTIFIED,children:[new TextRun({text:t,size:22,font:"Arial",color:"333333"})]});
const spacer=(n=1)=>new Paragraph({spacing:{before:0,after:n*80},children:[new TextRun("")]});
const pb=()=>new Paragraph({children:[new PageBreak()]});
const bullet=t=>new Paragraph({numbering:{reference:"bullets",level:0},spacing:{before:60,after:60},children:[new TextRun({text:t,size:22,font:"Arial"})]});
const note=(t,bg=C.ORANGE_LIGHT,left=C.ORANGE)=>new Paragraph({spacing:{before:120,after:120},border:{left:{style:BorderStyle.SINGLE,size:14,color:left}},indent:{left:400},children:[new TextRun({text:t,size:20,font:"Arial",color:"555555",italics:true})]});

function code(lines){
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:noBdrs,shading:{fill:"1E2A3A",type:ShadingType.CLEAR},
      margins:{top:140,bottom:140,left:220,right:220},
      children:lines.map(l=>new Paragraph({spacing:{before:0,after:0},children:[new TextRun({text:l,size:18,font:"Courier New",color:"A8D8EA"})]}))
    })]})]
  });
}

function alertBox(t,bg,tc){
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:noBdrs,shading:{fill:bg,type:ShadingType.CLEAR},
      margins:{top:140,bottom:140,left:240,right:240},
      children:[new Paragraph({children:[new TextRun({text:t,size:22,font:"Arial",color:tc,bold:true})]})]
    })]})]
  });
}

const tHdr=(cols,widths,bg=C.BLUE)=>new TableRow({tableHeader:true,children:cols.map((c,i)=>new TableCell({borders:bdrs,width:{size:widths[i],type:WidthType.DXA},shading:{fill:bg,type:ShadingType.CLEAR},margins:{top:80,bottom:80,left:120,right:120},children:[new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:c,bold:true,size:20,font:"Arial",color:"FFFFFF"})]})]}))});
const tRow=(cells,widths,bg="FFFFFF")=>new TableRow({children:cells.map((c,i)=>new TableCell({borders:bdrs,width:{size:widths[i],type:WidthType.DXA},shading:{fill:bg,type:ShadingType.CLEAR},margins:{top:60,bottom:60,left:120,right:120},children:[new Paragraph({children:[new TextRun({text:c,size:20,font:"Arial",color:"333333"})]})]}))}); 

function groupBanner(label,name,color){
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:noBdrs,shading:{fill:color,type:ShadingType.CLEAR},
      margins:{top:120,bottom:120,left:240,right:240},
      children:[new Paragraph({children:[new TextRun({text:label+" — "+name,bold:true,size:24,font:"Arial",color:"FFFFFF"})]})]
    })]})]
  });
}

const MEMBERS=[
  ["Khayra Sakilla Ramona","4342501073"],
  ["Faizal Kahfi Lubis","4342501077"],
  ["Faiz Annabil","4342501071"],
  ["Mufti","4342501084"],
  ["Rasya' Defiya Putri Salsabila","4342501062"],
];

function makeCover(title,subtitle,num){
  return [
    spacer(2),
    new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:0,after:100},children:[new TextRun({text:"LAPORAN PROGRESS PART-1",size:24,font:"Arial",color:"888888",bold:true})]}),
    new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:0,after:200},border:{bottom:{style:BorderStyle.SINGLE,size:8,color:C.BLUE_MID}},children:[new TextRun({text:title,bold:true,size:44,font:"Arial",color:C.BLUE})]}),
    new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:200,after:120},children:[new TextRun({text:subtitle,size:24,font:"Arial",color:C.BLUE_MID})]}),
    new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:0,after:80},children:[new TextRun({text:"Sistem E-Recruitment PT Eco Green Oleochemicals",size:22,font:"Arial",color:"555555"})]}),
    new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:0,after:80},children:[new TextRun({text:"PBL TRPL-212 — Politeknik Batam — 2025",size:22,font:"Arial",color:"888888"})]}),
    spacer(3),
    new Table({
      width:{size:5040,type:WidthType.DXA},columnWidths:[3240,1800],
      rows:[tHdr(["Nama Anggota","NIM"],[3240,1800],C.BLUE_MID),...MEMBERS.map((r,i)=>tRow(r,[3240,1800],i%2===0?"FFFFFF":C.BLUE_LIGHT))]
    }),
    pb()
  ];
}

// ═══════════════════════════════════════════════════════
// DOKUMEN 1: IDENTIFIKASI TABEL
// ═══════════════════════════════════════════════════════
const doc1children=[];

doc1children.push(...makeCover("Identifikasi Tabel","Komponen 1 dari 3 — Progress Report Part-1","1"));

doc1children.push(
  h1("BAB 1 — PENDAHULUAN"),
  h2("1.1 Latar Belakang"),
  para("Identifikasi tabel merupakan tahap awal dalam perancangan basis data. Pada tahap ini, dilakukan analisis terhadap kebutuhan sistem untuk menentukan entitas-entitas apa saja yang perlu disimpan datanya, serta hubungan antar entitas tersebut."),
  para("Dokumen ini memaparkan hasil identifikasi seluruh tabel yang dibutuhkan oleh Sistem E-Recruitment PT Eco Green Oleochemicals — sistem perekrutan karyawan berbasis web yang memungkinkan kandidat melamar pekerjaan secara online dan HR mengelola proses rekrutmen secara digital."),
  spacer(),
  h2("1.2 Hasil Identifikasi"),
  para("Berdasarkan analisis kebutuhan sistem, ditemukan 18 tabel yang dikelompokkan dalam 6 grup fungsional:"),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[1200,1200,2500,4460],
    rows:[
      tHdr(["Grup","Jumlah Tabel","Nama Grup","Fungsi Utama"],[1200,1200,2500,4460]),
      tRow(["A","4 tabel","Pengguna & Autentikasi","Mengelola akun, profil, dan keamanan login pengguna"],[1200,1200,2500,4460]),
      tRow(["B","2 tabel","CV & Template","Mengelola CV pelamar dan template desain CV"],[1200,1200,2500,4460],C.GRAY),
      tRow(["C","3 tabel","Profil Profesional","Menyimpan riwayat kerja, pendidikan, dan skill pelamar"],[1200,1200,2500,4460]),
      tRow(["D","3 tabel","Lowongan Pekerjaan","Mengelola kategori dan data lowongan yang dibuka HR"],[1200,1200,2500,4460],C.GRAY),
      tRow(["E","3 tabel","Lamaran & Pelacakan","Mengelola lamaran masuk, status, dan log pencarian"],[1200,1200,2500,4460]),
      tRow(["F","3 tabel","Wawancara & Notifikasi","Mengelola jadwal wawancara, hasil penilaian, dan notifikasi"],[1200,1200,2500,4460],C.GRAY),
    ]
  }),
  pb()
);

// GRUP A
doc1children.push(
  h1("BAB 2 — IDENTIFIKASI TABEL PER GRUP"),
  groupBanner("GRUP A","Pengguna & Autentikasi",C.BLUE),
  spacer(),
  para("Grup ini mengelola semua data yang berkaitan dengan akun pengguna — baik HR maupun pelamar — termasuk keamanan login dan reset password."),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[400,2000,2000,4960],
    rows:[
      tHdr(["No","Nama Tabel","Primary Key","Fungsi Tabel"],[400,2000,2000,4960]),
      tRow(["1","users","id (BIGINT, PK)","Menyimpan akun semua pengguna — HR dan pelamar — dibedakan oleh kolom role (enum: hr / applicant)"],[400,2000,2000,4960]),
      tRow(["2","user_profiles","id (BIGINT, PK)","Menyimpan data profil detail pelamar — bio, alamat, kota, foto, LinkedIn. Relasi 1:1 dengan users"],[400,2000,2000,4960],C.GRAY),
      tRow(["3","password_reset_tokens","id (BIGINT, PK)","Menyimpan token reset password yang dikirim ke email. Token bersifat sekali pakai dan memiliki batas waktu"],[400,2000,2000,4960]),
      tRow(["4","login_attempts","id (BIGINT, PK)","Mencatat setiap percobaan login untuk keperluan keamanan — mendeteksi brute force attack"],[400,2000,2000,4960],C.GRAY),
    ]
  }),
  spacer(2),
  groupBanner("GRUP B","CV & Template",C.GREEN),
  spacer(),
  para("Grup ini mengelola template desain CV yang disediakan sistem dan CV yang dibuat oleh pelamar berdasarkan template tersebut."),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[400,2000,2000,4960],
    rows:[
      tHdr(["No","Nama Tabel","Primary Key","Fungsi Tabel"],[400,2000,2000,4960]),
      tRow(["5","cv_templates","id (BIGINT, PK)","Menyimpan master data template CV yang disediakan HR. Pelamar memilih salah satu sebagai basis pembuatan CV"],[400,2000,2000,4960]),
      tRow(["6","applicant_cvs","id (BIGINT, PK)","Menyimpan CV yang dibuat pelamar. Satu pelamar bisa punya beberapa CV, salah satunya ditandai sebagai CV utama"],[400,2000,2000,4960],C.GRAY),
    ]
  }),
  spacer(2),
  groupBanner("GRUP C","Profil Profesional Pelamar",C.PURPLE),
  spacer(),
  para("Grup ini menyimpan informasi profesional pelamar yang sifatnya berulang — seorang pelamar bisa punya lebih dari satu riwayat kerja, pendidikan, atau skill."),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[400,2000,2000,4960],
    rows:[
      tHdr(["No","Nama Tabel","Primary Key","Fungsi Tabel"],[400,2000,2000,4960]),
      tRow(["7","work_experiences","id (BIGINT, PK)","Menyimpan riwayat pengalaman kerja pelamar. Satu baris = satu posisi di satu perusahaan"],[400,2000,2000,4960]),
      tRow(["8","educations","id (BIGINT, PK)","Menyimpan riwayat pendidikan formal pelamar dari SMA hingga S3. Satu baris = satu jenjang pendidikan"],[400,2000,2000,4960],C.GRAY),
      tRow(["9","applicant_skills","id (BIGINT, PK)","Menyimpan daftar skill dan sertifikasi pelamar. Dikategorikan: technical, soft, dan language"],[400,2000,2000,4960]),
    ]
  }),
  spacer(2),
  groupBanner("GRUP D","Lowongan Pekerjaan",C.ORANGE),
  spacer(),
  para("Grup ini mengelola semua data yang berkaitan dengan lowongan pekerjaan yang dibuka oleh HR — mulai dari kategori hingga fitur simpan lowongan."),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[400,2000,2000,4960],
    rows:[
      tHdr(["No","Nama Tabel","Primary Key","Fungsi Tabel"],[400,2000,2000,4960]),
      tRow(["10","job_categories","id (BIGINT, PK)","Menyimpan master data kategori pekerjaan. Contoh: IT & Engineering, Finance & Accounting, Human Resources"],[400,2000,2000,4960]),
      tRow(["11","job_postings","id (BIGINT, PK)","Menyimpan data lengkap lowongan yang dibuka HR — judul, deskripsi, syarat, benefit, gaji, kuota, deadline, status"],[400,2000,2000,4960],C.GRAY),
      tRow(["12","saved_jobs","id (BIGINT, PK)","Menyimpan lowongan yang di-bookmark oleh pelamar. Constraint UNIQUE(user_id, job_id) mencegah duplikasi"],[400,2000,2000,4960]),
    ]
  }),
  spacer(2),
  groupBanner("GRUP E","Lamaran & Pelacakan",C.RED),
  spacer(),
  para("Grup ini adalah inti proses rekrutmen — mengelola lamaran yang masuk, pelacakan perubahan statusnya, dan log pencarian keyword oleh pelamar."),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[400,2200,2000,4760],
    rows:[
      tHdr(["No","Nama Tabel","Primary Key","Fungsi Tabel"],[400,2200,2000,4760]),
      tRow(["13","applications","id (BIGINT, PK)","Menyimpan data lamaran — menghubungkan pelamar, lowongan, dan CV. Alur status: applied → reviewed → shortlisted → interview → offered / rejected"],[400,2200,2000,4760]),
