      tRow(["15","job_search_logs","id (BIGINT, PK)","Mencatat riwayat pencarian keyword lowongan. user_id nullable karena bisa dicatat dari pengguna yang belum login (tamu)"],[400,2200,2000,4760]),
    ]
  }),
  spacer(2),
  groupBanner("GRUP F","Wawancara & Notifikasi",C.TEAL),
  spacer(),
  para("Grup ini mengelola sesi wawancara, hasil penilaiannya, dan notifikasi yang dikirimkan kepada pengguna saat terjadi perubahan di sistem."),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[400,2000,2000,4960],
    rows:[
      tHdr(["No","Nama Tabel","Primary Key","Fungsi Tabel"],[400,2000,2000,4960]),
