      tRow(["17","interview_results","id (BIGINT, PK)","Menyimpan hasil penilaian wawancara — nilai, feedback, dan rekomendasi. Relasi 1:1 dengan interviews"],[400,2000,2000,4960],C.GRAY),
      tRow(["18","notifications","id (BIGINT, PK)","Menyimpan notifikasi in-app untuk semua pengguna. Contoh: status lamaran berubah, undangan wawancara masuk"],[400,2000,2000,4960]),
    ]
