doc1children.push(
  h1("BAB 3 — RINGKASAN RELASI ANTAR TABEL"),
  para("Seluruh 18 tabel dihubungkan melalui 22 relasi foreign key sebagai berikut:"),
  spacer(1),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[600,3000,600,3000,2160],
