  code([
    "-- FULLTEXT INDEX sudah dibuat saat CREATE TABLE:",
    "FULLTEXT KEY `ft_job_search` (`title`,`description`,`requirements`,`benefits`)",
    "",
    "-- Cara penggunaannya di query pencarian:",
    "SELECT * FROM `job_postings`",
    "WHERE MATCH(title, description, requirements, benefits)",
    "      AGAINST('laravel backend developer' IN BOOLEAN MODE)",
    "  AND status = 'open';",
  ]),
  spacer(2),
  h2("5.2 UNIQUE Constraint untuk Mencegah Duplikasi"),
  para("Beberapa tabel menggunakan UNIQUE constraint untuk memastikan tidak ada data yang terduplikasi:"),
  spacer(1),
  code([
    "-- Satu pelamar tidak bisa melamar lowongan yang sama dua kali:",
    "UNIQUE KEY `applications_user_id_job_id_unique` (`user_id`, `job_id`)",
    "",
    "-- Satu pelamar tidak bisa menyimpan lowongan yang sama dua kali:",
    "UNIQUE KEY `saved_jobs_user_id_job_id_unique` (`user_id`, `job_id`)",
    "",
    "-- Satu sesi wawancara hanya bisa punya satu hasil penilaian:",
    "UNIQUE KEY `interview_results_interview_id_unique` (`interview_id`)",
    "",
    "-- Satu akun hanya bisa punya satu profil:",
    "UNIQUE KEY `user_profiles_user_id_unique` (`user_id`)",
  ]),
  spacer(2),
  h2("5.3 ON DELETE CASCADE dan SET NULL"),
  para("Foreign key dirancang dengan strategi DELETE yang tepat untuk menjaga konsistensi data:"),
