const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

const C = {
  BLUE:"1F4E79", BLUE_MID:"2E75B6", BLUE_LIGHT:"D6E4F0",
  GREEN:"1D6A4E", GREEN_LIGHT:"D6EAE0",
  ORANGE:"B45309", ORANGE_LIGHT:"FDEBD0",
  RED:"B91C1C", RED_LIGHT:"FADBD8",
  GRAY:"F5F5F5", GRAY2:"E8E8E8", BORDER:"CCCCCC"
};

const bdr={style:BorderStyle.SINGLE,size:4,color:C.BORDER};
const bdrs={top:bdr,bottom:bdr,left:bdr,right:bdr};
const noBdr={style:BorderStyle.NONE,size:0,color:"FFFFFF"};
const noBdrs={top:noBdr,bottom:noBdr,left:noBdr,right:noBdr};

const h1=t=>new Paragraph({heading:HeadingLevel.HEADING_1,spacing:{before:320,after:180},children:[new TextRun({text:t,bold:true,size:30,font:"Arial",color:C.BLUE})]});
const h2=t=>new Paragraph({heading:HeadingLevel.HEADING_2,spacing:{before:240,after:120},children:[new TextRun({text:t,bold:true,size:24,font:"Arial",color:C.BLUE_MID})]});
const h3=t=>new Paragraph({heading:HeadingLevel.HEADING_3,spacing:{before:180,after:80},children:[new TextRun({text:t,bold:true,size:22,font:"Arial",color:"333333"})]});
const para=t=>new Paragraph({spacing:{before:80,after:80},alignment:AlignmentType.JUSTIFIED,children:[new TextRun({text:t,size:22,font:"Arial",color:"333333"})]});
const spacer=(n=1)=>new Paragraph({spacing:{before:0,after:n*80},children:[new TextRun("")]});
const pb=()=>new Paragraph({children:[new PageBreak()]});
const bullet=t=>new Paragraph({numbering:{reference:"bullets",level:0},spacing:{before:50,after:50},children:[new TextRun({text:t,size:22,font:"Arial"})]});

// Data table helper - mirip format PDF contoh
function dataTable(headers, rows, widths) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},
    columnWidths:widths,
    rows:[
      new TableRow({
        tableHeader:true,
        children:headers.map((h,i)=>new TableCell({
          borders:bdrs,
          width:{size:widths[i],type:WidthType.DXA},
          shading:{fill:C.BLUE_MID,type:ShadingType.CLEAR},
          margins:{top:60,bottom:60,left:100,right:100},
          children:[new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:h,bold:true,size:18,font:"Arial",color:"FFFFFF"})]})]
        }))
      }),
      ...rows.map((row,ri)=>new TableRow({
        children:row.map((cell,ci)=>new TableCell({
          borders:bdrs,
          width:{size:widths[ci],type:WidthType.DXA},
          shading:{fill:ri%2===0?"FFFFFF":C.GRAY,type:ShadingType.CLEAR},
          margins:{top:50,bottom:50,left:100,right:100},
          children:[new Paragraph({children:[new TextRun({text:String(cell),size:17,font:"Arial",color:"333333"})]})]
        }))
      }))
    ]
  });
}

// SQL code block - dark theme seperti PDF
function sqlBlock(lines) {
  const arr = Array.isArray(lines) ? lines : lines.split('\n');
  const keywords = ['CREATE','ALTER','DROP','INSERT','UPDATE','DELETE','SELECT','FROM','WHERE',
    'JOIN','INNER','LEFT','RIGHT','ON','GROUP BY','ORDER BY','HAVING','LIMIT','AND','OR','NOT',
    'IN','EXISTS','AS','SET','VALUES','INTO','TABLE','DATABASE','PRIMARY','FOREIGN','KEY',
    'REFERENCES','UNIQUE','ENGINE','DEFAULT','NULL','AUTO_INCREMENT','CONSTRAINT','ADD',
    'MODIFY','CALL','PROCEDURE','FUNCTION','DELIMITER','BEGIN','END','RETURNS','RETURN',
    'DECLARE','IF','THEN','ELSE','COUNT','SUM','AVG','MAX','MIN','CONCAT','GROUP_CONCAT',
    'SHOW','DESCRIBE','UNION','DISTINCT','BETWEEN','LIKE'];

  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:noBdrs,
      shading:{fill:"1E2A3A",type:ShadingType.CLEAR},
      margins:{top:120,bottom:120,left:200,right:200},
      children:arr.map(line=>{
        const isComment=line.trim().startsWith('--');
        const trimmed=line.trim().toUpperCase();
        const isKw=keywords.some(k=>trimmed.startsWith(k));
        return new Paragraph({
          spacing:{before:0,after:0},
          children:[new TextRun({
            text:line,size:17,font:"Courier New",
            color:isComment?"6A9955":isKw?"569CD6":"A8D8EA"
          })]
        });
      })
    })]})]}
  ));
}

// Query result table (output dari SELECT)
function resultTable(headers, rows, widths) {
  return new Table({
    width:{size:Math.min(9360,widths.reduce((a,b)=>a+b,0)),type:WidthType.DXA},
    columnWidths:widths,
    rows:[
      new TableRow({
        tableHeader:true,
        children:headers.map((h,i)=>new TableCell({
          borders:bdrs,
          width:{size:widths[i],type:WidthType.DXA},
          shading:{fill:"264653",type:ShadingType.CLEAR},
          margins:{top:60,bottom:60,left:100,right:100},
          children:[new Paragraph({children:[new TextRun({text:h,bold:true,size:17,font:"Courier New",color:"FFFFFF"})]})]
        }))
      }),
      ...rows.map((row,ri)=>new TableRow({
        children:row.map((cell,ci)=>new TableCell({
          borders:bdrs,
          width:{size:widths[ci],type:WidthType.DXA},
          shading:{fill:ri%2===0?"EBF5FB":"FFFFFF",type:ShadingType.CLEAR},
          margins:{top:50,bottom:50,left:100,right:100},
          children:[new Paragraph({children:[new TextRun({text:String(cell),size:17,font:"Arial",color:"333333"})]})]
        }))
      }))
    ]
  });
}

function noteBox(text,bg=C.ORANGE_LIGHT,left=C.ORANGE){
  return new Paragraph({
    spacing:{before:100,after:100},
    border:{left:{style:BorderStyle.SINGLE,size:14,color:left}},
    indent:{left:360},
    children:[new TextRun({text,size:19,font:"Arial",color:"444444",italics:true})]
  });
}

const children=[];

// ==================== COVER ====================
children.push(
  spacer(2),
  new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:0,after:80},children:[new TextRun({text:"LAPORAN PROGRESS PROJECT PBL PART-2",bold:true,size:32,font:"Arial",color:C.BLUE})]}),
  new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:80,after:80},children:[new TextRun({text:"PEMROGRAMAN BASIS DATA",bold:true,size:28,font:"Arial",color:C.BLUE_MID})]}),
  spacer(3),
  new Table({
    width:{size:6000,type:WidthType.DXA},columnWidths:[2000,4000],
    rows:[
      new TableRow({children:[
        new TableCell({borders:noBdrs,margins:{top:60,bottom:60,left:0,right:100},children:[new Paragraph({children:[new TextRun({text:"NAMA ANGGOTA",size:20,font:"Arial",bold:true})]})]}),
        new TableCell({borders:noBdrs,margins:{top:60,bottom:60,left:0,right:0},children:[
          ...[
            ["4342501073","Khayra Sakilla Ramona"],
            ["4342501077","Faizal Kahfi Lubis"],
            ["4342501071","Faiz Annabil"],
            ["4342501084","Mufti"],
            ["4342501062","Rasya' Defiya Putri Salsabila"],
          ].map(([nim,name])=>new Paragraph({spacing:{before:40,after:40},children:[new TextRun({text:`${nim}  ${name}`,size:20,font:"Arial"})]}))
        ]})
      ]}),
      new TableRow({children:[
        new TableCell({borders:noBdrs,margins:{top:60,bottom:60,left:0,right:100},children:[new Paragraph({children:[new TextRun({text:"KELAS",size:20,font:"Arial",bold:true})]})]}) ,
        new TableCell({borders:noBdrs,margins:{top:60,bottom:60,left:0,right:0},children:[new Paragraph({children:[new TextRun({text:"TRPL 2C PAGI",size:20,font:"Arial"})]})]})
      ]}),
      new TableRow({children:[
        new TableCell({borders:noBdrs,margins:{top:60,bottom:60,left:0,right:100},children:[new Paragraph({children:[new TextRun({text:"KOORDINATOR",size:20,font:"Arial",bold:true})]})]}) ,
        new TableCell({borders:noBdrs,margins:{top:60,bottom:60,left:0,right:0},children:[new Paragraph({children:[new TextRun({text:"Ahmadi Irmansyah Lubis",size:20,font:"Arial"})]})]})
      ]}),
    ]
  }),
  spacer(3),
  new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:"PROGRAM STUDI TEKNOLOGI REKAYASA PERANGKAT LUNAK",bold:true,size:20,font:"Arial"})]}),
  new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:"JURUSAN TEKNIK INFORMATIKA",bold:true,size:20,font:"Arial"})]}),
  new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:"POLITEKNIK NEGERI BATAM",bold:true,size:20,font:"Arial"})]}),
  new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:"2025",bold:true,size:20,font:"Arial"})]}),
  pb()
);

// ==================== A. NORMALISASI ====================
