children.push(h1("C. ANALISIS QUERY LANJUTAN"));

// 1. Aggregate
children.push(h2("1. Aggregate Function"));

children.push(h3("a) Menghitung total lamaran yang masuk"));
children.push(para("Digunakan untuk mengetahui jumlah keseluruhan lamaran dari semua pelamar."));
children.push(spacer(1));
children.push(sqlBlock([
  "SELECT COUNT(*) AS total_lamaran",
  "FROM applications;",
]));
children.push(spacer(1));
children.push(resultTable(["total_lamaran"],[["5"]],[2000]));
children.push(spacer(2));

children.push(h3("b) Menghitung jumlah lowongan yang aktif"));
children.push(para("Digunakan untuk mengetahui berapa banyak lowongan yang saat ini berstatus open."));
children.push(spacer(1));
children.push(sqlBlock([
  "SELECT COUNT(*) AS total_lowongan_aktif",
  "FROM job_postings",
  "WHERE status = 'open';",
]));
children.push(spacer(1));
children.push(resultTable(["total_lowongan_aktif"],[["6"]],[2000]));
children.push(spacer(2));

children.push(h3("c) Menghitung rata-rata nilai wawancara"));
children.push(para("Digunakan untuk mengetahui rata-rata nilai hasil wawancara seluruh kandidat."));
children.push(spacer(1));
children.push(sqlBlock([
  "SELECT",
  "  COUNT(*) AS total_wawancara,",
  "  ROUND(AVG(score), 2) AS rata_nilai,",
  "  MAX(score) AS nilai_tertinggi,",
  "  MIN(score) AS nilai_terendah",
  "FROM interview_results;",
]));
children.push(spacer(1));
children.push(resultTable(
  ["total_wawancara","rata_nilai","nilai_tertinggi","nilai_terendah"],
  [["1","82.00","82","82"]],
  [2000,2000,2000,2000]
));
children.push(spacer(2));

children.push(h3("d) Menghitung jumlah pelamar per lowongan"));
children.push(para("Digunakan untuk mengetahui lowongan mana yang paling banyak diminati."));
children.push(spacer(1));
children.push(sqlBlock([
  "SELECT jp.title AS judul_lowongan, COUNT(a.id) AS jumlah_pelamar",
  "FROM job_postings jp",
  "LEFT JOIN applications a ON jp.id = a.job_id",
  "GROUP BY jp.id, jp.title",
  "ORDER BY jumlah_pelamar DESC;",
]));
