    'REFERENCES','UNIQUE','ENGINE','DEFAULT','NULL','AUTO_INCREMENT','CONSTRAINT','ADD',
    'MODIFY','CALL','PROCEDURE','FUNCTION','DELIMITER','BEGIN','END','RETURNS','RETURN',
    'DECLARE','IF','THEN','ELSE','COUNT','SUM','AVG','MAX','MIN','CONCAT','GROUP_CONCAT',
    'SHOW','DESCRIBE','UNION','DISTINCT','BETWEEN','LIKE'];

  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:noBdrs,
      shading:{fill:"1E2A3A",type:ShadingType.CLEAR},
      margins:{top:120,bottom:120,left:200,right:200},
