children.push(h1("B. IMPLEMENTASI SQL"));
children.push(h2("1. DDL"));
children.push(para("Berikut adalah perintah DDL (Data Definition Language) untuk membuat seluruh 18 tabel database e_recruitment. Tabel dibuat sesuai urutan dependency:"));
children.push(spacer());

children.push(h3("1) Tabel users"));
children.push(sqlBlock([
  "CREATE TABLE `users` (",
  "  `id`                bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,",
  "  `name`              varchar(100) NOT NULL,",
  "  `email`             varchar(150) NOT NULL,",
  "  `password_hash`     varchar(255) NOT NULL,",
  "  `role`              enum('hr','applicant') NOT NULL DEFAULT 'applicant',",
  "  `phone`             varchar(20) DEFAULT NULL,",
  "  `is_active`         tinyint(1) NOT NULL DEFAULT 1,",
  "  `email_verified_at` timestamp NULL DEFAULT NULL,",
  "  `remember_token`    varchar(100) DEFAULT NULL,",
  "  `created_at`        timestamp NULL DEFAULT NULL,",
  "  `updated_at`        timestamp NULL DEFAULT NULL",
  ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;",
  "",
  "ALTER TABLE `users`",
  "  ADD PRIMARY KEY (`id`),",
  "  ADD UNIQUE KEY `users_email_unique` (`email`);",
  "",
  "ALTER TABLE `users`",
  "  MODIFY `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT;",
]));
children.push(spacer());

children.push(h3("2) Tabel user_profiles"));
children.push(sqlBlock([
  "CREATE TABLE `user_profiles` (",
  "  `id`            bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,",
