// 4. Stored Procedure
children.push(h2("4. Procedural Language / PL-SQL (Stored Procedure & Function)"));

children.push(h3("a) Stored Procedure tambah lamaran"));
children.push(para("Stored procedure untuk menambah lamaran baru sekaligus mencatat log status awal secara otomatis."));
children.push(spacer(1));
children.push(sqlBlock([
  "DELIMITER //",
  "",
  "CREATE PROCEDURE tambah_lamaran(",
  "  IN p_user_id    BIGINT,",
  "  IN p_job_id     BIGINT,",
  "  IN p_cv_id      BIGINT,",
  "  IN p_cover      TEXT",
  ")",
  "BEGIN",
  "  DECLARE v_app_id BIGINT;",
  "",
  "  -- Insert lamaran baru",
  "  INSERT INTO applications(user_id, job_id, cv_id, cover_letter, status)",
  "  VALUES(p_user_id, p_job_id, p_cv_id, p_cover, 'applied');",
  "",
  "  SET v_app_id = LAST_INSERT_ID();",
  "",
  "  -- Catat log status awal secara otomatis",
  "  INSERT INTO application_status_logs",
  "    (application_id, changed_by, old_status, new_status, reason)",
  "  VALUES(v_app_id, p_user_id, 'applied', 'applied', 'Lamaran baru dikirim');",
  "END //",
  "",
  "DELIMITER ;",
  "",
  "-- Cara memanggil procedure:",
  "CALL tambah_lamaran(3, 2, 1, 'Saya tertarik dengan posisi ini.');",
]));
children.push(spacer());
children.push(resultTable(
  ["application_id","user_id","job_id","status"],
  [["6","3","2","applied"]],
  [2500,2000,2000,2860]
));
children.push(spacer(2));

children.push(h3("b) Stored Procedure ubah status lamaran"));
children.push(para("Stored procedure untuk mengubah status lamaran sekaligus mencatat log perubahan secara otomatis."));
children.push(spacer(1));
children.push(sqlBlock([
  "DELIMITER //",
  "",
  "CREATE PROCEDURE ubah_status_lamaran(",
  "  IN p_application_id BIGINT,",
  "  IN p_changed_by     BIGINT,",
  "  IN p_new_status     VARCHAR(20),",
  "  IN p_reason         TEXT",
  ")",
  "BEGIN",
  "  DECLARE v_old_status VARCHAR(20);",
  "",
  "  -- Ambil status lama",
  "  SELECT status INTO v_old_status",
  "  FROM applications WHERE id = p_application_id;",
  "",
  "  -- Update status",
  "  UPDATE applications",
  "  SET status = p_new_status, updated_at = NOW()",
  "  WHERE id = p_application_id;",
  "",
  "  -- Catat log perubahan",
  "  INSERT INTO application_status_logs",
  "    (application_id, changed_by, old_status, new_status, reason)",
  "  VALUES(p_application_id, p_changed_by, v_old_status, p_new_status, p_reason);",
