      codeBlock(["DELIMITER //","CREATE PROCEDURE AddDosen(","    IN kode_dos VARCHAR(10),","    IN nama_dose VARCHAR(50),","    IN alamat_dos VARCHAR(100))","BEGIN","    INSERT INTO dosen VALUES (kode_dos, nama_dose, alamat_dos);","END//","","DELIMITER ;"]),
