      codeBlock(["DELIMITER //","CREATE PROCEDURE JumlahDosen (","    OUT jumlah_dosen INT(3))","BEGIN","    SELECT COUNT(kode_dos) INTO jumlah_dosen FROM dosen;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil dan membaca nilai output:"),
      codeBlock(["CALL JumlahDosen(@jumlah_dosen);","","SELECT @jumlah_dosen;"]),
      normalText("Hasil: @jumlah_dosen = 6 (setelah penambahan data Gunawan)."),

      gap(), gap(),

