      sectionBox("7. Parameter INOUT – CountBySks()"),
      gap(), normalText("Parameter INOUT adalah kombinasi IN dan OUT. Nilai dikirim masuk ke procedure dan nilai hasil dikembalikan melalui parameter yang sama."),
      gap(), labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE CountBySks(","    INOUT var INT(3)","  )","BEGIN","    SELECT COUNT(kd_mk)","    INTO var","    FROM matakuliah","    WHERE sks=var;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil untuk matakuliah dengan SKS = 2:"),
      codeBlock(["SET @sks=2;","","CALL CountBySks(@sks);","","SELECT @sks;"]),
      normalText("Hasil: Nilai @sks berubah menjadi jumlah matakuliah ber-SKS 2 (PTI777 dan TIK123 = 2 matakuliah)."),

      gap(), gap(),

      // 8
      sectionBox("8. Kombinasi Parameter IN & OUT – CountByGender()"),
      gap(), normalText("Pendekatan INOUT dapat direpresentasikan dengan memisah parameter IN dan OUT. Contoh: hitung mahasiswa berdasarkan jenis kelamin."),
      gap(), labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE CountByGender(","    IN gender VARCHAR(3),","    OUT total INT(3))","BEGIN","    SELECT COUNT(nim) INTO total FROM mahasiswa","    WHERE jk=gender;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil untuk jenis kelamin 'L':"),
      codeBlock(["CALL CountByGender ('L',@total);","","SELECT @total;"]),
      normalText("Hasil: @total = 4 (Arif, Budi, Tono, Iwan)."),

      gap(), gap(),

      // 9
      sectionBox("9. Percabangan IF – DemoIF()"),
      gap(), normalText("Stored procedure dengan pernyataan kondisional IF/ELSE untuk menentukan apakah suatu bilangan positif atau negatif."),
      gap(), labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE DemoIF(","    IN bil INT(3)",")","BEGIN","    DECLARE str VARCHAR(50);","    IF(bil<0) THEN","        SET str = 'BILANGAN NEGATIF';","    ELSE","        SET str = 'BILANGAN POSITIF';","    END IF;","","    SELECT str;","END//","","DELIMITER ;"]),
      labelBlock("▶ Memanggil dengan nilai 7 (positif):"),
      codeBlock(["CALL DemoIF(7);"]),
      normalText("Hasil: str = 'BILANGAN POSITIF'"),
      labelBlock("▶ Memanggil dengan nilai -3 (negatif):"),
      codeBlock(["CALL DemoIF(-3);"]),
      normalText("Hasil: str = 'BILANGAN NEGATIF'"),

      gap(), gap(),

      // 10
      sectionBox("10. Pengulangan WHILE – DemoLOOP()"),
      gap(), normalText("Stored procedure dengan perulangan WHILE untuk menggabungkan angka 1 hingga N menjadi satu string."),
      gap(), labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE DemoLOOP(","    IN bil INT(3)",")","BEGIN","    DECLARE str VARCHAR(50);","    DECLARE i INT(3);","    SET i=1;","    SET str='';","    WHILE i <= bil DO","        SET str=CONCAT(str,i,',');","        set i=i+1;","    END WHILE;","","    SELECT str;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil dengan nilai 9:"),
      codeBlock(["CALL DemoLOOP(9);"]),
      normalText("Hasil: str = '1,2,3,4,5,6,7,8,9,' (angka 1 sampai 9 digabung dengan pemisah koma)."),

      gap(),
      new Paragraph({ children: [new TextRun({ text: "--- Selesai ---", size: 20, color: "888888", italics: true })], alignment: AlignmentType.CENTER, spacing: { before: 300 } }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => { fs.writeFileSync('/home/claude/Jawaban_P5_Part1_StoredProcedure.docx', buf); console.log('Part1 Done!'); });

