const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType, LevelFormat
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "AAAAAA" };
const borders = { top: border, bottom: border, left: border, right: border };
const headerBorder = { style: BorderStyle.SINGLE, size: 1, color: "2E74B5" };
const headerBorders = { top: headerBorder, bottom: headerBorder, left: headerBorder, right: headerBorder };

function normalText(text) {
  return new Paragraph({ children: [new TextRun({ text, size: 22 })], spacing: { before: 60, after: 60 } });
}
function labelBlock(label) {
  return new Paragraph({ children: [new TextRun({ text: label, size: 20, color: "595959", italics: true })], spacing: { before: 140, after: 40 } });
}
function codeBlock(lines) {
  return new Table({
    width: { size: 9026, type: WidthType.DXA }, columnWidths: [9026],
    rows: lines.map(line => new TableRow({ children: [new TableCell({
      borders, width: { size: 9026, type: WidthType.DXA },
      shading: { fill: "1E1E2E", type: ShadingType.CLEAR },
      margins: { top: 60, bottom: 60, left: 160, right: 160 },
      children: [new Paragraph({ children: [new TextRun({ text: line, font: "Courier New", size: 19, color: "A8FF78" })], spacing: { before: 20, after: 20 } })]
    })] })),
    margins: { top: 120, bottom: 120 }
  });
}
function sectionBox(title) {
  return new Table({
    width: { size: 9026, type: WidthType.DXA }, columnWidths: [9026],
    rows: [new TableRow({ children: [new TableCell({
      borders: headerBorders, width: { size: 9026, type: WidthType.DXA },
      shading: { fill: "1F3864", type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 160, right: 160 },
      children: [new Paragraph({ children: [new TextRun({ text: title, bold: true, size: 24, color: "FFFFFF" })] })]
    })] })]
  });
}
function gap() { return new Paragraph({ children: [new TextRun("")], spacing: { before: 100, after: 80 } }); }
function divider() {
  return new Paragraph({ children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 3, color: "CCCCCC", space: 1 } },
    spacing: { before: 160, after: 160 } });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Arial", color: "1F3864" },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Arial", color: "2E74B5" },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 1 } },
    ]
  },
  sections: [{ properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1440, right: 1260, bottom: 1440, left: 1260 } } },
    children: [
      // Cover
      new Paragraph({ children: [new TextRun("")], spacing: { before: 600 } }),
      new Paragraph({ children: [new TextRun({ text: "LAPORAN UJI COBA PRAKTIKUM", bold: true, size: 40, color: "1F3864" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 120 } }),
      new Paragraph({ children: [new TextRun({ text: "Modul 5 – Part 2", bold: true, size: 30, color: "2E74B5" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: "Trigger", bold: true, size: 26, color: "2E74B5" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: "Basis Data | Politeknik Negeri Batam", size: 22, color: "595959" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 600 } }),

      divider(),
      normalText("Praktikum ini menggunakan dua tabel: barang (id_brg, nama_brg, stok) dan pembelian (id_pem, id_brg, jml_beli)."),
      gap(),

      // 1
      sectionBox("1. Trigger BEFORE INSERT – inkremenStok2"),
      gap(), normalText("Trigger dieksekusi SEBELUM data baru dimasukkan ke tabel barang. Setiap INSERT otomatis menambah nilai stok sebesar +1."),
      gap(), labelBlock("▶ Membuat Trigger:"),
      codeBlock(["CREATE TRIGGER inkremenStok2","BEFORE INSERT ON barang","FOR EACH ROW","BEGIN","    SET NEW.stok = NEW.stok + 1;","END;"]),
      labelBlock("▶ Uji coba – INSERT data barang baru:"),
      codeBlock(["INSERT INTO barang VALUES('A13', 'Modem', 5);"]),
      labelBlock("▶ Cek hasil:"),
      codeBlock(["SELECT * FROM barang;"]),
      normalText("Hasil: Modem diinsert dengan stok=5, namun trigger mengubahnya menjadi stok=6 secara otomatis."),
      gap(), labelBlock("▶ Melihat daftar trigger:"),
      codeBlock(["SHOW TRIGGERS;"]),
      labelBlock("▶ Menghapus trigger:"),
      codeBlock(["DROP TRIGGER inkremenStok2;"]),

      gap(), gap(),

      // 2
      sectionBox("2. Keyword NEW – Trigger AFTER INSERT – updateStok"),
      gap(), normalText("Trigger AFTER INSERT pada tabel pembelian. Saat data pembelian ditambahkan, stok barang otomatis dikurangi sesuai jml_beli. Keyword NEW digunakan untuk mengakses nilai yang baru diinsert."),
      gap(), labelBlock("▶ Membuat Trigger:"),
      codeBlock(["CREATE TRIGGER updateStok","AFTER INSERT ON pembelian","FOR EACH ROW","BEGIN","    UPDATE barang","    SET stok = stok - NEW.jml_beli","    WHERE id_brg = NEW.id_brg;","END;"]),
      labelBlock("▶ Cek kondisi awal tabel barang:"),
      codeBlock(["SELECT * FROM barang;"]),
      labelBlock("▶ Insert data pembelian:"),
      codeBlock(["INSERT INTO `pembelian` (`id_pembelian`, `id_brg`, `jml_beli`)","VALUES ('2', 'A10', '10');"]),
      labelBlock("▶ Cek kembali tabel barang:"),
      codeBlock(["SELECT * FROM barang;"]),
      normalText("Hasil: Stok barang A10 (Mouse) berkurang sebesar 10 secara otomatis setelah INSERT pembelian."),

      gap(), gap(),

      // 3
      sectionBox("3. Keyword OLD – Trigger AFTER DELETE – deleteChild"),
      gap(), normalText("Untuk trigger DELETE, hanya keyword OLD yang tersedia (tidak ada data baru). Trigger ini menghapus semua data pembelian terkait saat data barang dihapus (cascade delete manual)."),
      gap(), labelBlock("▶ Membuat Trigger:"),
      codeBlock(["CREATE TRIGGER deleteChild","AFTER DELETE ON barang","FOR EACH ROW","BEGIN","    -- Hapus data pembelian yang berkorespondensi","    DELETE FROM pembelian","    WHERE id_brg = OLD.id_brg;","END;"]),
      labelBlock("▶ Hapus data barang A10:"),
      codeBlock(["DELETE FROM barang WHERE id_brg = 'A10';"]),
      labelBlock("▶ Cek tabel pembelian setelah delete:"),
      codeBlock(["SELECT * FROM `pembelian`;"]),
      normalText("Hasil: Semua data pembelian dengan id_brg='A10' ikut terhapus otomatis (MySQL returned empty result set)."),

      gap(), gap(),

      // 4
      sectionBox("4. Keyword NEW & OLD – Trigger AFTER UPDATE – updateStokEdit"),
      gap(), normalText("Untuk UPDATE, kedua keyword NEW dan OLD dapat digunakan. OLD = nilai sebelum update, NEW = nilai sesudah update. Selisihnya digunakan untuk menyesuaikan stok barang."),
      gap(), labelBlock("▶ Membuat Trigger:"),
      codeBlock(["CREATE TRIGGER updateStokEdit","AFTER UPDATE ON pembelian","FOR EACH ROW","BEGIN","    -- Update nilai stok barang berdasarkan selisih","    UPDATE barang","    SET stok = stok + (NEW.jml_beli - OLD.jml_beli)","    WHERE id_brg = NEW.id_brg;","END;"]),
      labelBlock("▶ Update data pembelian:"),
      codeBlock(["UPDATE pembelian SET jml_beli= 20 WHERE id_pembelian=3;"]),
      labelBlock("▶ Tampilkan data tabel barang:"),
      codeBlock(["SELECT * FROM `barang`;"]),
      normalText("Hasil: Stok barang diperbarui sesuai selisih antara jml_beli baru dan lama, sehingga data selalu akurat."),

      gap(), gap(),

      // 5
      sectionBox("5. Trigger Kompleks – auditBarang (BEFORE INSERT dengan IF)"),
      gap(), normalText("Trigger kompleks dapat mengandung percabangan IF, pengulangan, dan fungsi agregat. Skenario: jika id_brg sudah ada, simpan status ke variabel; jika belum ada, data dimasukkan normal."),
      gap(), labelBlock("▶ Membuat Trigger Kompleks:"),
