const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType, LevelFormat
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "AAAAAA" };
const borders = { top: border, bottom: border, left: border, right: border };
const headerBorder = { style: BorderStyle.SINGLE, size: 1, color: "2E74B5" };
const headerBorders = { top: headerBorder, bottom: headerBorder, left: headerBorder, right: headerBorder };

function heading1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, bold: true, size: 30, color: "1F3864" })],
    spacing: { before: 320, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "2E74B5", space: 1 } }
  });
}

function heading2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, bold: true, size: 26, color: "2E74B5" })],
    spacing: { before: 240, after: 120 }
  });
}

function normalText(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22 })],
    spacing: { before: 60, after: 60 }
  });
}

function codeBlock(lines) {
  const rows = lines.map(line =>
    new TableRow({
      children: [new TableCell({
        borders,
        width: { size: 9026, type: WidthType.DXA },
        shading: { fill: "1E1E2E", type: ShadingType.CLEAR },
        margins: { top: 60, bottom: 60, left: 160, right: 160 },
        children: [new Paragraph({
          children: [new TextRun({ text: line, font: "Courier New", size: 19, color: "A8FF78" })],
          spacing: { before: 20, after: 20 }
        })]
      })]
    })
  );
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [9026],
    rows
  });
}

function labelBlock(label) {
  return new Paragraph({
    children: [new TextRun({ text: label, size: 20, color: "595959", italics: true })],
    spacing: { before: 140, after: 40 }
  });
}

function sectionBox(title) {
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [9026],
    rows: [new TableRow({
      children: [new TableCell({
        borders: headerBorders,
        width: { size: 9026, type: WidthType.DXA },
        shading: { fill: "1F3864", type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 160, right: 160 },
        children: [new Paragraph({
          children: [new TextRun({ text: title, bold: true, size: 24, color: "FFFFFF" })],
        })]
      })]
    })]
  });
}

function spacer() {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 120, after: 80 } });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Arial", color: "1F3864" },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Arial", color: "2E74B5" },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 1 } },
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 11906, height: 16838 },
        margin: { top: 1440, right: 1260, bottom: 1440, left: 1260 }
      }
    },
    children: [
      // Cover
      new Paragraph({ children: [new TextRun("")], spacing: { before: 600, after: 0 } }),
      new Paragraph({
        children: [new TextRun({ text: "LAPORAN UJI COBA PRAKTIKUM", bold: true, size: 40, color: "1F3864" })],
        alignment: AlignmentType.CENTER, spacing: { before: 0, after: 120 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Modul 5 – Part 1", bold: true, size: 32, color: "2E74B5" })],
        alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Stored Procedure & Function", bold: true, size: 26, color: "2E74B5" })],
        alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Basis Data | Politeknik Negeri Batam", size: 22, color: "595959" })],
        alignment: AlignmentType.CENTER, spacing: { before: 0, after: 600 }
      }),

      heading1("STORED PROCEDURE & FUNCTION"),
      normalText("Database yang digunakan: db_p4_subquery (tabel: mahasiswa, matakuliah, dosen, jurusan)."),
      new Paragraph({ children: [new TextRun("")], spacing: { before: 80, after: 80 } }),

      // 1
      sectionBox("1. Stored Procedure Tanpa Parameter – getMhs()"),
      new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } }),
      normalText("Menampilkan semua data mahasiswa tanpa parameter."),
      labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE getMhs()","BEGIN","    SELECT * FROM mahasiswa;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil:"),
      codeBlock(["CALL getMhs();"]),
      normalText("Hasil: Menampilkan seluruh 7 baris data mahasiswa (nim, nama, jk, alamat)."),
      spacer(),

      // 2
      sectionBox("2. Parameter IN (1 param) – getMkBySemester(smt)"),
      new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } }),
      normalText("Menampilkan matakuliah berdasarkan semester tertentu menggunakan parameter IN."),
      labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE getMkBySemester(IN smt INT(2))","BEGIN","    SELECT * FROM matakuliah","    WHERE semester = smt;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil untuk semester 3:"),
      codeBlock(["CALL getMkBySemester(3);"]),
      normalText("Hasil: Menampilkan PTI447, PTI777, TIK342 (matakuliah di semester 3)."),
      spacer(),

      // 3
      sectionBox("3. Parameter IN (2 param) – getMkBySemSks(Smt, Sks)"),
      new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } }),
      normalText("Menampilkan matakuliah berdasarkan semester DAN jumlah SKS."),
      labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE getMkBySemSks(","    IN Smt INT(2),","    IN Sks INT(2))","BEGIN","    SELECT * FROM matakuliah","    WHERE semester = Smt","    AND sks = Sks;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil semester=3, SKS=2:"),
      codeBlock(["CALL getMkBySemSks(3,2);"]),
      normalText("Hasil: Menampilkan PTI777 (Sistem Informasi, semester 3, SKS 2)."),
      spacer(),

      // 4 Variabel
      sectionBox("4. Penggunaan Variabel Session (@smt)"),
      new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } }),
      normalText("Variabel global session dideklarasikan dengan SET dan notasi @, lalu digunakan sebagai argumen stored procedure."),
      labelBlock("▶ Deklarasi variabel dan penggunaan:"),
      codeBlock(["SET @smt = 3;","","SELECT @smt;","","CALL getMkBySemester(@smt);"]),
      normalText("Hasil: @smt = 3, kemudian dipakai sebagai argumen getMkBySemester, menampilkan matakuliah semester 3."),
      spacer(),

      // 5
      sectionBox("5. Penambahan Data – AddDosen()"),
      new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } }),
      normalText("Stored procedure dengan parameter IN untuk INSERT data baru ke tabel dosen."),
      labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE AddDosen(","    IN kode_dos VARCHAR(10),","    IN nama_dose VARCHAR(50),","    IN alamat_dos VARCHAR(100))","BEGIN","    INSERT INTO dosen VALUES (kode_dos, nama_dose, alamat_dos);","END//","","DELIMITER ;"]),
      labelBlock("▶ Memanggil:"),
      codeBlock(["CALL AddDosen('212','Gunawan','Jl. Ambarawa');"]),
      labelBlock("▶ Verifikasi:"),
      codeBlock(["SELECT * FROM dosen;"]),
      normalText("Hasil: Dosen baru (212, Gunawan, Jl. Ambarawa) berhasil ditambahkan."),
      spacer(),

      // 6
      sectionBox("6. Parameter OUT – JumlahDosen()"),
      new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } }),
      normalText("Parameter OUT memungkinkan stored procedure mengembalikan nilai ke pemanggil (analog passing-by-reference)."),
      labelBlock("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE JumlahDosen (","    OUT jumlah_dosen INT(3))","BEGIN","    SELECT COUNT(kode_dos) INTO jumlah_dosen FROM dosen;","END //","","DELIMITER ;"]),
      labelBlock("▶ Memanggil dan membaca output:"),
