      sectionBox("9. Percabangan IF – DemoIF()"),
      sp(60,60), normalText("Pernyataan kondisional IF/ELSE di dalam stored procedure."),
      label("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE DemoIF(","    IN bil INT(3)",")","BEGIN","    DECLARE str VARCHAR(50);","    IF(bil<0) THEN","        SET str = 'BILANGAN NEGATIF';","    ELSE","        SET str = 'BILANGAN POSITIF';","    END IF;","","    SELECT str;","END//","","DELIMITER ;"]),
      label("▶ Memanggil dengan nilai positif (7):"), codeBlock(["CALL DemoIF(7);"]),
      normalText("Hasil: str = 'BILANGAN POSITIF'"),
      label("▶ Memanggil dengan nilai negatif (-3):"), codeBlock(["CALL DemoIF(-3);"]),
      normalText("Hasil: str = 'BILANGAN NEGATIF'"), sp(),

      // 10
      sectionBox("10. Pengulangan WHILE – DemoLOOP()"),
      sp(60,60), normalText("Perulangan WHILE di dalam stored procedure untuk merangkai angka menjadi string."),
      label("▶ Membuat Stored Procedure:"),
      codeBlock(["DELIMITER //","CREATE PROCEDURE DemoLOOP(","    IN bil INT(3)",")","BEGIN","    DECLARE str VARCHAR(50);","    DECLARE i INT(3);","    SET i=1;","    SET str='';","    WHILE i <= bil DO","        SET str=CONCAT(str,i,',');","        set i=i+1;","    END WHILE;","","    SELECT str;","END //","","DELIMITER ;"]),
      label("▶ Memanggil dengan nilai 9:"), codeBlock(["CALL DemoLOOP(9);"]),
      normalText("Hasil: str = '1,2,3,4,5,6,7,8,9,'"),

      sp(400,0),
      new Paragraph({ children: [new TextRun({ text: "--- Selesai Part 1 ---", size: 20, color: "888888", italics: true })], alignment: AlignmentType.CENTER }),
    ]
  }]
});

Packer.toBuffer(doc).then(b => { fs.writeFileSync('/home/claude/Jawaban_P5_Part1_StoredProcedure.docx', b); console.log('done'); });

