const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "AAAAAA" };
const borders = { top: border, bottom: border, left: border, right: border };
const hBorder = { style: BorderStyle.SINGLE, size: 1, color: "C55A11" };
const hBorders = { top: hBorder, bottom: hBorder, left: hBorder, right: hBorder };

function normalText(text) {
  return new Paragraph({ children: [new TextRun({ text, size: 22 })], spacing: { before: 60, after: 60 } });
}

function codeBlock(lines) {
  return new Table({
    width: { size: 9026, type: WidthType.DXA }, columnWidths: [9026],
    rows: lines.map(line => new TableRow({ children: [new TableCell({
      borders, width: { size: 9026, type: WidthType.DXA },
      shading: { fill: "1E1E2E", type: ShadingType.CLEAR },
      margins: { top: 50, bottom: 50, left: 160, right: 160 },
      children: [new Paragraph({ children: [new TextRun({ text: line, font: "Courier New", size: 19, color: "FFD580" })], spacing: { before: 10, after: 10 } })]
    })] }))
  });
}

function label(text) {
  return new Paragraph({ children: [new TextRun({ text, size: 20, color: "595959", italics: true })], spacing: { before: 120, after: 30 } });
}

function sectionBox(title) {
  return new Table({
    width: { size: 9026, type: WidthType.DXA }, columnWidths: [9026],
    rows: [new TableRow({ children: [new TableCell({
      borders: hBorders, width: { size: 9026, type: WidthType.DXA },
      shading: { fill: "833C00", type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 160, right: 160 },
      children: [new Paragraph({ children: [new TextRun({ text: title, bold: true, size: 24, color: "FFFFFF" })] })]
    })] })]
  });
}

const sp = (b=100,a=80) => new Paragraph({ children: [new TextRun("")], spacing: { before: b, after: a } });

// Summary table
function summaryTable() {
  const headerRow = new TableRow({ children: ["Operasi","Keyword","Waktu","Keterangan"].map((t,i) => new TableCell({
    borders: hBorders, width: { size: [2000,2000,2000,3026][i], type: WidthType.DXA },
    shading: { fill: "833C00", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({ children: [new TextRun({ text: t, bold: true, size: 20, color: "FFFFFF" })] })]
  })) });
  const data = [
    ["INSERT","NEW saja","BEFORE / AFTER","Tidak ada data lama"],
    ["DELETE","OLD saja","BEFORE / AFTER","Tidak ada data baru"],
    ["UPDATE","NEW & OLD","BEFORE / AFTER","Akses nilai sebelum & sesudah"],
  ];
  return new Table({
    width: { size: 9026, type: WidthType.DXA }, columnWidths: [2000,2000,2000,3026],
    rows: [headerRow, ...data.map((row,i) => new TableRow({ children: row.map((cell,j) => new TableCell({
      borders, width: { size: [2000,2000,2000,3026][j], type: WidthType.DXA },
      shading: { fill: i % 2 === 0 ? "FBE5D6" : "FFFFFF", type: ShadingType.CLEAR },
      margins: { top: 60, bottom: 60, left: 120, right: 120 },
      children: [new Paragraph({ children: [new TextRun({ text: cell, size: 20 })] })]
    })) }))]
  });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Arial", color: "833C00" },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Arial", color: "C55A11" },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 1 } },
    ]
  },
  sections: [{ properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1440, right: 1260, bottom: 1440, left: 1260 } } },
    children: [
      sp(600,0),
      new Paragraph({ children: [new TextRun({ text: "LAPORAN UJI COBA PRAKTIKUM", bold: true, size: 40, color: "833C00" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 100 } }),
      new Paragraph({ children: [new TextRun({ text: "Modul 5 – Part 2", bold: true, size: 32, color: "C55A11" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: "Trigger", bold: true, size: 26, color: "C55A11" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: "Basis Data | Politeknik Negeri Batam", size: 22, color: "595959" })], alignment: AlignmentType.CENTER, spacing: { before: 0, after: 600 } }),

      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: "TRIGGER", bold: true, size: 30, color: "833C00" })], spacing: { before: 320, after: 160 }, border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "C55A11", space: 1 } } }),
      normalText("Tabel yang digunakan: barang (id_brg, nama_brg, stok) dan pembelian (id_pem, id_brg, jml_beli)."),
      sp(),

      // 1
      sectionBox("1. Trigger BEFORE INSERT – inkremenStok2"),
      sp(60,60), normalText("Dieksekusi SEBELUM INSERT ke tabel barang. Menginkremen nilai stok otomatis sebesar +1."),
      label("▶ Membuat Trigger:"),
      codeBlock(["CREATE TRIGGER inkremenStok2","BEFORE INSERT ON barang","FOR EACH ROW","BEGIN","    SET NEW.stok = NEW.stok + 1;","END;"]),
      label("▶ Uji dengan INSERT data barang baru:"), codeBlock(["INSERT INTO barang VALUES('A13', 'Modem', 5);"]),
      label("▶ Cek hasil:"), codeBlock(["SELECT * FROM barang;"]),
      normalText("Hasil: Modem diinsert dengan stok=5, otomatis menjadi stok=6 (trigger +1 sebelum insert)."),
      label("▶ Melihat daftar trigger:"), codeBlock(["SHOW TRIGGERS;"]),
      label("▶ Menghapus trigger:"), codeBlock(["DROP TRIGGER inkremenStok2;"]),
      sp(),

      // 2
      sectionBox("2. Keyword NEW – Trigger AFTER INSERT – updateStok"),
      sp(60,60), normalText("AFTER INSERT pada tabel pembelian: otomatis mengurangi stok barang sesuai jumlah beli. Keyword NEW mengakses nilai yang baru dimasukkan."),
      label("▶ Membuat Trigger:"),
      codeBlock(["CREATE TRIGGER updateStok","AFTER INSERT ON pembelian","FOR EACH ROW","BEGIN","    UPDATE barang","    SET stok = stok - NEW.jml_beli","    WHERE id_brg = NEW.id_brg;","END;"]),
      label("▶ Cek kondisi awal tabel barang:"), codeBlock(["SELECT * FROM barang;"]),
      label("▶ Insert data pembelian:"),
      codeBlock(["INSERT INTO `pembelian` (`id_pembelian`, `id_brg`, `jml_beli`)","VALUES ('2', 'A10', '10');"]),
      label("▶ Cek tabel barang setelah insert:"), codeBlock(["SELECT * FROM barang;"]),
      normalText("Hasil: Stok barang A10 (Mouse) berkurang 10 secara otomatis setelah pembelian dimasukkan."),
      sp(),

      // 3
      sectionBox("3. Keyword OLD – Trigger AFTER DELETE – deleteChild"),
      sp(60,60), normalText("Untuk DELETE, keyword yang tersedia hanya OLD. Trigger ini cascade-delete: menghapus semua data pembelian terkait saat data barang dihapus."),
      label("▶ Membuat Trigger:"),
      codeBlock(["CREATE TRIGGER deleteChild","AFTER DELETE ON barang","FOR EACH ROW","BEGIN","    -- Hapus data pembelian yang berkorespondensi","    DELETE FROM pembelian","    WHERE id_brg = OLD.id_brg;","END;"]),
      label("▶ Hapus data barang A10:"), codeBlock(["DELETE FROM barang WHERE id_brg = 'A10';"]),
