const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, Header, Footer, TabStopType, TabStopPosition,
  UnderlineType
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "AAAAAA" };
const borders = { top: border, bottom: border, left: border, right: border };

function heading(text, level = HeadingLevel.HEADING_1) {
  return new Paragraph({
    heading: level,
    spacing: { before: 240, after: 120 },
    children: [new TextRun({ text, bold: true, size: level === HeadingLevel.HEADING_1 ? 28 : 24, font: "Times New Roman" })]
  });
}

function para(text, opts = {}) {
  return new Paragraph({
    alignment: opts.align || AlignmentType.JUSTIFIED,
    spacing: { before: 60, after: 60 },
    indent: opts.indent ? { left: 720 } : {},
    children: [new TextRun({ text, size: 24, font: "Times New Roman", ...opts.run })]
  });
}

function code(text) {
  return new Paragraph({
    spacing: { before: 40, after: 40 },
    indent: { left: 720 },
    children: [new TextRun({ text, size: 20, font: "Courier New", color: "1F497D" })]
  });
}

function divider() {
  return new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "2E75B6", space: 1 } },
    spacing: { before: 160, after: 160 },
    children: []
  });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Times New Roman", size: 24 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Times New Roman", color: "1F3864" },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Times New Roman", color: "2E75B6" },
        paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 1 }
      },
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 11906, height: 16838 },
        margin: { top: 1440, right: 1080, bottom: 1440, left: 1800 }
      }
    },
    children: [
      // HEADER BOX - Identity
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 60 },
        children: [new TextRun({ text: "TUGAS PEMROGRAMAN BERORIENTASI OBJEK", bold: true, size: 28, font: "Times New Roman", color: "1F3864" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 40 },
        children: [new TextRun({ text: "Interface dan Class Abstrak dalam PHP", size: 24, font: "Times New Roman", color: "2E75B6", italics: true })]
      }),
      new Paragraph({
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "1F3864", space: 1 } },
        spacing: { before: 80, after: 200 },
        children: []
      }),

      // Identity Table
      new Table({
        width: { size: 9026, type: WidthType.DXA },
        columnWidths: [2500, 200, 6326],
        rows: [
          new TableRow({ children: [
            new TableCell({ borders, width: { size: 2500, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "Nama", bold: true, size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 200, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: ":", size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 6326, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "Faizal Kahfi Lubis", size: 24, font: "Times New Roman" })] })] }),
          ]}),
          new TableRow({ children: [
            new TableCell({ borders, width: { size: 2500, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "NIM", bold: true, size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 200, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: ":", size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 6326, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "4342501077", size: 24, font: "Times New Roman" })] })] }),
          ]}),
          new TableRow({ children: [
            new TableCell({ borders, width: { size: 2500, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "Kelas", bold: true, size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 200, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: ":", size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 6326, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "TRPL 2C Pagi", size: 24, font: "Times New Roman" })] })] }),
          ]}),
          new TableRow({ children: [
            new TableCell({ borders, width: { size: 2500, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "Mata Kuliah", bold: true, size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 200, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: ":", size: 24, font: "Times New Roman" })] })] }),
            new TableCell({ borders, width: { size: 6326, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 120, right: 120 }, children: [new Paragraph({ children: [new TextRun({ text: "Pemrograman Berorientasi Objek", size: 24, font: "Times New Roman" })] })] }),
          ]}),
        ]
      }),

      new Paragraph({ spacing: { before: 240, after: 0 }, children: [] }),

      // ===================== SOAL 1 =====================
      new Paragraph({
        heading: HeadingLevel.HEADING_1,
        spacing: { before: 200, after: 120 },
        children: [new TextRun({ text: "1. Perbedaan Utama antara Interface dan Class Abstrak dalam PHP", bold: true, size: 28, font: "Times New Roman" })]
      }),

      para("Dalam pemrograman berorientasi objek (OOP) PHP, interface dan class abstrak adalah dua konsep yang sering dibandingkan. Keduanya digunakan untuk mendefinisikan kontrak atau blueprint bagi class lain, namun memiliki perbedaan mendasar."),

      new Paragraph({ spacing: { before: 120, after: 60 }, children: [new TextRun({ text: "a. Interface", bold: true, size: 24, font: "Times New Roman" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Hanya berisi deklarasi method tanpa implementasi (body method kosong).", size: 24, font: "Times New Roman" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Semua method dalam interface bersifat public secara default.", size: 24, font: "Times New Roman" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Sebuah class dapat mengimplementasikan lebih dari satu interface (multiple interface implementation).", size: 24, font: "Times New Roman" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Interface tidak dapat memiliki properti (hanya konstanta yang diperbolehkan).", size: 24, font: "Times New Roman" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Didefinisikan menggunakan keyword interface.", size: 24, font: "Times New Roman" })] }),

      new Paragraph({ spacing: { before: 120, after: 60 }, children: [new TextRun({ text: "b. Class Abstrak (Abstract Class)", bold: true, size: 24, font: "Times New Roman" })] }),
