/**
 * Login Page - Auth JS
 * Handles: toggle password visibility, form validation, AJAX login
 */

document.addEventListener('DOMContentLoaded', function () {

    // === Toggle Password Visibility ===
    const toggleBtn = document.getElementById('toggle-password');
    const passwordInput = document.getElementById('password');
    const eyeIcon = document.getElementById('eye-icon');
    const eyeOffIcon = document.getElementById('eye-off-icon');

    if (toggleBtn) {
        toggleBtn.addEventListener('click', function () {
            const isPassword = passwordInput.type === 'password';
            passwordInput.type = isPassword ? 'text' : 'password';
            eyeIcon.classList.toggle('hidden');
            eyeOffIcon.classList.toggle('hidden');
        });
    }

    // === Form Validation ===
    const btnLogin = document.getElementById('btn-login');
    const emailInput = document.getElementById('email');
    const alertError = document.getElementById('alert-error');
    const alertErrorText = document.getElementById('alert-error-text');
    const alertWarning = document.getElementById('alert-warning');

    if (btnLogin) {
        btnLogin.addEventListener('click', function () {
            // Hide alerts
            alertError.classList.add('hidden');
            alertWarning.classList.add('hidden');

            const email = emailInput.value.trim();
            const password = passwordInput.value.trim();

            // Basic validation
            if (!email || !password) {
                alertErrorText.textContent = 'Harap isi email dan kata sandi.';
                alertError.classList.remove('hidden');
                return;
            }

            if (!isValidEmail(email)) {
                alertErrorText.textContent = 'Format email tidak valid.';
                alertError.classList.remove('hidden');
                return;
            }

            // TODO: AJAX login ke API
            // fetch('/api/login', {
            //     method: 'POST',
            //     headers: {
            //         'Content-Type': 'application/json',
            //         'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
            //     },
            //     body: JSON.stringify({ email, password })
            // })
            // .then(res => res.json())
            // .then(data => {
            //     if (data.token) {
            //         localStorage.setItem('token', data.token);
            //         if (data.role === 'hr') {
            //             window.location.href = '/hr/dashboard';
            //         } else {
            //             window.location.href = '/pelamar/dashboard';
            //         }
            //     } else {
            //         alertErrorText.textContent = data.message;
            //         alertError.classList.remove('hidden');
            //     }
            // })
            // .catch(err => {
            //     alertErrorText.textContent = 'Terjadi kesalahan. Coba lagi nanti.';
            //     alertError.classList.remove('hidden');
            // });

            console.log('Login attempt:', { email, password });
            alert('Login berhasil! (demo - belum terhubung API)');
        });
    }

    // === Helper ===
    function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }
});

