/**
 * Pengalaman Kerja JS
 * Functional: add, edit, delete experience entries
 */

document.addEventListener('DOMContentLoaded', function () {

    const list = document.getElementById('experience-list');
    const emptyState = document.getElementById('empty-state');
    const modal = document.getElementById('modal-overlay');
    const modalTitle = document.getElementById('modal-title');
    let idCounter = 3;

    // ===== OPEN MODAL: TAMBAH =====
    document.getElementById('btn-tambah').addEventListener('click', function () {
        modalTitle.textContent = 'Tambah Pengalaman';
        document.getElementById('edit-id').value = '';
        document.getElementById('m-posisi').value = '';
        document.getElementById('m-perusahaan').value = '';
        document.getElementById('m-tipe').value = 'Full-Time';
        document.getElementById('m-mulai').value = '';
        document.getElementById('m-selesai').value = '';
        document.getElementById('m-sekarang').checked = false;
        document.getElementById('m-selesai').disabled = false;
        modal.classList.remove('hidden');
    });

    // ===== CLOSE MODAL =====
    document.getElementById('btn-modal-batal').addEventListener('click', () => modal.classList.add('hidden'));
    modal.addEventListener('click', (e) => { if (e.target === modal) modal.classList.add('hidden'); });

    // ===== CHECKBOX "Masih bekerja" =====
    document.getElementById('m-sekarang').addEventListener('change', function () {
        const selesaiInput = document.getElementById('m-selesai');
        selesaiInput.disabled = this.checked;
        if (this.checked) selesaiInput.value = '';
    });

    // ===== SIMPAN (ADD / EDIT) =====
    document.getElementById('btn-modal-simpan').addEventListener('click', function () {
        const editId = document.getElementById('edit-id').value;
        const posisi = document.getElementById('m-posisi').value.trim();
        const perusahaan = document.getElementById('m-perusahaan').value.trim();
        const tipe = document.getElementById('m-tipe').value;
        const mulai = document.getElementById('m-mulai').value;
        const selesai = document.getElementById('m-sekarang').checked ? 'Sekarang' : document.getElementById('m-selesai').value;

        if (!posisi || !perusahaan || !mulai) {
            alert('Posisi, Perusahaan, dan Tanggal Mulai wajib diisi.');
            return;
        }

        const mulaiFormatted = formatMonth(mulai);
        const selesaiFormatted = selesai === 'Sekarang' ? 'Sekarang' : formatMonth(selesai);

        if (editId) {
            // EDIT existing
            const card = list.querySelector('[data-id="' + editId + '"]');
            if (card) {
                card.querySelector('.exp-tipe').textContent = tipe.toUpperCase();
                card.querySelector('.exp-posisi').textContent = posisi;
                card.querySelector('.exp-perusahaan').textContent = perusahaan;
                card.querySelector('.exp-periode').textContent = mulaiFormatted + ' - ' + selesaiFormatted;
            }
        } else {
            // ADD new
            const newId = idCounter++;
            const cardHTML = `
                <div class="bg-white rounded-xl border border-gray-200 p-6 flex items-start justify-between" data-id="${newId}">
                    <div class="flex-1">
                        <span class="exp-tipe text-xs font-bold text-green-700 uppercase tracking-wider">${tipe.toUpperCase()}</span>
                        <h3 class="exp-posisi text-lg font-bold text-gray-900 mt-1">${posisi}</h3>
                        <div class="flex items-center gap-2 mt-2 text-sm text-gray-500">
                            <svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="20" height="14" x="2" y="7" rx="2" ry="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg>
                            <span class="exp-perusahaan">${perusahaan}</span>
                        </div>
                        <div class="flex items-center gap-2 mt-1 text-sm text-gray-500">
                            <svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="4" rx="2" ry="2"/><line x1="16" x2="16" y1="2" y2="6"/><line x1="8" x2="8" y1="2" y2="6"/><line x1="3" x2="21" y1="10" y2="10"/></svg>
                            <span class="exp-periode">${mulaiFormatted} - ${selesaiFormatted}</span>
                        </div>
                        <div class="flex gap-2 mt-4">
                            <button class="btn-edit flex items-center gap-1.5 px-4 py-1.5 border border-gray-300 rounded-lg text-sm text-gray-700 hover:bg-gray-50 transition-colors" data-id="${newId}">
                                <svg xmlns="http://www.w3.org/2000/svg" class="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg>
                                Edit
                            </button>
                            <button class="btn-hapus flex items-center gap-1.5 px-4 py-1.5 border border-gray-300 rounded-lg text-sm text-gray-700 hover:bg-red-50 hover:text-red-600 hover:border-red-300 transition-colors" data-id="${newId}">
                                <svg xmlns="http://www.w3.org/2000/svg" class="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>
                                Hapus
                            </button>
                        </div>
                    </div>
                    <div class="w-40 h-28 bg-gradient-to-br from-green-800 to-green-950 rounded-lg ml-6 shrink-0 flex items-center justify-center text-white/30 text-xs">Foto</div>
                </div>`;
            list.insertAdjacentHTML('beforeend', cardHTML);
            emptyState.classList.add('hidden');
        }

        modal.classList.add('hidden');
    });

    // ===== DELEGATED EVENTS: EDIT & HAPUS =====
    list.addEventListener('click', function (e) {
        const editBtn = e.target.closest('.btn-edit');
        const hapusBtn = e.target.closest('.btn-hapus');

        if (editBtn) {
            const card = editBtn.closest('[data-id]');
            const id = card.dataset.id;
            modalTitle.textContent = 'Edit Pengalaman';
            document.getElementById('edit-id').value = id;
            document.getElementById('m-posisi').value = card.querySelector('.exp-posisi')?.textContent || card.querySelector('h3').textContent;
            document.getElementById('m-perusahaan').value = card.querySelector('.exp-perusahaan')?.textContent || '';
            document.getElementById('m-tipe').value = 'Full-Time';
            modal.classList.remove('hidden');
        }

        if (hapusBtn) {
            if (confirm('Yakin ingin menghapus pengalaman ini?')) {
                const card = hapusBtn.closest('[data-id]');
                card.style.transition = 'opacity 0.3s, transform 0.3s';
                card.style.opacity = '0';
                card.style.transform = 'translateX(-20px)';
                setTimeout(() => {
                    card.remove();
                    if (list.children.length === 0) {
                        emptyState.classList.remove('hidden');
                    }
                }, 300);
            }
        }
    });

    // ===== HELPER =====
    function formatMonth(val) {
        if (!val) return '';
        const [y, m] = val.split('-');
        const months = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Ags','Sep','Okt','Nov','Des'];
        return months[parseInt(m) - 1] + ' ' + y;
    }
});

