/**
 * Pelamar Dashboard JS
 * Features: animated counters, greeting by time, table row click, stat card click
 */

document.addEventListener('DOMContentLoaded', function () {

    // ===== GREETING BY TIME OF DAY =====
    const nameEl = document.getElementById('user-name');
    const greetEl = nameEl?.closest('h1');
    if (greetEl) {
        const hour = new Date().getHours();
        let greeting = 'Halo';
        if (hour < 12) greeting = 'Selamat Pagi';
        else if (hour < 15) greeting = 'Selamat Siang';
        else if (hour < 18) greeting = 'Selamat Sore';
        else greeting = 'Selamat Malam';
        greetEl.innerHTML = greeting + ', <span id="user-name">Ahmad</span>!';
    }

    // ===== ANIMATED COUNTER =====
    function animateCounter(el, target, duration) {
        let start = 0;
        const step = Math.ceil(target / (duration / 16));
        const timer = setInterval(() => {
            start += step;
            if (start >= target) {
                start = target;
                clearInterval(timer);
            }
            el.textContent = start;
        }, 16);
    }

    const counters = {
        'stat-total': 12,
        'stat-aktif': 4,
        'stat-ditolak': 2,
        'stat-wawancara': 3
    };

    Object.entries(counters).forEach(([id, target]) => {
        const el = document.getElementById(id);
        if (el) {
            el.textContent = '0';
            setTimeout(() => animateCounter(el, target, 800), 300);
        }
    });

    // ===== STAT CARDS CLICKABLE =====
    document.querySelectorAll('.stat-card').forEach(card => {
        card.addEventListener('click', function () {
            window.location.href = '/pelamar/status-lamaran';
        });
    });

    // ===== TABLE ROWS CLICKABLE =====
    document.querySelectorAll('#lamaran-table tr').forEach(row => {
        row.style.cursor = 'pointer';
        row.addEventListener('click', () => {
            window.location.href = '/pelamar/status-lamaran';
        });
    });

    // ===== NOTIFICATION ITEMS: Mark as read on click =====
    document.querySelectorAll('#notifications > div').forEach(item => {
        item.style.cursor = 'pointer';
        item.addEventListener('click', function () {
            const dot = this.querySelector('.bg-blue-500');
            if (dot) {
                dot.classList.remove('bg-blue-500');
                dot.classList.add('bg-gray-300');
            }
        });
    });

    console.log('Dashboard loaded');
});

