    document.querySelectorAll('.filter-cat').forEach(cb => cb.checked = false);
    document.querySelectorAll('.filter-type').forEach(rb => rb.checked = false);
    document.querySelectorAll('.filter-loc').forEach(rb => rb.checked = false);
