/**
 * HR Dashboard JS
 */
document.addEventListener('DOMContentLoaded', function () {

    const MAX_HEIGHT = 140; // px — tinggi bar tertinggi (100%)

    // Data chart
    const chartData = {
        monthly: {
            labels: ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN'],
            values: [55, 72, 65, 88, 78, 100],
            activeIndex: 5
        },
        weekly: {
            labels: ['SEN', 'SEL', 'RAB', 'KAM', 'JUM', 'SAB'],
            values: [40, 60, 85, 55, 70, 45],
            activeIndex: 2
        }
    };

    let currentMode = 'monthly';

    const bars       = document.querySelectorAll('.chart-bar');
    const labels     = document.querySelectorAll('.chart-label');
    const btnMonthly = document.getElementById('btn-monthly');
    const btnWeekly  = document.getElementById('btn-weekly');

    function updateChart(mode) {
        const data = chartData[mode];
        const maxVal = Math.max(...data.values);

        bars.forEach((bar, i) => {
            const val    = data.values[i];
            const height = Math.round((val / maxVal) * MAX_HEIGHT);
            bar.style.height = height + 'px';

            // Update warna: bar tertinggi/aktif = hijau tua
            if (i === data.activeIndex) {
                bar.classList.remove('bg-green-200');
                bar.classList.add('bg-green-800');
            } else {
                bar.classList.remove('bg-green-800');
                bar.classList.add('bg-green-200');
            }

            // Tooltip title
            bar.setAttribute('title', data.labels[i] + ': ' + val + ' pelamar');
        });

        labels.forEach((lbl, i) => {
            lbl.textContent = data.labels[i];
            if (i === data.activeIndex) {
                lbl.classList.add('text-green-800');
                lbl.classList.remove('text-gray-400');
            } else {
                lbl.classList.remove('text-green-800');
                lbl.classList.add('text-gray-400');
            }
        });

        currentMode = mode;
    }

    // Toggle buttons
    function setActiveBtn(active, inactive) {
        active.classList.add('bg-white', 'text-gray-800', 'shadow-sm');
        active.classList.remove('text-gray-500');
        inactive.classList.remove('bg-white', 'text-gray-800', 'shadow-sm');
        inactive.classList.add('text-gray-500');
    }

    btnMonthly.addEventListener('click', function () {
        updateChart('monthly');
        setActiveBtn(btnMonthly, btnWeekly);
    });

    btnWeekly.addEventListener('click', function () {
        updateChart('weekly');
        setActiveBtn(btnWeekly, btnMonthly);
    });

    // ===== BAR TOOLTIP (hover popup) =====
