document.addEventListener('DOMContentLoaded', function () {

    // ===== WEEKLY TRENDS TOGGLE =====
    const btnMonth = document.getElementById('btn-last-month');
    const btnYear  = document.getElementById('btn-last-year');
    const chartLine = document.getElementById('chart-line');
    const chartArea = document.getElementById('chart-area');

    const paths = {
        month: {
            line: 'M 30 180 C 120 175, 180 170, 210 130 S 300 90, 390 85 S 500 70, 570 65',
            area: 'M 30 180 C 120 175, 180 170, 210 130 S 300 90, 390 85 S 500 70, 570 65 L 570 220 L 30 220 Z'
        },
        year: {
            line: 'M 30 100 C 120 60, 180 140, 210 110 S 300 170, 390 130 S 500 100, 570 40',
            area: 'M 30 100 C 120 60, 180 140, 210 110 S 300 170, 390 130 S 500 100, 570 40 L 570 220 L 30 220 Z'
        }
    };

    function setChart(mode) {
        chartLine.setAttribute('d', paths[mode].line);
        chartArea.setAttribute('d', paths[mode].area);
    }

    function activeBtn(on, off) {
        on.classList.add('bg-white', 'text-gray-800', 'shadow-sm');
        on.classList.remove('text-gray-500');
        off.classList.remove('bg-white', 'text-gray-800', 'shadow-sm');
        off.classList.add('text-gray-500');
    }

    btnMonth?.addEventListener('click', () => { setChart('month'); activeBtn(btnMonth, btnYear); });
    btnYear?.addEventListener('click',  () => { setChart('year');  activeBtn(btnYear,  btnMonth); });

    // ===== CHART DATA POINT TOOLTIP =====
    const tooltip = document.createElement('div');
    tooltip.className = 'fixed z-50 bg-green-900 text-white text-xs font-semibold px-3 py-1.5 rounded-lg shadow-lg pointer-events-none hidden';
    document.body.appendChild(tooltip);

    document.querySelectorAll('circle[data-week]').forEach(dot => {
        dot.addEventListener('mouseenter', function (e) {
            tooltip.textContent = this.dataset.week + ': ' + this.dataset.value + ' applicants';
            tooltip.classList.remove('hidden');
        });
        dot.addEventListener('mousemove', function (e) {
            tooltip.style.left = (e.clientX + 12) + 'px';
            tooltip.style.top  = (e.clientY - 34) + 'px';
        });
        dot.addEventListener('mouseleave', () => tooltip.classList.add('hidden'));
    });
});

