/**
 * HR Lowongan Detail JS
 */
document.addEventListener('DOMContentLoaded', function () {

    // ===== CHART DATA =====
    const datasets = {
        month: {
            labels: ['Week 1', 'Week 2', 'Week 3', 'Week 4'],
            values: [12, 28, 45, 52]
        },
        year: {
            labels: ['Q1', 'Q2', 'Q3', 'Q4'],
            values: [80, 120, 95, 145]
        }
    };

    const svg       = document.getElementById('trend-chart');
    const pathLine  = document.getElementById('chart-line');
    const pathArea  = document.getElementById('chart-area');
    const pointsG   = document.getElementById('chart-points');
    const btnMonth  = document.getElementById('btn-last-month');
    const btnYear   = document.getElementById('btn-last-year');

    const W = 600, H = 240;
    const padX = 40, padY = 30;
    const chartW = W - padX * 2;
    const chartH = H - padY * 2;

    // Convert data to points
    function dataToPoints(values) {
        const max = Math.max(...values);
        const min = Math.min(0, Math.min(...values));
        return values.map((v, i) => ({
            x: padX + (i * (chartW / (values.length - 1))),
            y: padY + chartH - ((v - min) / (max - min)) * chartH
        }));
    }

    // Smooth curve via cubic Bezier (Catmull-Rom to Bezier)
    function buildSmoothPath(pts) {
        if (pts.length < 2) return '';
        let d = `M ${pts[0].x} ${pts[0].y}`;
        for (let i = 0; i < pts.length - 1; i++) {
            const p0 = pts[i - 1] || pts[i];
            const p1 = pts[i];
            const p2 = pts[i + 1];
            const p3 = pts[i + 2] || p2;

            const cp1x = p1.x + (p2.x - p0.x) / 6;
            const cp1y = p1.y + (p2.y - p0.y) / 6;
            const cp2x = p2.x - (p3.x - p1.x) / 6;
            const cp2y = p2.y - (p3.y - p1.y) / 6;

            d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
        }
        return d;
    }

    let currentMode = 'month';

    // Tooltip element
    const tooltip = document.createElement('div');
    tooltip.className = 'fixed z-50 bg-green-900 text-white text-xs font-semibold px-3 py-1.5 rounded-lg shadow-lg pointer-events-none hidden';
    document.body.appendChild(tooltip);

    function renderChart(mode) {
        const data = datasets[mode];
        const pts  = dataToPoints(data.values);

        const linePath = buildSmoothPath(pts);
        const areaPath = linePath + ` L ${pts[pts.length - 1].x} ${H} L ${pts[0].x} ${H} Z`;

        pathLine.setAttribute('d', linePath);
        pathArea.setAttribute('d', areaPath);

        // Clear & rebuild points
        pointsG.innerHTML = '';
        pts.forEach((p, i) => {
            const halo = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            halo.setAttribute('cx', p.x);
            halo.setAttribute('cy', p.y);
            halo.setAttribute('r', '9');
            halo.setAttribute('fill', '#166534');
            halo.setAttribute('fill-opacity', '0.15');
            pointsG.appendChild(halo);

            const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            dot.setAttribute('cx', p.x);
            dot.setAttribute('cy', p.y);
            dot.setAttribute('r', '5');
            dot.setAttribute('fill', '#166534');
            dot.setAttribute('stroke', '#ffffff');
            dot.setAttribute('stroke-width', '2');
            dot.style.cursor = 'pointer';

            const label = data.labels[i];
            const value = data.values[i];

            dot.addEventListener('mouseenter', () => {
                dot.setAttribute('r', '7');
                tooltip.textContent = label + ': ' + value + ' applicants';
                tooltip.classList.remove('hidden');
            });
            dot.addEventListener('mousemove', e => {
                tooltip.style.left = (e.clientX + 12) + 'px';
                tooltip.style.top  = (e.clientY - 34) + 'px';
            });
            dot.addEventListener('mouseleave', () => {
                dot.setAttribute('r', '5');
                tooltip.classList.add('hidden');
            });

            pointsG.appendChild(dot);
        });

        // Update x-axis labels
        const labelsContainer = svg.parentElement.querySelector('.flex.justify-between');
        if (labelsContainer) {
            labelsContainer.innerHTML = data.labels.map(l =>
                `<span class="text-[10px] font-semibold text-gray-300 uppercase tracking-wider">${l}</span>`
            ).join('');
        }

        currentMode = mode;
    }

    function activeBtn(on, off) {
        on.classList.add('bg-white', 'text-gray-800', 'shadow-sm');
        on.classList.remove('text-gray-500');
        off.classList.remove('bg-white', 'text-gray-800', 'shadow-sm');
        off.classList.add('text-gray-500');
    }

    btnMonth?.addEventListener('click', () => { renderChart('month'); activeBtn(btnMonth, btnYear); });
    btnYear?.addEventListener('click',  () => { renderChart('year');  activeBtn(btnYear,  btnMonth); });

    // Initial render
    renderChart('month');
});

