/**
 * HR Pelamar List JS
 * - Collapsible lowongan cards
 * - Status tab filter per card
 * - Sort (recent / score / name)
 * - Global search
 * - Expand/Collapse all
 */
document.addEventListener('DOMContentLoaded', function () {

    // ===== COLLAPSIBLE LOWONGAN CARDS =====
    document.querySelectorAll('.lowongan-toggle').forEach(btn => {
        btn.addEventListener('click', function () {
            const card    = this.closest('.lowongan-card');
            const body    = card.querySelector('.lowongan-body');
            const chevron = this.querySelector('.lowongan-chevron');

            body.classList.toggle('hidden');
            card.classList.toggle('is-expanded');

            // Chevron rotation: right (0deg) when collapsed, down (90deg) when expanded
            if (card.classList.contains('is-expanded')) {
                chevron.style.transform = 'rotate(90deg)';
            } else {
                chevron.style.transform = 'rotate(0deg)';
            }
        });

        // Set initial chevron state
        const card    = btn.closest('.lowongan-card');
        const chevron = btn.querySelector('.lowongan-chevron');
        if (card.classList.contains('is-expanded')) {
            chevron.style.transform = 'rotate(90deg)';
        }
    });

    // ===== STATUS TABS (per card) =====
    document.querySelectorAll('.lowongan-card').forEach(card => {
        const tabs    = card.querySelectorAll('.status-tab');
        const rows    = card.querySelectorAll('.applicant-row');
        const emptyEl = card.querySelector('.applicant-empty');
        const countEl = card.querySelector('.filter-count');

        tabs.forEach(tab => {
            tab.addEventListener('click', function () {
                // Update active state
                tabs.forEach(t => {
                    t.classList.remove('active-tab', 'text-green-800', 'border-green-700');
                    t.classList.add('text-gray-500', 'border-transparent');
                });
                this.classList.add('active-tab', 'text-green-800', 'border-green-700');
                this.classList.remove('text-gray-500', 'border-transparent');

                // Filter rows
                const status = this.dataset.status;
                let visibleCount = 0;
                rows.forEach(row => {
                    const match = (status === 'all') || (row.dataset.status === status);
                    row.style.display = match ? '' : 'none';
                    if (match) visibleCount++;
                });

                // Empty state
                if (visibleCount === 0) {
                    emptyEl.classList.remove('hidden');
                } else {
                    emptyEl.classList.add('hidden');
                }

                if (countEl) countEl.textContent = visibleCount;
            });
        });

        // ===== SORT =====
        const sortSelect = card.querySelector('.sort-select');
        const tbody      = card.querySelector('.applicant-tbody');

        sortSelect?.addEventListener('change', function () {
            const rowsArray = Array.from(card.querySelectorAll('.applicant-row'));
            const mode = this.value;

            rowsArray.sort((a, b) => {
                if (mode === 'score-desc') return parseInt(b.dataset.score) - parseInt(a.dataset.score);
                if (mode === 'score-asc')  return parseInt(a.dataset.score) - parseInt(b.dataset.score);
                if (mode === 'name')       return a.dataset.name.localeCompare(b.dataset.name);
                // 'recent' = by date index
                return parseInt(a.dataset.dateIdx) - parseInt(b.dataset.dateIdx);
            });

            // Re-append in order
            rowsArray.forEach(r => tbody.appendChild(r));
            // Keep empty state at bottom
            if (emptyEl) tbody.appendChild(emptyEl);
        });
    });

    // ===== EXPAND ALL / COLLAPSE ALL =====
    document.getElementById('btn-expand-all').addEventListener('click', function () {
        document.querySelectorAll('.lowongan-card').forEach(card => {
            card.classList.add('is-expanded');
            card.querySelector('.lowongan-body').classList.remove('hidden');
            card.querySelector('.lowongan-chevron').style.transform = 'rotate(90deg)';
        });
    });

    document.getElementById('btn-collapse-all').addEventListener('click', function () {
        document.querySelectorAll('.lowongan-card').forEach(card => {
            card.classList.remove('is-expanded');
            card.querySelector('.lowongan-body').classList.add('hidden');
            card.querySelector('.lowongan-chevron').style.transform = 'rotate(0deg)';
        });
    });

    // ===== GLOBAL SEARCH =====
    document.getElementById('global-search').addEventListener('input', function () {
        const q = this.value.toLowerCase().trim();
        let anyVisible = false;

        document.querySelectorAll('.lowongan-card').forEach(card => {
            const titleMatch = card.dataset.title.includes(q);
            const rows       = card.querySelectorAll('.applicant-row');
            let matchedRows  = 0;

            rows.forEach(row => {
                const nameMatch = row.dataset.name.includes(q);
                if (!q || titleMatch || nameMatch) {
                    row.style.display = '';
                    matchedRows++;
                } else {
                    row.style.display = 'none';
                }
            });

            // Show/hide whole card
            if (!q || titleMatch || matchedRows > 0) {
                card.style.display = '';
                anyVisible = true;

                // Auto-expand card if search matched applicants in it
                if (q && matchedRows > 0 && !titleMatch) {
                    card.classList.add('is-expanded');
                    card.querySelector('.lowongan-body').classList.remove('hidden');
                    card.querySelector('.lowongan-chevron').style.transform = 'rotate(90deg)';
                }
            } else {
                card.style.display = 'none';
            }
        });

        // Empty result
        const emptyResult = document.getElementById('empty-result');
        if (q && !anyVisible) {
            emptyResult.classList.remove('hidden');
        } else {
            emptyResult.classList.add('hidden');
        }
    });

    // ===== EXPORT CSV (demo) =====
    document.getElementById('btn-export').addEventListener('click', function () {
        this.innerHTML = '<svg class="w-4 h-4 animate-spin inline" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg> Mengekspor...';
        setTimeout(() => {
            this.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Berhasil';
            this.classList.add('text-green-700', 'border-green-300', 'bg-green-50');
            setTimeout(() => {
                this.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg> Export CSV';
                this.classList.remove('text-green-700', 'border-green-300', 'bg-green-50');
            }, 1500);
        }, 1200);
    });
});

