/**
 * HR Pelamar List JS
 * Fitur:
 * - Collapsible cards + chevron rotate
 * - Status tabs per card
 * - Sort per card (recent/score/name)
 * - Smart search (nama pelamar, email, posisi) dengan auto-expand + highlight
 * - Quick filter global (Perlu Review, Sedang Interview, Butuh Keputusan, Ditolak)
 * - Department filter
 * - Sort lowongan (paling banyak / deadline / recent / nama)
 * - Expand All / Collapse All
 * - Active filter indicator
 */
document.addEventListener('DOMContentLoaded', function () {

    const container   = document.getElementById('lowongan-container');
    const emptyResult = document.getElementById('empty-result');
    const activeFilterBar = document.getElementById('active-filter-bar');
    const activeFilterTag = document.getElementById('active-filter-tag');

    // State
    let currentQuickFilter = 'all';
    let currentDepartment  = '';
    let currentSearch      = '';

    // ===== COLLAPSIBLE =====
    function setCardExpanded(card, expanded) {
        const body    = card.querySelector('.lowongan-body');
        const chevron = card.querySelector('.lowongan-chevron');
        if (expanded) {
            card.classList.add('is-expanded');
            body.classList.remove('hidden');
            chevron.style.transform = 'rotate(90deg)';
        } else {
            card.classList.remove('is-expanded');
