import { useState } from "react";

const days = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"];

const mealPlan = [
  {
    day: "Senin",
    pagi: { menu: "Nasi + Telur Dadar Kecap", icon: "🍳", tags: ["telur"] },
    siang: { menu: "Nasi + Tempe Goreng + Tumis Bayam", icon: "🌿", tags: ["tempe"] },
    sore: { menu: "Mie Goreng + Telur Ceplok", icon: "🍜", tags: ["mie", "telur"] },
  },
  {
    day: "Selasa",
    pagi: { menu: "Nasi + Tahu Goreng + Sambal Kecap", icon: "🟡", tags: ["tahu"] },
    siang: { menu: "Nasi + Telur Balado + Tumis Kangkung", icon: "🥬", tags: ["telur"] },
    sore: { menu: "Nasi + Tempe Orek + Kerupuk", icon: "🍚", tags: ["tempe"] },
  },
  {
    day: "Rabu",
    pagi: { menu: "Nasi + Telur Rebus + Kecap Asin", icon: "🥚", tags: ["telur"] },
    siang: { menu: "Nasi + Kentang Goreng + Tahu Bacem", icon: "🥔", tags: ["kentang", "tahu"] },
    sore: { menu: "Mie Rebus + Tahu Goreng + Sawi", icon: "🍜", tags: ["mie", "tahu"] },
  },
  {
    day: "Kamis",
    pagi: { menu: "Nasi + Tempe Goreng + Sambal Bawang", icon: "🌶️", tags: ["tempe"] },
    siang: { menu: "Nasi + Telur Dadar + Tumis Wortel", icon: "🥕", tags: ["telur"] },
    sore: { menu: "Nasi + Kentang Balado + Tahu Putih", icon: "🔥", tags: ["kentang", "tahu"] },
  },
  {
    day: "Jumat",
    pagi: { menu: "Nasi + Tahu Tempe Goreng Campur", icon: "🍱", tags: ["tahu", "tempe"] },
    siang: { menu: "Mie Goreng + Telur + Sawi Hijau", icon: "🍜", tags: ["mie", "telur"] },
    sore: { menu: "Nasi + Telur Ceplok Kecap + Kerupuk", icon: "🥚", tags: ["telur"] },
  },
  {
    day: "Sabtu",
    pagi: { menu: "Nasi + Telur Rebus + Tempe Krispi", icon: "✨", tags: ["telur", "tempe"] },
    siang: { menu: "Nasi + Kentang Tumis Bawang + Tahu", icon: "🧅", tags: ["kentang", "tahu"] },
    sore: { menu: "Mie Kuah + Telur Rebus + Sayuran", icon: "🍜", tags: ["mie", "telur"] },
  },
  {
    day: "Minggu",
    pagi: { menu: "Nasi + Tempe Bacem + Kecap Manis", icon: "🍯", tags: ["tempe"] },
    siang: { menu: "Nasi + Telur Balado + Tumis Kangkung", icon: "🌶️", tags: ["telur"] },
    sore: { menu: "Nasi + Tahu Goreng + Kentang Rebus", icon: "🥔", tags: ["tahu", "kentang"] },
  },
];

const belanja = [
  { item: "Beras 2 kg", harga: 28000 },
  { item: "Telur 1/2 kg (±8 butir)", harga: 14000 },
  { item: "Tahu 10 potong", harga: 10000 },
  { item: "Tempe 2 papan", harga: 10000 },
  { item: "Kentang 500 gr", harga: 10000 },
  { item: "Mie Instan 6 bungkus", harga: 18000 },
  { item: "Sayuran (bayam, kangkung, wortel, sawi)", harga: 20000 },
  { item: "Minyak goreng 250 ml", harga: 10000 },
  { item: "Bumbu dapur (bawang, cabe, garam)", harga: 15000 },
  { item: "Kecap & kerupuk", harga: 10000 },
];

const tagColor = {
  telur: "#f59e0b",
  tahu: "#84cc16",
  tempe: "#f97316",
  kentang: "#a78bfa",
  mie: "#38bdf8",
};

const mealLabels = {
  pagi: { label: "Pagi", emoji: "🌅", color: "#fde68a" },
  siang: { label: "Siang", emoji: "☀️", color: "#bbf7d0" },
  sore: { label: "Sore", emoji: "🌇", color: "#fecaca" },
};

export default function MealPlan() {
  const [activeDay, setActiveDay] = useState(0);
  const [showBelanja, setShowBelanja] = useState(false);
  const totalBelanja = belanja.reduce((a, b) => a + b.harga, 0);

  const current = mealPlan[activeDay];

  return (
    <div style={{
      minHeight: "100vh",
      background: "linear-gradient(135deg, #fff7ed 0%, #fef9ee 50%, #f0fdf4 100%)",
      fontFamily: "'Georgia', serif",
      padding: "24px 16px",
    }}>
      {/* Header */}
      <div style={{ textAlign: "center", marginBottom: 28 }}>
        <div style={{
          display: "inline-block",
          background: "#15803d",
          color: "white",
          borderRadius: 999,
          padding: "4px 18px",
          fontSize: 12,
          letterSpacing: 2,
          fontFamily: "monospace",
          marginBottom: 8,
        }}>BUDGET Rp150.000 / MINGGU</div>
        <h1 style={{
          fontSize: 28,
          fontWeight: 900,
          color: "#14532d",
          margin: "0 0 4px",
          letterSpacing: -1,
        }}>🍽️ Jadwal Makan Mingguan</h1>
        <p style={{ color: "#6b7280", fontSize: 13, margin: 0 }}>
          3x sehari · Hemat · Bergizi · Mudah dimasak
        </p>
      </div>

      {/* Day Selector */}
      <div style={{
        display: "flex",
        gap: 6,
        overflowX: "auto",
        paddingBottom: 8,
        marginBottom: 20,
        scrollbarWidth: "none",
      }}>
        {days.map((d, i) => (
          <button key={d} onClick={() => setActiveDay(i)} style={{
            flexShrink: 0,
            padding: "8px 14px",
            borderRadius: 999,
            border: "2px solid",
            borderColor: activeDay === i ? "#15803d" : "#d1fae5",
            background: activeDay === i ? "#15803d" : "white",
            color: activeDay === i ? "white" : "#15803d",
            fontWeight: 700,
            fontSize: 13,
            cursor: "pointer",
            transition: "all 0.2s",
            fontFamily: "inherit",
          }}>{d}</button>
        ))}
      </div>

      {/* Meal Cards */}
      <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 24 }}>
        {(["pagi", "siang", "sore"]).map(waktu => {
          const meal = current[waktu];
          const meta = mealLabels[waktu];
          return (
            <div key={waktu} style={{
              background: "white",
              borderRadius: 16,
              padding: "16px 18px",
              boxShadow: "0 2px 12px rgba(0,0,0,0.07)",
              borderLeft: `5px solid ${meta.color}`,
              display: "flex",
              alignItems: "center",
              gap: 14,
            }}>
              <div style={{
                width: 48, height: 48,
                borderRadius: 14,
                background: meta.color,
                display: "flex", alignItems: "center", justifyContent: "center",
                fontSize: 22, flexShrink: 0,
              }}>{meta.emoji}</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 11, color: "#9ca3af", fontWeight: 700, letterSpacing: 1, marginBottom: 2, fontFamily: "monospace" }}>
                  {meta.label.toUpperCase()}
                </div>
                <div style={{ fontSize: 15, fontWeight: 700, color: "#1c1917", marginBottom: 6 }}>
                  {meal.icon} {meal.menu}
                </div>
                <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
                  {meal.tags.map(tag => (
                    <span key={tag} style={{
                      background: tagColor[tag] + "22",
                      color: tagColor[tag],
                      border: `1px solid ${tagColor[tag]}55`,
                      borderRadius: 999,
                      padding: "1px 8px",
                      fontSize: 11,
                      fontWeight: 700,
                      fontFamily: "monospace",
                    }}>{tag}</span>
                  ))}
                </div>
              </div>
            </div>
