# M5-tugas2-stack.py
# Program untuk memeriksa pasangan kurung '()', '[]', '{}'
# menggunakan struktur data Stack

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        return None

    def is_empty(self):
        return len(self.items) == 0

    def peek(self):
        if not self.is_empty():
            return self.items[-1]
        return None


def cek_kurung(ekspresi):
    stack = Stack()

    # Dictionary pasangan kurung: kurung tutup -> kurung buka
    pasangan = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    kurung_buka = set(['(', '[', '{'])
    kurung_tutup = set([')', ']', '}'])

    for char in ekspresi:
        if char in kurung_buka:
            # Jika karakter adalah kurung buka, PUSH ke stack
            stack.push(char)
        elif char in kurung_tutup:
            # Jika karakter adalah kurung tutup, periksa stack
            if stack.is_empty():
                # Tidak ada kurung buka yang cocok
                return "SALAH"
            top = stack.pop()
            if top != pasangan[char]:
                # Kurung buka di stack tidak cocok dengan kurung tutup
                return "SALAH"

    # Setelah semua karakter ditelusuri, periksa isi stack
    if stack.is_empty():
        return "BENAR"
    else:
        return "SALAH"


# === Program Utama ===
